3	/// Why a connection stopped at the compatibility gate, and whether the app can do
4	/// anything about it.
5	public struct DaemonUpdateRequirement: Equatable, Sendable {
6	    public let reported: String
7	    public let minimum: String
8	    /// `/update/*` is mounted only under `--wireless-version`. A Lite robot cannot be
9	    /// updated over the network at all — it needs the desktop app over USB — so the
10	    /// screen has to offer an explanation rather than a button.
11	    public let canSelfUpdate: Bool
12	
13	    public init(reported: String, minimum: String, canSelfUpdate: Bool) {
14	        self.reported = reported
15	        self.minimum = minimum
16	        self.canSelfUpdate = canSelfUpdate
17	    }
18	}
