20	/// What `GET /update/available` says about the robot's own software.
21	public enum DaemonUpdateAvailability: Sendable, Equatable {
22	    case upToDate(current: String)
23	    case available(current: String, latest: String)
24	    /// The daemon answered but could not reach PyPI, reporting the literal string
25	    /// `"unknown"` as the available version. The robot's connectivity is at fault,
26	    /// not the request — telling the user the check failed would send them looking
27	    /// in the wrong place.
28	    case robotOffline(current: String)
29	
30	    public var currentVersion: String {
31	        switch self {
32	        case let .upToDate(current), let .available(current, _), let .robotOffline(current):
33	            current
34	        }
35	    }
36	
37	    /// Decodes the daemon's doubly-nested payload:
38	    /// `{"update": {"reachy_mini": {"is_available", "current_version", "available_version"}}}`.
39	    struct Response: Decodable {
40	        struct Package: Decodable {
41	            let isAvailable: Bool
42	            let currentVersion: String
43	            let availableVersion: String
44	
45	            enum CodingKeys: String, CodingKey {
46	                case isAvailable = "is_available"
47	                case currentVersion = "current_version"
48	                case availableVersion = "available_version"
49	            }
50	        }
51	
52	        let update: [String: Package]
53	
54	        /// The daemon keys the map by distribution name; `reachy_mini` is the only
55	        /// one it ever reports, but reading the sole value survives a rename.
56	        var availability: DaemonUpdateAvailability? {
57	            guard let package = update["reachy_mini"] ?? update.values.first else { return nil }
58	            if package.availableVersion == "unknown" {
59	                return .robotOffline(current: package.currentVersion)
60	            }
61	            return package.isAvailable
62	                ? .available(current: package.currentVersion, latest: package.availableVersion)
63	                : .upToDate(current: package.currentVersion)
64	        }
65	    }
66	}
