68	/// A background job on the daemon — here, always `update_reachy_mini`.
69	public struct DaemonUpdateJob: Sendable, Equatable, Decodable {
70	    /// An unrecognised value decodes to `.unknown` rather than throwing: the daemon
71	    /// versions independently of this app, and a job whose status stopped parsing
72	    /// must not read as a failed update. The socket closing is the real end signal.
73	    public enum Status: Sendable, Equatable, Decodable {
74	        case pending
75	        case inProgress
76	        case done
77	        case failed
78	        case unknown(String)
79	
80	        public init(from decoder: any Decoder) throws {
81	            switch try decoder.singleValueContainer().decode(String.self) {
82	            case "pending": self = .pending
83	            case "in_progress": self = .inProgress
84	            case "done": self = .done
85	            case "failed": self = .failed
86	            case let other: self = .unknown(other)
87	            }
88	        }
89	
90	        public var isTerminal: Bool {
91	            self == .done || self == .failed
92	        }
93	    }
94	
95	    public let command: String
96	    public let status: Status
97	    public let logs: [String]
98	
99	    public init(command: String, status: Status, logs: [String]) {
100	        self.command = command
101	        self.status = status
102	        self.logs = logs
103	    }
104	}
