3	/// The daemon's self-update surface.
4	///
5	/// Deliberately separate from `RobotAPIClient`: these routes are mounted only when
6	/// the daemon runs with `--wireless-version`, they sit outside the `/api` prefix, and
7	/// they are absent from `openapi.json` (the committed spec is generated without that
8	/// flag), so the generated client cannot reach them. Folding them into the connection
9	/// surface would also hand every existing test double three more methods to stub.
10	public protocol DaemonUpdateClient: Sendable {
11	    func availableUpdate(preRelease: Bool) async throws -> DaemonUpdateAvailability
12	    /// Returns the job id to follow over `UpdateLogStreamClient`.
13	    func startUpdate(preRelease: Bool) async throws -> String
14	    func updateInfo(jobID: String) async throws -> DaemonUpdateJob
15	}
16	
17	/// Defaults keep test doubles focused on the behaviour they exercise.
18	public extension DaemonUpdateClient {
19	    func availableUpdate(preRelease _: Bool) async throws -> DaemonUpdateAvailability {
20	        throw URLError(.unsupportedURL)
21	    }
22	
23	    func startUpdate(preRelease _: Bool) async throws -> String {
24	        throw URLError(.unsupportedURL)
25	    }
26	
27	    func updateInfo(jobID _: String) async throws -> DaemonUpdateJob {
28	        throw URLError(.unsupportedURL)
29	    }
30	}
