3	/// One message from `ws://…/update/ws/logs?job_id=…`.
4	public enum UpdateLogEvent: Sendable, Equatable {
5	    case line(String)
6	    case status(DaemonUpdateJob.Status)
7	    /// The daemon does not know this job — always the first and only frame.
8	    case rejected(String)
9	    /// The socket ended. This, not a `done` status, is what completion looks like:
10	    /// the update finishes by restarting the daemon, which kills the process before
11	    /// the terminal frame is ever written.
12	    case closed
13	}
14	
15	/// Streams one update job's log from `ws://…/update/ws/logs?job_id=…`.
16	///
17	/// Two deliberate differences from `LogStreamClient`:
18	///
19	/// - **No reconnect.** The job ends with `systemctl restart reachy-mini-daemon`, and
20	///   the in-memory job register dies with the process. Reconnecting would hammer a
21	///   daemon that is rebooting and could never find the job again afterwards.
22	/// - **Two frame shapes on one socket.** `bg_job_register.ws_poll_info` sends each new
23	///   line as its own text frame and *then* a `JobInfo` JSON frame repeating those same
24	///   lines. Decoding both would duplicate every line, so a frame that parses as JSON
25	///   contributes only its status.
26	public struct UpdateLogStreamClient: Sendable {
27	    public static let path = "/update/ws/logs"
28	
29	    private let url: URL
30	    private let session: URLSession
31	
32	    public init(address: RobotAddress, jobID: String, session: URLSession = .shared) throws {
33	        guard let url = address.webSocketURL(
34	            path: Self.path,
35	            queryItems: [URLQueryItem(name: "job_id", value: jobID)]
36	        ) else {
37	            throw ReachyKitError.invalidAddress(address)
38	        }
39	        self.url = url
40	        self.session = session
41	    }
42	
43	    /// Ends with exactly one `.closed`, whether the daemon finished, restarted or died.
44	    public func events() -> AsyncStream<UpdateLogEvent> {
45	        let (stream, continuation) = AsyncStream.makeStream(
46	            of: UpdateLogEvent.self,
47	            bufferingPolicy: .bufferingNewest(1000)
48	        )
49	        let task = Task { [url, session] in
50	            let socket = session.webSocketTask(with: url)
51	            socket.resume()
52	            defer {
53	                socket.cancel(with: .goingAway, reason: nil)
54	                continuation.yield(.closed)
55	                continuation.finish()
56	            }
57	            while !Task.isCancelled {
58	                guard let message = try? await socket.receive() else { return }
59	                guard case let .string(text) = message else { continue }
60	                for event in Self.events(in: text) {
61	                    continuation.yield(event)
62	                    if case .rejected = event {
63	                        return
64	                    }
65	                }
66	            }
67	        }
68	        continuation.onTermination = { _ in task.cancel() }
69	        return stream
70	    }
71	
72	    /// A frame is either a raw log line or one of the two JSON shapes the daemon sends.
73	    static func events(in frame: String) -> [UpdateLogEvent] {
74	        struct Rejection: Decodable {
75	            let error: String
76	        }
77	        guard let data = frame.data(using: .utf8) else {
78	            return [.line(frame)]
79	        }
80	        if let rejection = try? JSONDecoder().decode(Rejection.self, from: data) {
81	            return [.rejected(rejection.error)]
82	        }
83	        if let job = try? JSONDecoder.reachyDaemon.decode(DaemonUpdateJob.self, from: data) {
84	            // `job.logs` repeats lines already delivered as their own frames.
85	            return [.status(job.status)]
86	        }
87	        return [.line(frame)]
88	    }
89	}
