5	/// Owns the HTTP client for one robot daemon and performs the connection handshake.
6	///
7	/// The handshake establishes robot identity (hardware id, display name) and daemon
8	/// version before anything else — the version drives graceful degradation, and the
9	/// hardware id is the only safe way to deduplicate robots seen at several addresses.
10	public actor RobotConnection {
11	    public let address: RobotAddress
12	    private let client: Client
13	    /// The readiness probe reads a status code, never a body, so it deliberately
14	    /// bypasses the generated client. It also gets upstream's 10 s budget rather
15	    /// than the 3.5 s tuned for the 3 s status poll.
16	    private let readinessSession: URLSession
17	    /// Mesh downloads run to tens of megabytes; the 3.5 s health-poll budget would
18	    /// abort them, so they get their own session.
19	    private let assetSession: URLSession
20	    /// `/update/*` and `/wifi/*` are answered by the robot only after it has talked to
21	    /// PyPI or driven `nmcli`, so they need a far longer budget than the health poll.
22	    /// Not `private`: the routes live in `RobotConnection+Wireless`, a sibling file.
23	    let wirelessSession: URLSession
24	
25	    public init(address: RobotAddress, session: URLSession? = nil) throws {
26	        guard let serverURL = address.rootURL else {
27	            throw ReachyKitError.invalidAddress(address)
28	        }
29	        self.address = address
30	
31	        func makeSession(timeout: TimeInterval, resourceTimeout: TimeInterval? = nil) -> URLSession {
32	            // An injected session belongs to a test harness — reuse it so stubbed
33	            // protocols still intercept every request.
34	            if let session {
35	                return session
36	            }
37	            let configuration = URLSessionConfiguration.ephemeral
38	            configuration.timeoutIntervalForRequest = timeout
39	            if let resourceTimeout {
40	                configuration.timeoutIntervalForResource = resourceTimeout
41	            }
42	            return URLSession(configuration: configuration)
43	        }
44	
45	        client = Client(
46	            serverURL: serverURL,
47	            transport: URLSessionTransport(configuration: .init(session: makeSession(timeout: 3.5)))
48	        )
49	        readinessSession = makeSession(timeout: 10)
50	        assetSession = makeSession(timeout: 20, resourceTimeout: 120)
51	        wirelessSession = makeSession(timeout: 15)
52	    }
53	
54	    /// Result of a successful handshake with the daemon.
55	    public struct Handshake: Sendable {
56	        public let identity: RobotIdentity
57	        public let status: Components.Schemas.DaemonStatus
58	        public let compatibility: DaemonCompatibility
59	
60	        public init(
61	            identity: RobotIdentity,
62	            status: Components.Schemas.DaemonStatus,
63	            compatibility: DaemonCompatibility? = nil
64	        ) {
65	            self.identity = identity
66	            self.status = status
67	            self.compatibility = compatibility ?? DaemonCompatibilityPolicy.evaluate(identity.daemonVersion)
68	        }
69	    }
70	
71	    /// An unsupported version is reported, not thrown. The daemon's own update route
72	    /// is the way out of that state, and throwing here left the user on a "Try again"
73	    /// button that could never work. `RobotSession` gates the command surface on the
74	    /// verdict instead — see ADR 0001.
75	    public func handshake() async throws -> Handshake {
76	        let status = try await daemonStatus()
77	        let compatibility = DaemonCompatibilityPolicy.evaluate(status.version)
78	        let hardwareID = await hardwareID(reportedIn: status)
79	        let name = try? await client.getRobotDisplayNameApiDaemonRobotNameGet().ok.body.json.name
80	
81	        return Handshake(
82	            identity: RobotIdentity(
83	                hardwareID: hardwareID,
84	                name: name ?? status.robotName,
85	                daemonVersion: status.version
86	            ),
87	            status: status,
88	            compatibility: compatibility
89	        )
90	    }
91	
92	    /// The one value the daemon files under `hardware_id` — `sha256(usb serial)[:16]`.
93	    ///
94	    /// It must reach `RobotIdentity` unreshaped: the same string is what the robot
95	    /// hands out over BLE and advertises as the mDNS `unit_id`, so a robot provisioned
96	    /// over Bluetooth is recognised on the LAN by comparing it. The status payload
97	    /// already carries it; the dedicated route covers daemons that leave it out. A
98	    /// daemon with no robot attached answers `{"hardware_id": null}`, which the
99	    /// generated `[String: String]` map rejects — that is "no hardware id", not a
100	    /// failed handshake.
101	    private func hardwareID(reportedIn status: Components.Schemas.DaemonStatus) async -> String? {
102	        if let reported = status.hardwareId, !reported.isEmpty {
103	            return reported
104	        }
105	        let map = try? await client.getRobotHardwareIdApiDaemonHardwareIdGet()
106	            .ok.body.json.additionalProperties
107	        return map?["hardware_id"].flatMap { $0.isEmpty ? nil : $0 }
108	    }
109	
110	    /// One-shot full state via REST — fallback only; prefer `StateStreamClient`.
111	    public func fullState() async throws -> Components.Schemas.FullState {
112	        switch try await client.getFullStateApiStateFullGet() {
113	        case let .ok(response):
114	            return try response.body.json
115	        case .unprocessableContent:
116	            throw ReachyKitError.daemonRejected(statusCode: 422)
117	        case let .undocumented(statusCode, _):
118	            throw ReachyKitError.fromStatusCode(statusCode)
119	        }
120	    }
121	
122	    /// The readiness gate. `daemonStatus().state == .running` flips before the
123	    /// backend finishes coming up; this route is guarded by the daemon's
124	    /// `get_backend`, which answers 503 until `backend.ready` is set — so a 200
125	    /// here is the first honest "the robot can be driven" signal.
126	    ///
127	    /// Only the status code carries that signal, so the body is never decoded:
128	    /// going through the generated client made readiness depend on whether our
129	    /// schema could parse the payload, and a live daemon serves `last_alive` in a
130	    /// format the generated ISO-8601 date decoder rejects — a ready robot then
131	    /// looked like a failed connection.
132	    public func probeBackendReady() async throws {
133	        guard let url = address.httpURL(path: "/api/state/full") else {
134	            throw ReachyKitError.invalidAddress(address)
135	        }
136	        var request = URLRequest(url: url)
137	        request.httpMethod = "GET"
138	        let (_, response) = try await readinessSession.data(for: request)
139	        guard let http = response as? HTTPURLResponse else {
140	            throw ReachyKitError.daemonRejected(statusCode: -1)
141	        }
142	        guard (200 ..< 300).contains(http.statusCode) else {
143	            throw ReachyKitError.fromStatusCode(http.statusCode)
144	        }
145	    }
