3	/// The daemon surface `RobotSession` needs — abstracted so session logic is
4	/// testable without a network.
5	public protocol RobotAPIClient: Sendable {
6	    func handshake() async throws -> RobotConnection.Handshake
7	    func daemonStatus() async throws -> Components.Schemas.DaemonStatus
8	    func probeBackendReady() async throws
9	    func wakeUp() async throws -> String
10	    func gotoSleep() async throws -> String
11	    func setRobotName(_ name: String) async throws -> String
12	    func setMotorMode(_ mode: Components.Schemas.MotorControlMode) async throws
13	    func startDaemon(wakeUp: Bool) async throws
14	    func listMoves(dataset: String) async throws -> [String]
