6	/// Provisioning is not here. Handing over a password is `WiFiProvisioningTransport`, which
7	/// works over Bluetooth too; these are the routes that only make sense once the robot is
8	/// already reachable.
9	public extension RobotSession {
10	    /// False on a Lite robot, which never mounts `/wifi/*`.
