2	
3	/// The daemon's self-update surface, reached through the session so the UI never
4	/// builds a URL of its own.
5	///
6	/// Deliberately not guarded by `assertSupportedDaemon()`: updating is precisely what
7	/// an unsupported daemon is for. ADR 0001 bars the *command* surface, and version
8	/// negotiation is not part of it.
9	public extension RobotSession {
10	    /// False on a Lite robot, which never mounts `/update/*`.
11	    var canUpdateDaemon: Bool {
12	        client is any DaemonUpdateClient && supportsWirelessFeatures
13	    }
14	
15	    func availableUpdate(preRelease: Bool) async throws -> DaemonUpdateAvailability {
16	        try await withUpdateClient { try await $0.availableUpdate(preRelease: preRelease) }
17	    }
18	
19	    /// Returns the job id whose log `updateLog(jobID:)` streams.
20	    func startUpdate(preRelease: Bool) async throws -> String {
21	        try await withUpdateClient { try await $0.startUpdate(preRelease: preRelease) }
22	    }
23	
24	    func updateLog(jobID: String) throws -> AsyncStream<UpdateLogEvent> {
25	        guard let address else { throw ReachyKitError.notConnected }
26	        return try UpdateLogStreamClient(address: address, jobID: jobID).events()
27	    }
28	
29	    /// Waits out the `systemctl restart` an update ends with and reports the version
30	    /// the daemon came back on.
31	    ///
32	    /// This is the only honest completion signal: the restart kills the process — and
33	    /// the in-memory job register with it — before the terminal `done` frame is ever
34	    /// written, so neither the socket nor `/update/info` can confirm success. `nil`
35	    /// means the daemon never answered again.
36	    func reconnectAfterUpdate(
37	        timeout: Duration = .seconds(120),
38	        pollInterval: Duration = .seconds(3)
39	    ) async -> String? {
40	        guard let address else { return nil }
41	        let deadline = ContinuousClock.now + timeout
42	        while ContinuousClock.now < deadline, !Task.isCancelled {
43	            try? await Task.sleep(for: pollInterval)
44	            if await connect(to: address), let version = lastStatus?.version {
45	                return version
46	            }
47	            // A halted attempt still read the status, so an update that landed but
48	            // stayed below the baseline reports its real version rather than nothing.
49	            if case .connecting(.needsDaemonUpdate) = phase, let version = lastStatus?.version {
50	                return version
51	            }
52	        }
53	        return nil
54	    }
55	}
56	
