58	    func withUpdateClient<T>(_ call: (any DaemonUpdateClient) async throws -> T) async throws -> T {
59	        guard let client else { throw ReachyKitError.notConnected }
60	        guard let updateClient = client as? any DaemonUpdateClient else {
61	            throw ReachyKitError.wirelessFeaturesUnavailable
62	        }
63	        do {
64	            let result = try await call(updateClient)
65	            lastError = nil
66	            return result
67	        } catch {
68	            lastError = Self.describe(error)
69	            throw error
70	        }
71	    }
72	}
