1	import Foundation
2	
3	/// Serves canned HTTP responses to a `URLSession` injected into `RobotConnection`,
4	/// which is the only way to exercise daemon status codes without a daemon.
5	///
6	/// Stubs bind to the session that carries them, not to a global table: `swift test
7	/// --parallel` runs separate suites concurrently, so a shared table lets one suite
8	/// answer another suite's requests, or wipe them mid-flight. `.serialized` is no
9	/// defence — it orders tests within one suite and says nothing about the others.
10	final class StubURLProtocol: URLProtocol {
11	    struct Stub: Sendable {
12	        let statusCode: Int
13	        let body: Data
14	
15	        init(statusCode: Int, json: String = "{}") {
16	            self.statusCode = statusCode
17	            body = Data(json.utf8)
18	        }
19	    }
20	
21	    /// Routes are keyed by path, optionally narrowed by a query:
22	    /// `/update/available` answers whatever the query is, while
23	    /// `/update/available?pre_release=true` answers only that one. The narrower key
24	    /// wins, so a table can pin one variant and let the bare path cover the rest —
25	    /// without it, `pre_release=true` and `false` collapse onto a single stub.
26	    static func makeSession(_ stubs: [String: Stub]) -> URLSession {
27	        let token = UUID().uuidString
28	        lock.withLock { sessions[token] = stubs }
29	
30	        let configuration = URLSessionConfiguration.ephemeral
31	        configuration.protocolClasses = [StubURLProtocol.self]
32	        configuration.httpAdditionalHeaders = [tokenHeader: token]
33	        return URLSession(configuration: configuration)
34	    }
35	
36	    /// What this session was actually asked for, in order. The sealed Wi-Fi payload is
37	    /// the reason this exists: a test has to be able to prove the password never
38	    /// appeared in a URL.
39	    static func requests(for session: URLSession) -> [URLRequest] {
40	        guard let token = session.configuration.httpAdditionalHeaders?[tokenHeader] as? String else {
41	            return []
42	        }
43	        return lock.withLock { served[token] ?? [] }
44	    }
45	
46	    private static let tokenHeader = "X-Stub-Session"
47	    private nonisolated(unsafe) static var sessions: [String: [String: Stub]] = [:]
48	    private nonisolated(unsafe) static var served: [String: [URLRequest]] = [:]
49	    private static let lock = NSLock()
50	
51	    private static func record(_ request: URLRequest) {
52	        guard let token = request.value(forHTTPHeaderField: tokenHeader) else { return }
53	        lock.withLock { served[token, default: []].append(request) }
54	    }
55	
56	    private static func stub(for request: URLRequest) -> Stub? {
57	        guard let token = request.value(forHTTPHeaderField: tokenHeader),
58	              let url = request.url,
59	              let table = lock.withLock({ sessions[token] })
60	        else { return nil }
61	
62	        if let query = url.query(), let narrow = table["\(url.path)?\(query)"] {
63	            return narrow
64	        }
65	        return table[url.path]
66	    }
67	
68	    override static func canInit(with _: URLRequest) -> Bool {
69	        true
70	    }
71	
72	    override static func canonicalRequest(for request: URLRequest) -> URLRequest {
73	        request
74	    }
75	
76	    override func startLoading() {
77	        Self.record(request)
78	        guard let url = request.url,
79	              let stub = Self.stub(for: request),
80	              let response = HTTPURLResponse(
81	                  url: url,
82	                  statusCode: stub.statusCode,
83	                  httpVersion: "HTTP/1.1",
84	                  headerFields: ["Content-Type": "application/json"]
85	              )
86	        else {
87	            client?.urlProtocol(self, didFailWithError: URLError(.unsupportedURL))
88	            return
89	        }
90	        client?.urlProtocol(self, didReceive: response, cacheStoragePolicy: .notAllowed)
91	        client?.urlProtocol(self, didLoad: stub.body)
92	        client?.urlProtocolDidFinishLoading(self)
93	    }
94	
95	    override func stopLoading() {}
96	}
