6	/// Connection lifecycle for one robot: handshake, health polling, wake/sleep and recorded moves.
7	@MainActor
8	@Observable
9	public final class RobotSession {
10	    public enum ConnectionPhase: Equatable, Sendable {
11	        case idle
12	        case connecting(ConnectionStep)
13	        case connected(RobotIdentity)
14	        case unreachable(RobotIdentity)
15	    }
16	
17	    /// Where a connection attempt currently stands. Split out of `.connecting`
18	    /// so a failure names the step it happened on instead of collapsing into one
19	    /// opaque spinner.
20	    public enum ConnectionStep: Equatable, Sendable {
21	        case handshaking
22	        case checkingBackend(RobotIdentity)
23	        /// The daemon answered but is below the supported baseline. Terminal until
24	        /// the user updates the robot or backs out — ADR 0001 forbids sending it any
25	        /// command, and its own `/update/*` route is the way out.
26	        case needsDaemonUpdate(RobotIdentity, DaemonUpdateRequirement)
27	        /// The handshake succeeded but the robot backend is down. Terminal until
28	        /// the user picks one of start / proceed / cancel — starting it here would
29	        /// move the robot without being asked.
30	        case backendUnavailable(RobotIdentity, daemonMessage: String?)
31	        /// Latched for explicit connects only; automatic attempts fall back to
32	        /// `.idle` so the candidate loop keeps sweeping.
33	        case failed(ConnectionStage, message: String)
34	    }
35	
36	    /// The steps a connection walks through, in order — the stepper's row model.
37	    public enum ConnectionStage: Int, CaseIterable, Equatable, Sendable {
38	        case connect
39	        case compatibility
40	        case backend
41	    }
42	
43	    public enum StageOutcome: Equatable, Sendable {
44	        case pending, active, done, attention, failed
45	    }
46	
47	    /// Wake and sleep are long enough — a cold backend start is budgeted at 90 s —
48	    /// that the UI has to show what the robot is doing meanwhile.
49	    public enum PowerTransition: Equatable, Sendable {
50	        case startingBackend
51	        case wakingUp
52	        case goingToSleep
53	    }
54	
55	    public struct MovePlayback: Equatable, Sendable {
56	        public let dataset: String
57	        public let move: String
58	        public let uuid: String
59	    }
60	
61	    public struct Configuration: Sendable {
62	        /// Upstream polls every 3 s (5 s over robot Wi-Fi).
63	        public var pollInterval: Duration = .seconds(3)
64	        /// Consecutive successful probes required to leave `.unreachable`.
65	        public var requiredConsecutiveSuccesses = 2
66	        /// Move task polling is intentionally cheaper than rendering/state streaming.
67	        public var movePollInterval: Duration = .milliseconds(500)
68	        /// Upstream waits this long for a wake/sleep animation before moving on.
69	        public var moveCompletionTimeout: Duration = .seconds(10)
70	        /// Backend startup budget — upstream's `STARTUP.TIMEOUT_NORMAL`.
71	        public var daemonStartTimeout: Duration = .seconds(90)
72	        /// Motors need a moment to hold their pose before the animation starts.
73	        public var motorSettleDelay: Duration = .milliseconds(300)
74	        /// Connect-time readiness budget. We never start a backend during connect,
75	        /// so a stopped one is reported at once — this only covers the window
76	        /// between `state == running` and `backend.ready`.
77	        public var readinessTimeout: Duration = .seconds(8)
78	        public var readinessPollInterval: Duration = .milliseconds(500)
79	
80	        public init() {}
81	    }
82	
83	    // `internal(set)` rather than `private(set)`: the connect and power protocols
84	    // live in sibling files, and a `private` setter is scoped to this one. The preview
85	    // fixtures do the same, parking a session in a state no real connection would reach.
86	    public internal(set) var phase: ConnectionPhase = .idle
87	    public internal(set) var address: RobotAddress?
88	    public internal(set) var lastStatus: Components.Schemas.DaemonStatus?
89	    public internal(set) var lastError: String?
90	    public internal(set) var compatibilityWarning: String?
91	    public internal(set) var currentMove: MovePlayback?
92	    public internal(set) var isStoppingMove = false
93	    public internal(set) var powerTransition: PowerTransition?
94	    /// Explicit Disconnect suppresses discovery-driven reconnect until the user connects again.
95	    public internal(set) var automaticConnectionAllowed = true
96	
97	    let configuration: Configuration
98	    var client: (any RobotAPIClient)?
99	    var connectionAttemptID = UUID()
100	
101	    private let makeClient: @Sendable (RobotAddress) throws -> any RobotAPIClient
102	    private var pollTask: Task<Void, Never>?
103	    private var movePollTask: Task<Void, Never>?
104	    private var pathMonitor: NWPathMonitor?
105	    private var moveCache: [String: [String]] = [:]
106	
107	    /// `ReachyKitError` carries actionable text; raw interpolation would print
108	    /// the bare case name instead.
109	    ///
110	    /// The generated client wraps transport failures in a `ClientError` whose
111	    /// description carries the whole operation context — around twenty lines of
112	    /// `NSError` internals that bury the one sentence worth reading. Unwrap to the
113	    /// root cause first, so a refused connection reads as "Could not connect to
114	    /// the server."
115	    static func describe(_ error: Error) -> String {
116	        let root = rootCause(of: error)
117	        return (root as? LocalizedError)?.errorDescription ?? root.localizedDescription
118	    }
119	
120	    private static func rootCause(of error: Error) -> Error {
121	        if let clientError = error as? ClientError {
122	            return rootCause(of: clientError.underlyingError)
123	        }
124	        return error
125	    }
126	
127	    /// Production session talking to a real daemon.
128	    public convenience init(configuration: Configuration = .init()) {
129	        self.init(configuration: configuration) { try RobotConnection(address: $0) }
130	    }
131	
132	    /// Injectable client factory for tests.
133	    public init(
134	        configuration: Configuration = .init(),
135	        makeClient: @escaping @Sendable (RobotAddress) throws -> any RobotAPIClient
136	    ) {
137	        self.configuration = configuration
138	        self.makeClient = makeClient
139	    }
140	
141	    /// Connects manually by default. Automatic attempts respect a preceding explicit Disconnect.
142	    @discardableResult
143	    public func connect(to address: RobotAddress, automatically: Bool = false) async -> Bool {
144	        guard !automatically || automaticConnectionAllowed else { return false }
145	        if !automatically {
146	            automaticConnectionAllowed = true
147	        }
148	
149	        let attemptID = UUID()
150	        connectionAttemptID = attemptID
151	        resetConnectionState()
152	        self.address = address
153	        phase = .connecting(.handshaking)
154	        lastError = nil
155	
156	        do {
157	            let client = try makeClient(address)
158	            let handshake = try await client.handshake()
159	            guard connectionAttemptID == attemptID, !Task.isCancelled else {
160	                if connectionAttemptID == attemptID {
161	                    resetConnectionState()
162	                }
163	                return false
164	            }
165	            // Claimed before the readiness stage so `startBackend()` has something
166	            // to talk to while the attempt sits on `.backendUnavailable`. Only the
167	            // stepper is mounted then, so the rest of the surface stays unreachable.
168	            self.client = client
169	            lastStatus = handshake.status
170	            compatibilityWarning = handshake.compatibility.warningMessage
171	            KnownRobots.lastAddress = address
172	            KnownRobots.remember(identity: handshake.identity, address: address)
173	            // A robot set up over Bluetooth has arrived under its own identity. This is
174	            // the only place that sees a handshake, and identity is all there is to match
175	            // on — it was provisioned at one address and turns up at another (rule 4).
176	            if KnownRobots.pendingProvisionedHardwareID == handshake.identity.hardwareID {
177	                KnownRobots.pendingProvisionedHardwareID = nil
178	            }
179	            if case let .unsupported(reported, minimum) = handshake.compatibility {
180	                return haltOnUnsupportedDaemon(
181	                    identity: handshake.identity,
182	                    requirement: DaemonUpdateRequirement(
183	                        reported: reported,
184	                        minimum: minimum,
185	                        canSelfUpdate: handshake.status.wirelessVersion
186	                    )
187	                )
188	            }
189	            phase = .connecting(.checkingBackend(handshake.identity))
190	            return await settleReadiness(
191	                identity: handshake.identity,
192	                status: handshake.status,
193	                client: client,
194	                attemptID: attemptID,
195	                automatically: automatically
196	            )
197	        } catch {
198	            guard connectionAttemptID == attemptID else { return false }
199	            guard !Task.isCancelled else {
200	                resetConnectionState()
201	                return false
202	            }
203	            return failAttempt(.connect, error: error, address: address, automatically: automatically)
204	        }
205	    }
206	
207	    public func disconnect() {
208	        automaticConnectionAllowed = false
209	        connectionAttemptID = UUID()
210	        resetConnectionState()
211	        lastError = nil
212	    }
213	
214	    /// Returns a session-scoped cached dataset index. Actual move assets stay daemon-side.
215	    public func moves(in dataset: String, refresh: Bool = false) async throws -> [String] {
216	        if !refresh, let cached = moveCache[dataset] {
217	            return cached
218	        }
219	        let moves = try await withClient { try await $0.listMoves(dataset: dataset) }
220	        moveCache[dataset] = moves
221	        return moves
222	    }
223	
224	    public func playMove(dataset: String, move: String) async throws {
225	        guard let client else { throw ReachyKitError.notConnected }
226	        if currentMove != nil {
227	            await stopMove()
228	        }
229	        lastError = nil
230	        do {
231	            let uuid = try await client.playMove(dataset: dataset, move: move)
232	            let playback = MovePlayback(dataset: dataset, move: move, uuid: uuid)
233	            currentMove = playback
234	            startMonitoring(playback, client: client)
235	        } catch {
236	            lastError = Self.describe(error)
237	            throw error
238	        }
239	    }
240	
241	    /// Stops both daemon tasks: motion and the separately-owned sound player.
242	    public func stopMove() async {
243	        guard let client, let playback = currentMove, !isStoppingMove else { return }
244	        isStoppingMove = true
245	        movePollTask?.cancel()
246	        movePollTask = nil
247	
248	        let errors = await withTaskGroup(of: String?.self, returning: [String].self) { group in
249	            group.addTask {
250	                do {
251	                    try await client.stopMove(uuid: playback.uuid)
252	                    return nil
253	                } catch {
254	                    return "Move: \(error)"
255	                }
256	            }
257	            group.addTask {
258	                do {
259	                    try await client.stopSound()
260	                    return nil
261	                } catch {
262	                    return "Sound: \(error)"
263	                }
264	            }
265	
266	            var errors: [String] = []
267	            for await error in group {
268	                if let error {
269	                    errors.append(error)
270	                }
271	            }
272	            return errors
273	        }
274	
275	        if currentMove?.uuid == playback.uuid {
276	            currentMove = nil
277	        }
278	        isStoppingMove = false
279	        lastError = errors.isEmpty ? nil : errors.sorted().joined(separator: "\n")
280	    }
281	
282	    func resetConnectionState() {
283	        pollTask?.cancel()
284	        pollTask = nil
285	        movePollTask?.cancel()
286	        movePollTask = nil
287	        pathMonitor?.cancel()
288	        pathMonitor = nil
289	        client = nil
290	        address = nil
291	        lastStatus = nil
292	        compatibilityWarning = nil
293	        currentMove = nil
294	        isStoppingMove = false
295	        powerTransition = nil
296	        moveCache = [:]
297	        phase = .idle
298	    }
299	
300	    /// Polls the daemon's authoritative running-task list so natural completion
301	    /// clears the UI. Two misses avoid racing task registration just after play.
302	    private func startMonitoring(_ playback: MovePlayback, client: any RobotAPIClient) {
303	        movePollTask?.cancel()
304	        movePollTask = Task { [configuration] in
305	            var consecutiveMisses = 0
306	            while !Task.isCancelled, currentMove?.uuid == playback.uuid {
307	                try? await Task.sleep(for: configuration.movePollInterval)
308	                guard !Task.isCancelled, currentMove?.uuid == playback.uuid else { return }
309	                do {
310	                    let running = try await client.runningMoveUUIDs()
311	                    guard !Task.isCancelled, currentMove?.uuid == playback.uuid else { return }
312	                    if running.contains(playback.uuid) {
313	                        consecutiveMisses = 0
314	                    } else {
315	                        consecutiveMisses += 1
316	                        if consecutiveMisses >= 2 {
317	                            try? await client.stopSound()
318	                            guard !Task.isCancelled, currentMove?.uuid == playback.uuid else { return }
319	                            currentMove = nil
320	                            movePollTask = nil
321	                            return
322	                        }
323	                    }
324	                } catch {
325	                    // A transient status failure must not claim that playback ended.
326	                }
327	            }
328	        }
329	    }
330	
331	    /// Network changes shouldn't wait for the next poll tick: losing the path
332	    /// drops to `.unreachable` immediately; regaining it restarts polling now.
333	    func startPathMonitor(identity: RobotIdentity) {
334	        pathMonitor?.cancel()
335	        let monitor = NWPathMonitor()
336	        monitor.pathUpdateHandler = { [weak self] path in
337	            let satisfied = path.status == .satisfied
338	            Task { @MainActor in
339	                self?.pathChanged(satisfied: satisfied, identity: identity)
340	            }
341	        }
342	        monitor.start(queue: .main)
343	        pathMonitor = monitor
344	    }
345	
346	    private func pathChanged(satisfied: Bool, identity: RobotIdentity) {
347	        guard client != nil else { return }
348	        if !satisfied {
349	            if case .connected = phase {
350	                phase = .unreachable(identity)
351	            }
352	        } else if case .unreachable = phase {
353	            startPolling(identity: identity)
354	        }
355	    }
356	
357	    func startPolling(identity: RobotIdentity) {
358	        pollTask?.cancel()
359	        pollTask = Task { [configuration] in
360	            var consecutiveSuccesses = 0
361	            while !Task.isCancelled {
362	                try? await Task.sleep(for: configuration.pollInterval)
363	                guard !Task.isCancelled, let client = self.client else { return }
364	                do {
365	                    let status = try await client.daemonStatus()
366	                    lastStatus = status
367	                    if case .unreachable = phase {
368	                        consecutiveSuccesses += 1
369	                        if consecutiveSuccesses >= configuration.requiredConsecutiveSuccesses {
370	                            phase = .connected(identity)
371	                        }
372	                    } else {
373	                        consecutiveSuccesses = 1
374	                    }
375	                } catch {
376	                    consecutiveSuccesses = 0
377	                    phase = .unreachable(identity)
378	                }
379	            }
380	        }
381	    }
382	}
