import Foundation
@testable import ReachyKit
import Testing

@Suite("Robot apps")
struct RobotAppsTests {
    /// One entry as `GET /api/apps/list-available` serves it: `extra` is the raw
    /// Hugging Face Spaces payload, verbatim (`hf_space._build_app_info`).
    private static let catalogueEntry = #"""
    {
      "name": "reachy-mini-dance",
      "source_kind": "hf_space",
      "description": "Make the robot dance",
      "url": "https://huggingface.co/spaces/pollen-robotics/reachy-mini-dance",
      "extra": {
        "id": "pollen-robotics/reachy-mini-dance",
        "author": "pollen-robotics",
        "likes": 42,
        "private": false,
        "tags": ["reachy_mini_python_app"],
        "cardData": {
          "title": "Dance Party",
          "emoji": "\#u{1F483}",
          "colorFrom": "pink",
          "colorTo": "indigo",
          "short_description": "Make the robot dance"
        }
      }
    }
    """#

    private func decode(_ json: String) throws -> RobotApp {
        try JSONDecoder().decode(RobotApp.self, from: Data(json.utf8))
    }

    @Test("reads the store card out of the raw Space payload")
    func parsesCatalogueEntry() throws {
        let app = try decode(Self.catalogueEntry)
        #expect(app.spaceID == "pollen-robotics/reachy-mini-dance")
        #expect(app.title == "Dance Party")
        #expect(app.emoji == "💃")
        #expect(app.gradient == RobotApp.Gradient(from: "pink", to: "indigo"))
        #expect(app.author == "pollen-robotics")
        #expect(app.likes == 42)
        #expect(app.isPrivate == false)
        #expect(app.isOfficial)
    }

    /// `POST /api/apps/install` takes the whole `AppInfo` back, and the daemon
    /// stores that `extra` as the app's metadata — anything dropped here is lost
    /// on the robot for good.
    @Test("survives a round trip through install")
    func roundTripsInstallBody() throws {
        let app = try decode(Self.catalogueEntry)
        let sent = try JSONSerialization.jsonObject(with: JSONEncoder().encode(app.info)) as? NSDictionary
        let received = try JSONSerialization.jsonObject(with: Data(Self.catalogueEntry.utf8)) as? NSDictionary
        #expect(sent == received)
    }

    @Test("an app from anyone else is not official")
    func communityAppIsNotOfficial() throws {
        let app = try decode(Self.catalogueEntry.replacingOccurrences(of: "pollen-robotics", with: "someone"))
        #expect(app.isOfficial == false)
    }

    @Test("falls back to the app name when the card has no title")
    func fallsBackToName() throws {
        let app = try decode(#"""
        {"name": "reachy-mini-dance", "source_kind": "hf_space", "extra": {"id": "someone/reachy-mini-dance"}}
        """#)
        #expect(app.title == "reachy-mini-dance")
        #expect(app.emoji == nil)
        #expect(app.gradient == nil)
    }

    /// A payload whose fields arrive with unexpected types must still produce an
    /// app: the daemon versions independently of this client (project rule 3).
    @Test("a malformed card costs the metadata, not the app")
    func toleratesMalformedExtra() throws {
        let app = try decode(#"""
        {"name": "odd", "source_kind": "hf_space", "extra": {"id": 7, "likes": "many"}}
        """#)
        #expect(app.name == "odd")
        #expect(app.spaceID == nil)
        #expect(app.title == "odd")
    }

    // MARK: Installed apps

    /// `local_common_venv._save_app_metadata` writes the Space payload under the
    /// slug at install time and merges it back into the installed listing, so the
    /// space id usually survives.
    @Test("an installed app carries the space id the daemon saved with it")
    func installedAppKeepsSpaceID() throws {
        let app = try decode(#"""
        {
          "name": "reachy_mini_dance",
          "source_kind": "installed",
          "extra": {"id": "pollen-robotics/reachy-mini-dance", "venv_path": "/venvs/apps_venv"}
        }
        """#)
        #expect(app.isInstalled)
        #expect(app.spaceID == "pollen-robotics/reachy-mini-dance")
    }

    /// On a wireless robot the installed listing looks its metadata up by entry
    /// point name alone (`_load_app_metadata`), so an app whose Python entry point
    /// was named differently from its Space comes back with no id at all.
    @Test("an installed app whose metadata was never found has no space id")
    func installedAppWithoutMetadata() throws {
        let app = try decode(#"""
        {"name": "dance_party", "source_kind": "installed", "extra": {"venv_path": "/venvs/apps_venv"}}
        """#)
        #expect(app.spaceID == nil)
        #expect(app.title == "dance_party")
    }
}

import Foundation

/// One app as the daemon describes it, with the Hugging Face Space card behind
/// `extra` read out into something a screen can render.
///
/// The generated `AppInfo` is kept verbatim rather than unpacked into fields of
/// our own: `POST /api/apps/install` takes the entire object back, and the daemon
/// files that `extra` away as the app's stored metadata
/// (`local_common_venv._save_app_metadata`). A field dropped in translation here
/// is a field the robot never gets.
public struct RobotApp: Sendable, Equatable, Identifiable, Codable {
    /// Exactly what the daemon sent, ready to hand back to `install`.
    public let info: Components.Schemas.AppInfo
    /// What `extra` turned out to contain. Empty rather than absent when the
    /// payload made no sense — an app with no card is still an app.
    public let card: Card

    public init(_ info: Components.Schemas.AppInfo) {
        self.info = info
        card = Card(extra: info.extra)
    }

    public init(from decoder: any Decoder) throws {
        try self.init(decoder.singleValueContainer().decode(Components.Schemas.AppInfo.self))
    }

    public func encode(to encoder: any Encoder) throws {
        var container = encoder.singleValueContainer()
        try container.encode(info)
    }

    /// The Space id when there is one, so the same app keeps its identity across
    /// the catalogue and the installed list — where `name` does not (see
    /// `matches(installed:)`).
    public var id: String { spaceID ?? name }

    /// Catalogue entries are named after the Space slug, installed ones after the
    /// Python entry point, and the two need not agree.
    public var name: String { info.name }
    public var spaceID: String? { card.id }
    public var author: String? { card.author }
    public var likes: Int? { card.likes }
    public var isPrivate: Bool { card.isPrivate ?? false }
    public var isInstalled: Bool { info.sourceKind == .installed }
    /// The store's own apps. There is no verified flag on a Space — the owner is
    /// all there is to go on.
    public var isOfficial: Bool { card.author == Self.officialAuthor }

    /// Cards carry a display title; installed apps that lost their metadata have
    /// only the entry point name.
    public var title: String {
        card.title.flatMap { $0.isEmpty ? nil : $0 } ?? name
    }

    public var summary: String? {
        let text = card.shortDescription ?? info.description
        return text.flatMap { $0.isEmpty ? nil : $0 }
    }

    /// Spaces have no thumbnails — an emoji on a two-colour gradient is the whole
    /// visual identity the Hub gives them.
    public var emoji: String? { card.emoji }

    public var gradient: Gradient? {
        guard let from = card.colorFrom, let to = card.colorTo else { return nil }
        return Gradient(from: from, to: to)
    }

    static let officialAuthor = "pollen-robotics"

    /// The Hub's own palette names (`cardData.colorFrom` / `colorTo`), passed
    /// through unresolved — mapping them to colours is the UI layer's business.
    public struct Gradient: Sendable, Equatable {
        public let from: String
        public let to: String

        public init(from: String, to: String) {
            self.from = from
            self.to = to
        }
    }

    /// The handful of `extra` keys worth reading, decoded defensively.
    ///
    /// Every field is optional and every failure is local: `extra` is whatever the
    /// Hugging Face API returned that day, and one field arriving as a number must
    /// not cost the whole app (project rule 3).
    public struct Card: Sendable, Equatable, Decodable {
        public var id: String?
        public var author: String?
        public var likes: Int?
        public var isPrivate: Bool?
        public var title: String?
        public var emoji: String?
        public var colorFrom: String?
        public var colorTo: String?
        public var shortDescription: String?

        public static let empty = Card()

        public init() {}

        init(extra: OpenAPIObjectContainer?) {
            guard let extra,
                  let data = try? JSONEncoder().encode(extra),
                  let card = try? JSONDecoder().decode(Card.self, from: data)
            else {
                self = .empty
                return
            }
            self = card
        }

        private enum CodingKeys: String, CodingKey {
            case id, author, likes, cardData
            case isPrivate = "private"
        }

        private enum CardDataKeys: String, CodingKey {
            case title, emoji, colorFrom, colorTo
            case shortDescription = "short_description"
        }

        public init(from decoder: any Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            id = container.value(String.self, .id)
            author = container.value(String.self, .author)
            likes = container.value(Int.self, .likes)
            isPrivate = container.value(Bool.self, .isPrivate)

            guard let card = try? container.nestedContainer(keyedBy: CardDataKeys.self, forKey: .cardData) else {
                return
            }
            title = card.value(String.self, .title)
            emoji = card.value(String.self, .emoji)
            colorFrom = card.value(String.self, .colorFrom)
            colorTo = card.value(String.self, .colorTo)
            shortDescription = card.value(String.self, .shortDescription)
        }
    }
}

private extension KeyedDecodingContainer {
    /// A key of the wrong type reads as absent rather than throwing.
    func value<T: Decodable>(_: T.Type, _ key: Key) -> T? {
        (try? decodeIfPresent(T.self, forKey: key)) ?? nil
    }
}

