import Foundation
@testable import ReachyKit
import Testing

/// The socket alone cannot be trusted to end an install, and the poll alone would
/// deliver the log in 500 ms lumps. This is where the two are reconciled.
@Suite("App job monitor", .timeLimit(.minutes(1)))
struct AppJobMonitorTests {
    /// Generous on purpose: a loaded runner must not turn "the job is still
    /// running" into a timeout (project rule 7).
    private static let configuration = AppJobMonitor.Configuration(
        pollInterval: .milliseconds(5),
        timeout: .seconds(10)
    )

    private func silentSocket() -> AsyncStream<JobLogEvent> {
        AsyncStream { _ in }
    }

    private func socket(_ events: [JobLogEvent]) -> AsyncStream<JobLogEvent> {
        AsyncStream { continuation in
            for event in events {
                continuation.yield(event)
            }
            continuation.finish()
        }
    }

    /// Hands out the scripted answers in order, repeating the last one forever.
    private final class Poll: @unchecked Sendable {
        private let answers: [Result<DaemonJob, any Error>]
        private let lock = NSLock()
        private var index = 0

        init(_ answers: [Result<DaemonJob, any Error>]) {
            self.answers = answers
        }

        func next() throws -> DaemonJob {
            let answer = lock.withLock { () -> Result<DaemonJob, any Error> in
                defer { index = min(index + 1, answers.count - 1) }
                return answers[min(index, answers.count - 1)]
            }
            return try answer.get()
        }
    }

    private func collect(
        socket: AsyncStream<JobLogEvent>,
        poll: Poll,
        configuration: AppJobMonitor.Configuration = configuration
    ) async -> [AppJobMonitor.Event] {
        let monitor = AppJobMonitor(
            configuration: configuration,
            logs: { socket },
            job: { try poll.next() }
        )
        var received: [AppJobMonitor.Event] = []
        for await event in monitor.events() {
            received.append(event)
        }
        return received
    }

    private func job(_ status: DaemonJob.Status, _ logs: [String] = []) -> DaemonJob {
        DaemonJob(command: "install", status: status, logs: logs)
    }

    @Test("the socket's own terminal status ends the job")
    func finishesOnSocketStatus() async {
        let events = await collect(
            socket: socket([.line("Collecting reachy-mini"), .status(.done), .closed]),
            poll: Poll([.success(job(.inProgress, ["Collecting reachy-mini"]))])
        )

        #expect(events == [
            .line("Collecting reachy-mini"),
            .status(.done),
            .finished(.succeeded),
        ])
    }

    /// `ws_poll_info` only ever wakes on a *new* log line, so a job that finished
    /// before the socket opened sends nothing at all — for good. Without the poll
    /// running alongside it, the install would sit on its spinner forever.
    @Test("a socket that never says anything still finishes, because the poll does")
    func finishesFromPollingWhenTheSocketIsSilent() async {
        let events = await collect(
            socket: silentSocket(),
            poll: Poll([
                .success(job(.inProgress, ["Collecting reachy-mini"])),
                .success(job(.done, ["Collecting reachy-mini", "Successfully installed"])),
            ])
        )

        #expect(events == [
            .line("Collecting reachy-mini"),
            .status(.inProgress),
            .line("Successfully installed"),
            .status(.done),
            .finished(.succeeded),
        ])
    }

    /// The poll answers with the job's *whole* log every time; the socket has
    /// already delivered the front of it.
    @Test("a line the socket already delivered is not repeated by the poll")
    func doesNotRepeatLines() async {
        let events = await collect(
            socket: socket([.line("Collecting reachy-mini")]),
            poll: Poll([
                .success(job(.done, ["Collecting reachy-mini", "Successfully installed"])),
            ])
        )

        #expect(events.filter { $0 == .line("Collecting reachy-mini") }.count == 1)
        #expect(events.last == .finished(.succeeded))
    }

    /// A failed job is a 200 with `status: failed` — never an HTTP error — and the
    /// reason is only ever the last line the job logged.
    @Test("a failed job carries the reason it failed")
    func reportsFailureReason() async {
        let events = await collect(
            socket: silentSocket(),
            poll: Poll([
                .success(job(.failed, ["Collecting", "Job 'install' failed with error: no matching distribution"])),
            ])
        )

        #expect(events.last == .finished(.failed("Job 'install' failed with error: no matching distribution")))
    }

    /// The job register is in memory. A daemon that restarted mid-install answers
    /// 404 for a job that really did start — which is not the same as a failure,
    /// and the user has to be told to go and look.
    @Test("a job the daemon has forgotten ends as a restart, not a failure")
    func reportsForgottenJob() async {
        let events = await collect(
            socket: silentSocket(),
            poll: Poll([.failure(ReachyKitError.daemonRejected(statusCode: 404))])
        )

        #expect(events == [.finished(.daemonRestarted)])
    }

    /// Same conclusion over the socket: the daemon greets an unknown id with one
    /// JSON frame and hangs up.
    @Test("the socket rejecting the job ends it the same way")
    func reportsRejectedJob() async {
        let events = await collect(
            socket: socket([.rejected("Job ID not found"), .closed]),
            poll: Poll([.failure(ReachyKitError.daemonRejected(statusCode: 404))])
        )

        #expect(events.last == .finished(.daemonRestarted))
    }

    @Test("a job that never ends gives up on its own deadline")
    func timesOut() async {
        let events = await collect(
            socket: silentSocket(),
            poll: Poll([.success(job(.inProgress, []))]),
            configuration: .init(pollInterval: .milliseconds(5), timeout: .milliseconds(200))
        )

        #expect(events == [.status(.inProgress), .finished(.timedOut)])
    }

    /// Whatever happens, a screen gets exactly one ending and the stream closes —
    /// a second outcome would leave an overlay with nothing to dismiss it.
    @Test("there is exactly one outcome, and the stream ends with it")
    func endsExactlyOnce() async {
        let events = await collect(
            socket: socket([.status(.done), .closed]),
            poll: Poll([.success(job(.done, ["Successfully installed"]))])
        )

        let outcomes = events.filter {
            if case .finished = $0 { return true } else { return false }
        }
        #expect(outcomes.count == 1)
        #expect(events.last == .finished(.succeeded))
    }

    /// A transient poll failure is not the end of a job: the network drops a packet
    /// far more often than the daemon forgets a job.
    @Test("a poll that fails once keeps going")
    func survivesATransientPollFailure() async {
        let events = await collect(
            socket: silentSocket(),
            poll: Poll([
                .failure(URLError(.timedOut)),
                .success(job(.done, ["Successfully installed"])),
            ])
        )

        #expect(events.last == .finished(.succeeded))
    }
}

import Foundation

/// Follows one app install, removal or update to its end.
///
/// Neither of the daemon's two ways of reporting a job is sufficient alone:
///
/// - the **socket** delivers each log line the moment it is written, but only ever
///   wakes on a *new* line. A job that finished before the socket opened sends
///   nothing at all, ever — the stream simply hangs;
/// - the **poll** always answers, but in `pollInterval` lumps, and its 404 is the
///   only way to learn that the daemon restarted and took the job register with it.
///
/// So both run, and this reconciles them. Both sources report the job's log from
/// its first line (`ws_poll_info` starts its cursor at zero too), which is what
/// makes a single "lines emitted" cursor enough to keep either from repeating the
/// other.
public struct AppJobMonitor: Sendable {
    public struct Configuration: Sendable {
        public var pollInterval: Duration
        /// Upstream's budgets, which are what the robot was tested against.
        public var timeout: Duration

        public init(pollInterval: Duration = .milliseconds(500), timeout: Duration = .seconds(60)) {
            self.pollInterval = pollInterval
            self.timeout = timeout
        }

        public static let install = Self(timeout: .seconds(60))
        public static let removal = Self(timeout: .seconds(90))
        public static let update = Self(timeout: .seconds(90))
    }

    public enum Outcome: Sendable, Equatable {
        case succeeded
        /// The daemon reports a failed job with a 200 and `status: failed` — never
        /// as an HTTP error. The reason is the last line the job logged.
        case failed(String?)
        /// The job register is in memory: a daemon that restarted mid-job answers
        /// 404 for work that really did start. Neither success nor failure, and the
        /// only honest thing to do is say so and re-read the installed list.
        case daemonRestarted
        case timedOut
    }

    public enum Event: Sendable, Equatable {
        case line(String)
        case status(DaemonJob.Status)
        /// Always the last event, and there is exactly one.
        case finished(Outcome)
    }

    private let configuration: Configuration
    private let logs: @Sendable () -> AsyncStream<JobLogEvent>
    private let job: @Sendable () async throws -> DaemonJob

    /// Both sources are injected rather than built here: the session owns the
    /// address and the client, and a test has no business standing up a socket.
    public init(
        configuration: Configuration = .install,
        logs: @escaping @Sendable () -> AsyncStream<JobLogEvent>,
        job: @escaping @Sendable () async throws -> DaemonJob
    ) {
        self.configuration = configuration
        self.logs = logs
        self.job = job
    }

    public func events() -> AsyncStream<Event> {
        let (stream, continuation) = AsyncStream.makeStream(
            of: Event.self,
            bufferingPolicy: .bufferingNewest(1000)
        )
        let task = Task { [configuration, logs, job] in
            let coordinator = Coordinator(continuation: continuation)
            await withTaskGroup(of: Void.self) { group in
                group.addTask { await coordinator.follow(logs()) }
                group.addTask { await coordinator.poll(job, every: configuration.pollInterval) }
                group.addTask {
                    try? await Task.sleep(for: configuration.timeout)
                    await coordinator.finish(.timedOut)
                }
                for await _ in group where await coordinator.hasFinished {
                    break
                }
                group.cancelAll()
            }
            continuation.finish()
        }
        continuation.onTermination = { _ in task.cancel() }
        return stream
    }

    private actor Coordinator {
        private let continuation: AsyncStream<Event>.Continuation
        /// How much of the job's log has reached the caller. Both sources index
        /// into the same list, so this is what keeps them from doubling it up.
        private var emittedLines = 0
        private var lastLine: String?
        private var lastStatus: DaemonJob.Status?
        private var isFinished = false

        init(continuation: AsyncStream<Event>.Continuation) {
            self.continuation = continuation
        }

        var hasFinished: Bool { isFinished }

        func follow(_ stream: AsyncStream<JobLogEvent>) async {
            var received = 0
            for await event in stream {
                guard !isFinished else { return }
                switch event {
                case let .line(text):
                    deliver(line: text, at: received)
                    received += 1
                case let .status(status):
                    deliver(status)
                case let .rejected(reason):
                    // The daemon greets an unknown job id with one frame and hangs
                    // up. Same conclusion as the poll's 404.
                    _ = reason
                    finish(.daemonRestarted)
                    return
                case .closed:
                    // Not an outcome on its own: an app job leaves the daemon
                    // standing, so the poll can still tell us how it ended.
                    return
                }
            }
        }

        func poll(_ job: @Sendable () async throws -> DaemonJob, every interval: Duration) async {
            while !Task.isCancelled, !isFinished {
                try? await Task.sleep(for: interval)
                guard !Task.isCancelled, !isFinished else { return }
                do {
                    let info = try await job()
                    guard !isFinished else { return }
                    deliver(logs: info.logs)
                    deliver(info.status)
                } catch ReachyKitError.daemonRejected(statusCode: 404) {
                    finish(.daemonRestarted)
                    return
                } catch {
                    // A dropped packet is not a lost job — keep asking.
                }
            }
        }

        func finish(_ outcome: Outcome) {
            guard !isFinished else { return }
            isFinished = true
            continuation.yield(.finished(outcome))
            continuation.finish()
        }

        private func deliver(logs: [String]) {
            guard logs.count > emittedLines else { return }
            for line in logs[emittedLines...] {
                continuation.yield(.line(line))
                lastLine = line
            }
            emittedLines = logs.count
        }

        private func deliver(line: String, at index: Int) {
            guard index >= emittedLines else { return }
            continuation.yield(.line(line))
            lastLine = line
            emittedLines = index + 1
        }

        private func deliver(_ status: DaemonJob.Status) {
            guard status != lastStatus else { return }
            lastStatus = status
            continuation.yield(.status(status))
            switch status {
            case .done: finish(.succeeded)
            case .failed: finish(.failed(lastLine))
            default: break
            }
        }
    }
}

