import Foundation
@testable import ReachyKit
import Testing

/// `/api/hf-auth/*` — the robot's own Hugging Face account, and the relay that
/// account gets it onto. Every shape here comes from `routers/hf_auth.py`.
@Suite("Hugging Face auth over HTTP", .timeLimit(.minutes(1)))
struct RobotConnectionHFAuthTests {
    private func makeSession(_ stubs: [String: StubURLProtocol.Stub]) -> URLSession {
        StubURLProtocol.makeSession(stubs)
    }

    private func makeConnection(_ session: URLSession) throws -> RobotConnection {
        try RobotConnection(address: RobotAddress(host: "10.42.0.1"), session: session)
    }

    @Test("a robot with no token says so")
    func readsLoggedOutStatus() async throws {
        let session = makeSession([
            "/api/hf-auth/status": .init(statusCode: 200, json: #"{"is_logged_in": false, "username": null}"#),
        ])

        let status = try await makeConnection(session).hfAuthStatus()

        #expect(status.isLoggedIn == false)
        #expect(status.username == nil)
    }

    @Test("a linked robot names the account it is linked to")
    func readsLoggedInStatus() async throws {
        let session = makeSession([
            "/api/hf-auth/status": .init(statusCode: 200, json: #"{"is_logged_in": true, "username": "alexey1312"}"#),
        ])

        let status = try await makeConnection(session).hfAuthStatus()

        #expect(status.isLoggedIn)
        #expect(status.username == "alexey1312")
    }

    /// The LAN hop is plain HTTP, so the one thing this client must never do is
    /// put the token where a proxy, a log or a screenshot can pick it up. The
    /// daemon takes the same care on its own side: it sends the token to central
    /// in an `Authorization` header rather than the URL, for exactly this reason.
    @Test("the token is sent in the body and never in the URL")
    func keepsTheTokenOutOfTheURL() async throws {
        let session = makeSession([
            "/api/hf-auth/save-token": .init(
                statusCode: 200,
                json: #"{"status": "success", "username": "alexey1312"}"#
            ),
        ])
        let token = "hf_ThisIsNotARealTokenButItLooksLikeOne"

        let username = try await makeConnection(session).saveHFToken(token)

        #expect(username == "alexey1312")
        let request = try #require(StubURLProtocol.requests(for: session).first)
        let url = try #require(request.url?.absoluteString)
        #expect(request.httpMethod == "POST")
        #expect(url == "http://10.42.0.1:8000/api/hf-auth/save-token")
        #expect(!url.contains(token))
        let body = try #require(StubURLProtocol.bodies(for: session).first)
        #expect(try JSONSerialization.jsonObject(with: body) as? NSDictionary == ["token": token])
    }

    /// The daemon validates the token by calling `whoami` before storing it, and a
    /// token that fails comes back as a 400 — not a 401.
    @Test("a token the Hub rejects is refused with a 400")
    func rejectsAnInvalidToken() async throws {
        let session = makeSession([
            "/api/hf-auth/save-token": .init(statusCode: 400, json: #"{"detail": "Invalid token"}"#),
        ])

        await #expect(throws: ReachyKitError.daemonRejected(statusCode: 400)) {
            try await makeConnection(session).saveHFToken("nope")
        }
    }

    @Test("unlinking clears the robot's token")
    func deletesTheToken() async throws {
        let session = makeSession([
            "/api/hf-auth/token": .init(statusCode: 200, json: #"{"status": "success"}"#),
        ])

        try await makeConnection(session).deleteHFToken()

        #expect(StubURLProtocol.requests(for: session).first?.httpMethod == "DELETE")
    }

    // MARK: Relay

    @Test("a connected relay reports the state and the flag that agree with it")
    func readsConnectedRelay() async throws {
        let session = makeSession([
            "/api/hf-auth/relay-status": .init(
                statusCode: 200,
                json: #"{"state": "connected", "message": "Connected to central", "is_connected": true}"#
            ),
        ])

        let status = try await makeConnection(session).relayStatus()

        #expect(status.state == .connected)
        #expect(status.isConnected)
        #expect(status.message == "Connected to central")
    }

    /// `RelayState` has six values; the router adds a seventh of its own for a
    /// Lite robot and for a build that ships no relay module. Neither is in the
    /// enum the relay itself defines.
    @Test("a Lite robot answers with a state the relay enum does not have")
    func readsUnavailableRelay() async throws {
        let session = makeSession([
            "/api/hf-auth/relay-status": .init(
                statusCode: 200,
                json: #"{"state": "unavailable", "message": "Coming soon to Lite version", "is_connected": false}"#
            ),
        ])

        let status = try await makeConnection(session).relayStatus()

        #expect(status.state == .unavailable)
        #expect(status.isConnected == false)
    }

    @Test("a state from a newer daemon is carried, not thrown")
    func toleratesUnknownRelayState() async throws {
        let session = makeSession([
            "/api/hf-auth/relay-status": .init(
                statusCode: 200,
                json: #"{"state": "handshaking", "is_connected": false}"#
            ),
        ])

        #expect(try await makeConnection(session).relayStatus().state == .unknown("handshaking"))
    }

    /// The daemon's own docstring is explicit about this: on `skipped` nothing was
    /// kicked off, so a caller that then waits for the relay state to change waits
    /// forever.
    @Test("a refresh that was skipped says so instead of pretending to reconnect")
    func reportsSkippedRefresh() async throws {
        let session = makeSession([
            "/api/hf-auth/refresh-relay": .init(
                statusCode: 200,
                json: #"{"status": "skipped", "token_available": true, "reason": "relay_not_running"}"#
            ),
        ])

        let refresh = try await makeConnection(session).refreshRelay()

        #expect(refresh.didStart == false)
        #expect(refresh.tokenAvailable)
        #expect(refresh.reason == "relay_not_running")
    }

    @Test("a refresh that was accepted reports that it started")
    func reportsRequestedRefresh() async throws {
        let session = makeSession([
            "/api/hf-auth/refresh-relay": .init(
                statusCode: 200,
                json: #"{"status": "requested", "token_available": true}"#
            ),
        ])

        #expect(try await makeConnection(session).refreshRelay().didStart)
    }

    // MARK: Central proxy

    /// The daemon proxies central's robot list so the raw token never reaches this
    /// app over the LAN. `available: false` means "unknown", never "no robots".
    @Test("an unlinked robot proxies nothing and says why")
    func reportsUnauthenticatedProxy() async throws {
        let session = makeSession([
            "/api/hf-auth/central-robot-status": .init(
                statusCode: 200,
                json: #"{"available": false, "robots": [], "reason": "not_authenticated"}"#
            ),
        ])

        let proxy = try await makeConnection(session).centralRobotStatus()

        #expect(proxy.isAvailable == false)
        #expect(proxy.reason == .notAuthenticated)
        #expect(proxy.robots.isEmpty)
    }

    @Test("central's robot list comes through with the keys that identify a robot")
    func decodesProxiedRobots() async throws {
        let session = makeSession([
            "/api/hf-auth/central-robot-status": .init(
                statusCode: 200,
                json: #"""
                {"available": true, "robots": [
                  {"peerId": "peer-7", "robotName": "testbot", "busy": true, "activeApp": "Hand Tracker",
                   "meta": {"name": "testbot", "transport": "wifi", "hardware_id": "a1b2c3d4e5f60718"},
                   "last_seen_age_seconds": 3.2}
                ]}
                """#
            ),
        ])

        let robot = try #require(await makeConnection(session).centralRobotStatus().robots.first)

        #expect(robot.hardwareID == "a1b2c3d4e5f60718")
        #expect(robot.transport == .wifi)
        #expect(robot.isBusy)
        #expect(robot.activeApp == "Hand Tracker")
    }

    /// `peerId` changes on every relay reconnect, so it is the last resort. Daemon
    /// 1.9.0 sends no `install_id` at all — the relay lists it as a future field.
    @Test("a robot is identified by the most stable key it actually sent")
    func fallsBackThroughIdentityKeys() async throws {
        let session = makeSession([
            "/api/hf-auth/central-robot-status": .init(
                statusCode: 200,
                json: #"""
                {"available": true, "robots": [
                  {"peerId": "peer-7", "busy": false, "meta": {"name": "a", "transport": "usb"}},
                  {"peerId": "peer-8", "busy": false,
                   "meta": {"name": "b", "transport": "wifi", "hardware_id": "a1b2c3d4e5f60718"}}
                ]}
                """#
            ),
        ])

        let robots = try await makeConnection(session).centralRobotStatus().robots

        #expect(robots.map(\.id) == ["peer-7", "a1b2c3d4e5f60718"])
        #expect(robots.first?.transport == .usb)
    }
}

import Foundation

/// Whether the *robot* holds a Hugging Face token, and whose it is.
///
/// Nothing to do with whether this app is signed in: the two custody points are
/// separate on purpose (see the token-custody ADR). The daemon answers this by
/// running `whoami` against the Hub on every single call, so it is slow enough to
/// be worth caching and never worth polling.
public struct HFAuthStatus: Sendable, Equatable, Decodable {
    public let isLoggedIn: Bool
    public let username: String?

    public init(isLoggedIn: Bool, username: String? = nil) {
        self.isLoggedIn = isLoggedIn
        self.username = username
    }

    private enum CodingKeys: String, CodingKey {
        case isLoggedIn = "is_logged_in"
        case username
    }
}

/// The robot's connection to the Hugging Face relay — what makes it reachable
/// from outside the LAN at all.
public struct RelayStatus: Sendable, Equatable, Decodable {
    public enum State: Sendable, Equatable, Decodable {
        case stopped
        case waitingForToken
        case connecting
        case connected
        case reconnecting
        case error
        /// Not one of the relay's own six states: the router substitutes this for
        /// a Lite robot, and for a daemon whose build ships no relay module.
        /// There is nothing the user can do about either.
        case unavailable
        case unknown(String)

        public init(from decoder: any Decoder) throws {
            switch try decoder.singleValueContainer().decode(String.self) {
            case "stopped": self = .stopped
            case "waiting_for_token": self = .waitingForToken
            case "connecting": self = .connecting
            case "connected": self = .connected
            case "reconnecting": self = .reconnecting
            case "error": self = .error
            case "unavailable": self = .unavailable
            case let other: self = .unknown(other)
            }
        }
    }

    public let state: State
    /// The relay's own words for the state — worth showing verbatim when it is an
    /// error, since it is the only detail the daemon offers.
    public let message: String?
    /// The daemon's own verdict rather than a comparison against `state`: it is
    /// what the relay instance reports, and a state this client has not heard of
    /// must not silently read as disconnected.
    public let isConnected: Bool

    public init(state: State, message: String? = nil, isConnected: Bool) {
        self.state = state
        self.message = message
        self.isConnected = isConnected
    }

    private enum CodingKeys: String, CodingKey {
        case state, message
        case isConnected = "is_connected"
    }
}

/// The answer to `POST /api/hf-auth/refresh-relay`.
///
/// The distinction matters more than it looks: on `skipped` the daemon started
/// nothing at all, so a caller that goes on to wait for `relay-status` to change
/// waits forever. The daemon's own docstring calls that trap out by name.
public struct RelayRefresh: Sendable, Equatable, Decodable {
    public let status: String
    public let tokenAvailable: Bool
    /// `relay_not_running` (no relay instance — no token, or the daemon is still
    /// coming up) or `relay_unavailable` (a build with no relay module at all).
    public let reason: String?

    /// Whether a reconnect was actually kicked off. Only then is waiting for a
    /// state change meaningful.
    public var didStart: Bool { status == "requested" }

    public init(status: String, tokenAvailable: Bool, reason: String? = nil) {
        self.status = status
        self.tokenAvailable = tokenAvailable
        self.reason = reason
    }

    private enum CodingKeys: String, CodingKey {
        case status, reason
        case tokenAvailable = "token_available"
    }
}

/// The robot's view of central's robot list, fetched on our behalf.
///
/// The daemon proxies this route rather than handing out the token, so on the LAN
/// this is how the app learns which of the user's robots are online without ever
/// seeing a credential.
public struct CentralRobotStatusProxy: Sendable, Equatable, Decodable {
    /// Why the proxy could not answer. Every case means "unknown" rather than
    /// "no robots" — the daemon's own docstring says callers must not block on it.
    public enum Reason: Sendable, Equatable, Decodable {
        case notAuthenticated
        case tokenInvalid
        case unreachable
        case http(Int)
        case unknown(String)

        public init(from decoder: any Decoder) throws {
            let raw = try decoder.singleValueContainer().decode(String.self)
            switch raw {
            case "not_authenticated": self = .notAuthenticated
            case "token_invalid": self = .tokenInvalid
            case "unreachable": self = .unreachable
            default:
                if raw.hasPrefix("http_"), let code = Int(raw.dropFirst("http_".count)) {
                    self = .http(code)
                } else {
                    self = .unknown(raw)
                }
            }
        }
    }

    public let isAvailable: Bool
    public let robots: [CentralRobot]
    public let reason: Reason?

    public init(isAvailable: Bool, robots: [CentralRobot] = [], reason: Reason? = nil) {
        self.isAvailable = isAvailable
        self.robots = robots
        self.reason = reason
    }

    private enum CodingKeys: String, CodingKey {
        case robots, reason
        case isAvailable = "available"
    }
}

/// One robot as the central signaling server lists it.
///
/// Reached two ways — proxied by a robot on the LAN, or read straight from
/// central once this app holds a token — and the shape is the same either way.
public struct CentralRobot: Sendable, Equatable, Identifiable, Decodable {
    public enum Transport: Sendable, Equatable, Decodable {
        case wifi
        case usb
        case unknown(String)

        public init(from decoder: any Decoder) throws {
            switch try decoder.singleValueContainer().decode(String.self) {
            case "wifi": self = .wifi
            case "usb": self = .usb
            case let other: self = .unknown(other)
            }
        }
    }

    public struct Meta: Sendable, Equatable, Decodable {
        public let name: String?
        public let transport: Transport?
        /// `sha256(usb serial)[:16]` — the same string the daemon serves at
        /// `/api/daemon/hardware-id` and advertises over mDNS, which is what makes
        /// a central listing joinable to a LAN one (project rule 4).
        public let hardwareID: String?
        /// Announced by the relay as a future field; daemon 1.9.0 never sends it.
        public let installID: String?

        private enum CodingKeys: String, CodingKey {
            case name, transport
            case hardwareID = "hardware_id"
            case installID = "install_id"
        }
    }

    public let peerID: String
    public let robotName: String?
    public let isBusy: Bool
    /// What is holding the robot — a local app or another listener's session.
    public let activeApp: String?
    public let meta: Meta?
    public let lastSeenAgeSeconds: Double?

    /// The most stable identifier the robot actually sent. `peerId` changes on
    /// every relay reconnect, so it is the last resort, not the key.
    public var id: String {
        meta?.installID ?? meta?.hardwareID ?? peerID
    }

    public var hardwareID: String? { meta?.hardwareID }
    public var transport: Transport? { meta?.transport }
    public var displayName: String { robotName ?? meta?.name ?? peerID }

    private enum CodingKeys: String, CodingKey {
        case peerID = "peerId"
        case robotName
        case busy
        case activeApp
        case meta
        case lastSeenAgeSeconds = "last_seen_age_seconds"
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        peerID = try container.decode(String.self, forKey: .peerID)
        robotName = try container.decodeIfPresent(String.self, forKey: .robotName)
        isBusy = try container.decodeIfPresent(Bool.self, forKey: .busy) ?? false
        activeApp = try container.decodeIfPresent(String.self, forKey: .activeApp)
        meta = try container.decodeIfPresent(Meta.self, forKey: .meta)
        lastSeenAgeSeconds = try container.decodeIfPresent(Double.self, forKey: .lastSeenAgeSeconds)
    }
}

import Foundation

/// The robot's own Hugging Face account: the token it stores, the relay that
/// token buys it, and central's robot list proxied through it.
///
/// The daemon's OAuth routes (`/api/hf-auth/oauth/*`) are deliberately absent.
/// They exist for a browser pointed at the robot, and they redirect back to
/// `reachy-mini.local` — a flow this app has no use for, because it signs in
/// natively and hands the robot a token it already holds.
public protocol HFAuthClient: Sendable {
    func hfAuthStatus() async throws -> HFAuthStatus
    /// Stores the token on the robot. The daemon validates it against the Hub
    /// first and answers 400 if the Hub refuses it. Returns the account name it
    /// resolved to.
    @discardableResult
    func saveHFToken(_ token: String) async throws -> String?
    func deleteHFToken() async throws
    func relayStatus() async throws -> RelayStatus
    /// Asks the relay to reconnect. Check `didStart` before waiting on anything.
    @discardableResult
    func refreshRelay() async throws -> RelayRefresh
    /// Central's robot list, fetched by the robot with its own token.
    func centralRobotStatus() async throws -> CentralRobotStatusProxy
}

/// Defaults keep test doubles focused on the behaviour they exercise.
public extension HFAuthClient {
    func hfAuthStatus() async throws -> HFAuthStatus {
        throw URLError(.unsupportedURL)
    }

    @discardableResult
    func saveHFToken(_: String) async throws -> String? {
        throw URLError(.unsupportedURL)
    }

    func deleteHFToken() async throws {
        throw URLError(.unsupportedURL)
    }

    func relayStatus() async throws -> RelayStatus {
        throw URLError(.unsupportedURL)
    }

    @discardableResult
    func refreshRelay() async throws -> RelayRefresh {
        throw URLError(.unsupportedURL)
    }

    func centralRobotStatus() async throws -> CentralRobotStatusProxy {
        throw URLError(.unsupportedURL)
    }
}

import Foundation

/// `/api/hf-auth/*`.
///
/// The two token routes go through the generated client, which is what puts the
/// token in a JSON body rather than anywhere it could be logged. The other four
/// are declared `additionalProperties: true` in the spec, so the generated client
/// hands back an untyped container — decoding the raw payload directly costs less
/// than re-encoding that container, and lets every enum stay tolerant of a value
/// a later daemon invents (project rule 3).
extension RobotConnection: HFAuthClient {
    public func hfAuthStatus() async throws -> HFAuthStatus {
        try await hubJSON(path: "/api/hf-auth/status")
    }

    /// 400 when the Hub refuses the token — the daemon runs `whoami` before it
    /// stores anything.
    @discardableResult
    public func saveHFToken(_ token: String) async throws -> String? {
        switch try await hubClient.saveTokenApiHfAuthSaveTokenPost(body: .json(.init(token: token))) {
        case let .ok(response):
