import Foundation
@testable import ReachyKit
import Testing

@Suite("Hugging Face OAuth", .timeLimit(.minutes(1)))
struct HFOAuthTests {
    private let configuration = HFOAuthConfiguration(
        clientID: "client-1",
        redirectURI: "reachy-mini-swift://oauth-callback",
        scopes: HFOAuthConfiguration.reachyMiniScopes
    )

    // MARK: PKCE

    /// RFC 7636 appendix B, verbatim. The one place a subtle base64 mistake —
    /// padding, or standard alphabet instead of URL-safe — silently produces a
    /// challenge the Hub rejects with nothing but "invalid_grant".
    @Test("derives the challenge the RFC's own vector expects")
    func matchesTheRFCVector() {
        let pkce = HFOAuth.PKCE(verifier: "REDACTED")

        #expect(pkce.challenge == "REDACTED")
        #expect(pkce.method == "S256")
    }

    @Test("a generated verifier is legal and never repeats")
    func generatesLegalVerifiers() {
        let allowed = CharacterSet(charactersIn: "REDACTED._~")
        let first = HFOAuth.PKCE()
        let second = HFOAuth.PKCE()

        #expect(first.verifier != second.verifier)
        for pkce in [first, second] {
            #expect((43 ... 128).contains(pkce.verifier.count))
            #expect(CharacterSet(charactersIn: pkce.verifier).isSubset(of: allowed))
        }
    }

    // MARK: Authorization URL

    /// Built with `URLComponents` (rule 5) — the redirect URI carries a scheme and
    /// slashes, and hand-interpolating it is how it ends up unescaped.
    @Test("the authorize URL carries everything the Hub needs and nothing else")
    func buildsTheAuthorizationURL() throws {
        let pkce = HFOAuth.PKCE(verifier: "REDACTED")
        let url = try #require(HFOAuth.authorizationURL(configuration: configuration, pkce: pkce, state: "state-1"))
        let items = try #require(URLComponents(url: url, resolvingAgainstBaseURL: false)?.queryItems)
        let query = Dictionary(uniqueKeysWithValues: items.map { ($0.name, $0.value ?? "") })

        #expect(url.host == "huggingface.co")
        #expect(url.path == "/oauth/authorize")
        #expect(query["client_id"] == "client-1")
        #expect(query["redirect_uri"] == "reachy-mini-swift://oauth-callback")
        #expect(query["response_type"] == "code")
        #expect(query["state"] == "state-1")
        #expect(query["code_challenge"] == pkce.challenge)
        #expect(query["code_challenge_method"] == "S256")
        #expect(query["scope"] == HFOAuthConfiguration.reachyMiniScopes)
        // A public client has no secret to send, and sending one would be worse
        // than useless — it would be shipped inside the app.
        #expect(query["client_secret"] == nil)
    }

    @Test("an app without a registered client id knows it cannot start")
    func reportsMissingClientID() {
        #expect(HFOAuthConfiguration(clientID: "", redirectURI: "x://y", scopes: "openid").isConfigured == false)
        #expect(configuration.isConfigured)
    }

    // MARK: Callback

    @Test("reads the code out of the callback")
    func readsTheCallbackCode() throws {
        let url = try #require(URL(string: "reachy-mini-swift://oauth-callback?code=abc123&state=state-1"))

        #expect(try HFOAuth.code(in: url, expectedState: "state-1") == "abc123")
    }

    /// The state is the only thing standing between this app and a code somebody
    /// else obtained — dropping the check is the classic OAuth mistake.
    @Test("a callback whose state does not match is refused")
    func refusesAForeignState() throws {
        let url = try #require(URL(string: "reachy-mini-swift://oauth-callback?code=abc123&state=someone-else"))

        #expect(throws: HFOAuthError.stateMismatch) {
            try HFOAuth.code(in: url, expectedState: "state-1")
        }
    }

    @Test("a refusal from the Hub is reported as itself")
    func readsAnErrorCallback() throws {
        let url = try #require(URL(string: "reachy-mini-swift://oauth-callback?error=access_denied&state=state-1"))

        #expect(throws: HFOAuthError.denied("access_denied")) {
            try HFOAuth.code(in: url, expectedState: "state-1")
        }
    }

    // MARK: Token exchange

    private func exchanger(_ stubs: [String: StubURLProtocol.Stub]) -> HFTokenExchanger {
        HFTokenExchanger(configuration: configuration, session: StubURLProtocol.makeSession(stubs))
    }

    @Test("exchanges the code for a token, sending the verifier and no secret")
    func exchangesTheCode() async throws {
        let session = StubURLProtocol.makeSession([
            "/oauth/token": .init(
                statusCode: 200,
                json: #"{"access_token": "hf_abc", "expires_in": 28800, "refresh_token": "r1"}"#
            ),
        ])

        let token = try await HFTokenExchanger(configuration: configuration, session: session)
            .exchange(code: "abc123", verifier: "verifier-1")

        #expect(token.accessToken == "hf_abc")
        #expect(token.refreshToken == "r1")
        #expect(token.expiresAt != nil)

        let body = try #require(StubURLProtocol.bodies(for: session).first)
        let form = try #require(String(bytes: body, encoding: .utf8))
        #expect(form.contains("grant_type=authorization_code"))
        #expect(form.contains("code_verifier=verifier-1"))
        #expect(form.contains("client_id=client-1"))
        #expect(!form.contains("client_secret"))
    }

    /// The Hub answers with `accessToken`, not `access_token`, often enough that
    /// the daemon reads both — so this does too.
    @Test("a camelCase token key is read just the same")
    func readsCamelCaseToken() async throws {
        let token = try await exchanger([
            "/oauth/token": .init(statusCode: 200, json: #"{"accessToken": "hf_abc", "expiresIn": 100}"#),
        ]).exchange(code: "abc123", verifier: "v")

        #expect(token.accessToken == "hf_abc")
    }

    @Test("a refused exchange throws rather than yielding an empty token")
    func reportsRefusedExchange() async {
        let exchanger = exchanger([
            "/oauth/token": .init(statusCode: 400, json: #"{"error": "invalid_grant"}"#),
        ])

        await #expect(throws: HFOAuthError.self) {
            try await exchanger.exchange(code: "abc123", verifier: "v")
        }
    }

    @Test("refreshing sends the refresh token under the right grant")
    func refreshesAToken() async throws {
        let session = StubURLProtocol.makeSession([
            "/oauth/token": .init(statusCode: 200, json: #"{"access_token": "hf_new", "expires_in": 100}"#),
        ])
        let existing = HFToken(accessToken: "hf_old", refreshToken: "r1", expiresAt: .distantPast)

        let token = try await HFTokenExchanger(configuration: configuration, session: session).refreshing(existing)

        #expect(token.accessToken == "hf_new")
        let form = try #require(String(bytes: StubURLProtocol.bodies(for: session).first ?? Data(), encoding: .utf8))
        #expect(form.contains("grant_type=refresh_token"))
        #expect(form.contains("refresh_token=r1"))
    }

    /// A token with no refresh token cannot be renewed — the user has to sign in
    /// again, which through Safari's cookies is one tap.
    @Test("a token that cannot be refreshed says so instead of trying")
    func reportsUnrefreshableToken() async {
        let exchanger = exchanger([:])
        let existing = HFToken(accessToken: "hf_old", refreshToken: nil, expiresAt: .distantPast)

        #expect(existing.needsReauth(at: Date()))
        await #expect(throws: HFOAuthError.notRefreshable) {
            try await exchanger.refreshing(existing)
        }
    }

    // MARK: Personal access tokens

    /// The fallback path, and the only one that works until the OAuth app is
    /// registered. `whoami-v2` is what the daemon and central both validate with.
    @Test("a pasted token is validated against the Hub, not trusted")
    func validatesAPastedToken() async throws {
        let session = StubURLProtocol.makeSession([
            "/api/whoami-v2": .init(statusCode: 200, json: #"{"name": "alexey1312", "type": "user"}"#),
        ])

        let username = try await HFTokenExchanger(configuration: configuration, session: session)
            .username(for: "hf_pasted")

        #expect(username == "alexey1312")
        let request = try #require(StubURLProtocol.requests(for: session).first)
        #expect(request.value(forHTTPHeaderField: "Authorization") == "Bearer hf_pasted")
        #expect(request.url?.absoluteString.contains("hf_pasted") == false)
    }

    @Test("a token the Hub does not know is refused")
    func rejectsAnInvalidPastedToken() async {
        let exchanger = exchanger(["/api/whoami-v2": .init(statusCode: 401)])

        await #expect(throws: HFOAuthError.invalidToken) {
            try await exchanger.username(for: "nope")
        }
    }
}

import CryptoKit
import Foundation

/// Where this app's Hugging Face sign-in points, and as whom.
///
/// A **public** OAuth client: there is no secret, because a secret shipped inside
/// an app is not one. PKCE is what takes its place, and it is also what the daemon
/// uses for its own browser flow — so both ends speak the same protocol to the
/// same endpoints.
public struct HFOAuthConfiguration: Sendable, Equatable {
    public let clientID: String
    /// Registered with the OAuth app on the Hub. A custom scheme rather than a
    /// universal link: the robot is on a LAN, and this callback must resolve with
    /// no server of ours involved.
    public let redirectURI: String
    public let scopes: String

    public init(clientID: String, redirectURI: String, scopes: String) {
        self.clientID = clientID
        self.redirectURI = redirectURI
        self.scopes = scopes
    }

    /// The same set the robot asks for (`HF_OAUTH_SCOPES` in the daemon), so one
    /// token covers everything either end does: reading the app store, installing
    /// from a private Space, and reaching central.
    public static let reachyMiniScopes = "openid profile read-repos write-repos manage-repos inference-api"

    public static let callbackScheme = "reachy-mini-swift"

    /// Filled in once the OAuth app is registered at
    /// `huggingface.co/settings/applications/new`. Until then `isConfigured` is
    /// false and the personal-access-token path is the only way in — which is why
    /// that path is not a second-class citizen.
    public static let reachyMini = Self(
        clientID: "",
        redirectURI: "\(callbackScheme)://oauth-callback",
        scopes: reachyMiniScopes
    )

    public var isConfigured: Bool { !clientID.isEmpty }
}

public enum HFOAuthError: Error, Equatable, Sendable {
    /// The callback carried a state this app did not issue. The only thing
    /// standing between it and a code obtained by somebody else.
    case stateMismatch
    /// The Hub refused, usually because the user did.
    case denied(String)
    case missingCode
    case exchangeFailed(statusCode: Int)
    /// Expired with no refresh token. Not an error the app can fix — the user
    /// signs in again, which Safari's cookies usually make instant.
    case notRefreshable
    case invalidToken
    case notConfigured
}

extension HFOAuthError: LocalizedError {
    public var errorDescription: String? {
        switch self {
        case .stateMismatch:
            "The sign-in reply did not match this request"
        case let .denied(reason):
            "Hugging Face refused the sign-in (\(reason))"
        case .missingCode:
            "The sign-in reply carried no authorization code"
        case let .exchangeFailed(statusCode):
            "Hugging Face rejected the sign-in (HTTP \(statusCode))"
        case .notRefreshable:
            "This session has expired — sign in again"
        case .invalidToken:
            "Hugging Face does not recognise this token"
        case .notConfigured:
            "One-tap sign-in is not available in this build"
        }
    }
}

/// The parts of the flow that are pure: a PKCE pair, the authorize URL, and
/// reading the callback. Everything here is testable without a browser.
public enum HFOAuth {
    public static let authorizationEndpoint = "https://huggingface.co/oauth/authorize"
    public static let tokenEndpoint = "https://huggingface.co/oauth/token"
    /// What both the daemon and the central server validate a token with.
    public static let whoamiEndpoint = "https://huggingface.co/api/whoami-v2"

    /// Proof-key pair for a public client: the verifier stays in this process, and
    /// only its SHA-256 digest travels with the authorization request.
    public struct PKCE: Sendable, Equatable {
        public let verifier: String
        public let method = "S256"

        public var challenge: String {
            Self.base64URL(Data(SHA256.hash(data: Data(verifier.utf8))))
        }

        /// 32 random bytes, base64url-encoded — 43 characters, the RFC's minimum
        /// and a comfortable amount of entropy.
        public init() {
            var bytes = [UInt8](repeating: 0, count: 32)
            for index in bytes.indices {
                bytes[index] = UInt8.random(in: .min ... .max)
            }
            verifier = Self.base64URL(Data(bytes))
        }

        public init(verifier: String) {
            self.verifier = verifier
        }

        /// Unpadded, URL-safe — a `+`, `/` or `=` here is rejected by the Hub as an
        /// invalid grant, with no hint as to why.
        static func base64URL(_ data: Data) -> String {
            data.base64EncodedString()
                .replacingOccurrences(of: "+", with: "-")
                .replacingOccurrences(of: "/", with: "_")
                .replacingOccurrences(of: "=", with: "")
        }
    }

    public static func authorizationURL(
        configuration: HFOAuthConfiguration,
        pkce: PKCE,
        state: String
    ) -> URL? {
        guard var components = URLComponents(string: authorizationEndpoint) else { return nil }
        components.queryItems = [
            URLQueryItem(name: "client_id", value: configuration.clientID),
            URLQueryItem(name: "redirect_uri", value: configuration.redirectURI),
            URLQueryItem(name: "response_type", value: "code"),
            URLQueryItem(name: "scope", value: configuration.scopes),
            URLQueryItem(name: "state", value: state),
            URLQueryItem(name: "code_challenge", value: pkce.challenge),
            URLQueryItem(name: "code_challenge_method", value: pkce.method),
        ]
        return components.url
    }

    /// Reads the authorization code out of the callback, refusing anything whose
    /// state this app did not issue.
    public static func code(in url: URL, expectedState: String) throws -> String {
        let items = URLComponents(url: url, resolvingAgainstBaseURL: false)?.queryItems ?? []
        let query = Dictionary(items.map { ($0.name, $0.value ?? "") }, uniquingKeysWith: { first, _ in first })

        if let error = query["error"], !error.isEmpty {
            throw HFOAuthError.denied(error)
        }
        guard query["state"] == expectedState else {
            throw HFOAuthError.stateMismatch
        }
        guard let code = query["code"], !code.isEmpty else {
            throw HFOAuthError.missingCode
        }
        return code
    }
}

import Foundation

/// A Hugging Face credential held by *this app*, as opposed to the copy a robot
/// keeps once it is linked.
public struct HFToken: Sendable, Equatable, Codable {
    public let accessToken: String
    /// The Hub does not always issue one. Without it an expired session cannot be
    /// renewed silently — see `needsReauth(at:)`.
    public let refreshToken: String?
    public let expiresAt: Date?
    public let username: String?

    public init(accessToken: String, refreshToken: String? = nil, expiresAt: Date? = nil, username: String? = nil) {
        self.accessToken = accessToken
        self.refreshToken = refreshToken
        self.expiresAt = expiresAt
        self.username = username
    }

    /// A minute of headroom: a token that expires while a request is in flight
    /// fails in a way that reads as a network error rather than a sign-in one.
    public func isExpired(at now: Date, headroom: TimeInterval = 60) -> Bool {
        guard let expiresAt else { return false }
        return expiresAt.addingTimeInterval(-headroom) <= now
    }

    /// Expired and unrenewable. The user has to sign in again — which, through
    /// Safari's shared cookies, is usually a single tap.
    public func needsReauth(at now: Date) -> Bool {
        isExpired(at: now) && refreshToken == nil
    }

    public func named(_ username: String?) -> HFToken {
        HFToken(accessToken: accessToken, refreshToken: refreshToken, expiresAt: expiresAt, username: username)
    }
}

/// Somewhere to keep the token between launches.
///
/// A protocol so the account model can be exercised without a Keychain — and so
/// previews can run against an inert one.
public protocol HFTokenStoring: Sendable {
    func load() throws -> HFToken?
    func save(_ token: HFToken) throws
    func clear() throws
}

/// In-memory custody, for previews and tests.
public final class InMemoryHFTokenStore: HFTokenStoring, @unchecked Sendable {
    private let lock = NSLock()
    private var token: HFToken?

    public init(token: HFToken? = nil) {
        self.token = token
    }

    public func load() throws -> HFToken? {
        lock.withLock { token }
    }

    public func save(_ token: HFToken) throws {
        lock.withLock { self.token = token }
    }

    public func clear() throws {
        lock.withLock { token = nil }
    }
}

import Foundation

/// The network half of the sign-in: swapping a code for a token, renewing one,
/// and asking the Hub who a token belongs to.
public protocol HFTokenExchanging: Sendable {
    func exchange(code: String, verifier: String) async throws -> HFToken
    func refreshing(_ token: HFToken) async throws -> HFToken
    /// Validates a token — a pasted personal access token, or one just issued —
    /// and answers with the account it belongs to.
    func username(for token: String) async throws -> String
}

public struct HFTokenExchanger: HFTokenExchanging {
    private let configuration: HFOAuthConfiguration
    private let session: URLSession

    public init(configuration: HFOAuthConfiguration = .reachyMini, session: URLSession = .shared) {
        self.configuration = configuration
        self.session = session
    }

    public func exchange(code: String, verifier: String) async throws -> HFToken {
        try await token(form: [
            "grant_type": "authorization_code",
            "client_id": configuration.clientID,
            "code": code,
            "redirect_uri": configuration.redirectURI,
            // PKCE stands in for the client secret a public client cannot keep.
            "code_verifier": verifier,
        ])
    }

    public func refreshing(_ token: HFToken) async throws -> HFToken {
        guard let refreshToken = token.refreshToken else {
            throw HFOAuthError.notRefreshable
        }
        let renewed = try await self.token(form: [
            "grant_type": "refresh_token",
            "client_id": configuration.clientID,
            "refresh_token": refreshToken,
        ])
        return renewed.named(renewed.username ?? token.username)
    }

    public func username(for token: String) async throws -> String {
        guard let url = URL(string: HFOAuth.whoamiEndpoint) else {
            throw HFOAuthError.notConfigured
        }
        var request = URLRequest(url: url)
        // Header, never a query parameter: a token in a URL ends up in access logs
        // on every hop between here and the Hub.
        request.setValue("Bearer \(token)", forHTTPHeaderField: "Authorization")

        let (data, response) = try await session.data(for: request)
        guard let http = response as? HTTPURLResponse else {
            throw HFOAuthError.invalidToken
        }
        guard http.statusCode == 200 else {
            throw http.statusCode == 401 || http.statusCode == 403
                ? HFOAuthError.invalidToken
                : HFOAuthError.exchangeFailed(statusCode: http.statusCode)
        }
        struct Whoami: Decodable {
            let name: String
        }
        guard let whoami = try? JSONDecoder().decode(Whoami.self, from: data), !whoami.name.isEmpty else {
            throw HFOAuthError.invalidToken
        }
        return whoami.name
    }

    private func token(form: [String: String]) async throws -> HFToken {
        guard let url = URL(string: HFOAuth.tokenEndpoint) else {
            throw HFOAuthError.notConfigured
        }
        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.setValue("application/x-www-form-urlencoded", forHTTPHeaderField: "Content-Type")
        request.httpBody = Data(Self.encoded(form).utf8)

        let (data, response) = try await session.data(for: request)
        guard let http = response as? HTTPURLResponse else {
            throw HFOAuthError.exchangeFailed(statusCode: -1)
        }
        guard http.statusCode == 200 else {
            throw HFOAuthError.exchangeFailed(statusCode: http.statusCode)
        }
        return try Self.decodeToken(data)
    }

    /// `URLComponents` does the percent-encoding, but its rules for a *query* let
    /// `+` through — and in a form body a `+` decodes as a space, which silently
    /// corrupts a verifier or a refresh token.
    static func encoded(_ form: [String: String]) -> String {
        var allowed = CharacterSet.alphanumerics
        allowed.insert(charactersIn: "-._~")
        return form
            .sorted { $0.key < $1.key }
            .map { key, value in
                let encoded = value.addingPercentEncoding(withAllowedCharacters: allowed) ?? value
                return "\(key)=\(encoded)"
            }
            .joined(separator: "&")
    }

    /// The Hub answers with `accessToken` often enough that the daemon reads both
    /// spellings; so does this.
    static func decodeToken(_ data: Data) throws -> HFToken {
        struct Payload: Decodable {
            let accessToken: String?
            let accessTokenSnake: String?
            let refreshToken: String?
            let refreshTokenSnake: String?
            let expiresIn: Double?
            let expiresInSnake: Double?

            enum CodingKeys: String, CodingKey {
                case accessToken
                case accessTokenSnake = "access_token"
                case refreshToken
                case refreshTokenSnake = "refresh_token"
                case expiresIn
                case expiresInSnake = "expires_in"
            }
        }

        guard let payload = try? JSONDecoder().decode(Payload.self, from: data),
              let accessToken = payload.accessTokenSnake ?? payload.accessToken,
              !accessToken.isEmpty
        else {
            throw HFOAuthError.exchangeFailed(statusCode: 200)
        }
        let lifetime = payload.expiresInSnake ?? payload.expiresIn
        return HFToken(
            accessToken: accessToken,
            refreshToken: payload.refreshTokenSnake ?? payload.refreshToken,
            expiresAt: lifetime.map { Date().addingTimeInterval($0) }
        )
    }
}

import Foundation
@testable import ReachyKit
import Testing

/// Scripted stand-in for the Hub. Records what it was asked so a test can prove a
/// token was validated rather than trusted.
private final class FakeExchanger: HFTokenExchanging, @unchecked Sendable {
    private let lock = NSLock()
    private(set) var exchanged: [(code: String, verifier: String)] = []
    private(set) var refreshCalls = 0
    private(set) var validated: [String] = []
    var username = "alexey1312"
    var rejectsTokens = false

    func exchange(code: String, verifier: String) async throws -> HFToken {
        lock.withLock { exchanged.append((code, verifier)) }
        return HFToken(accessToken: "hf_new", refreshToken: "r1", expiresAt: Date().addingTimeInterval(3600))
    }

    func refreshing(_ token: HFToken) async throws -> HFToken {
        lock.withLock { refreshCalls += 1 }
        guard token.refreshToken != nil else { throw HFOAuthError.notRefreshable }
        return HFToken(
            accessToken: "hf_refreshed",
            refreshToken: token.refreshToken,
            expiresAt: Date().addingTimeInterval(3600),
            username: token.username
        )
    }

    func username(for token: String) async throws -> String {
        lock.withLock { validated.append(token) }
        if rejectsTokens {
            throw HFOAuthError.invalidToken
        }
        return username
    }
}

@MainActor
@Suite("Hugging Face account", .timeLimit(.minutes(1)))
struct HFAccountTests {
    private let configuration = HFOAuthConfiguration(
        clientID: "client-1",
        redirectURI: "reachy-mini-swift://oauth-callback",
        scopes: HFOAuthConfiguration.reachyMiniScopes
    )

    private func account(
        store: any HFTokenStoring = InMemoryHFTokenStore(),
        exchanger: FakeExchanger = FakeExchanger(),
        configuration: HFOAuthConfiguration? = nil
    ) -> HFAccount {
        HFAccount(
            configuration: configuration ?? self.configuration,
            store: store,
            exchanger: exchanger
        )
    }

    @Test("a fresh install is signed out")
    func startsSignedOut() {
        let account = account()
        account.restore()

        #expect(account.state == .signedOut)
    }

    @Test("a stored token signs the user straight back in")
    func restoresAStoredToken() {
        let store = InMemoryHFTokenStore(
            token: HFToken(accessToken: "hf_old", expiresAt: .distantFuture, username: "alexey1312")
        )
        let account = account(store: store)

        account.restore()

        #expect(account.state == .signedIn(username: "alexey1312"))
    }

    /// Expired with nothing to renew it. Worth its own state rather than a plain
    /// signed-out: the app knows whose session lapsed, and signing in again through
    /// Safari's cookies is one tap.
    @Test("an expired token with nothing to renew it asks for a new sign-in")
    func reportsNeedsReauth() {
        let store = InMemoryHFTokenStore(
            token: HFToken(accessToken: "hf_old", refreshToken: nil, expiresAt: .distantPast, username: "alexey1312")
        )
        let account = account(store: store)

        account.restore()

        #expect(account.state == .needsReauth(username: "alexey1312"))
    }

    @Test("without a registered client id there is nothing to open")
    func refusesToStartUnconfigured() {
        let account = account(configuration: .reachyMini)

        #expect(account.canSignInWithBrowser == false)
        #expect(throws: HFOAuthError.notConfigured) {
            try account.beginSignIn()
        }
    }

    @Test("starting a sign-in produces the URL to open")
    func beginsSignIn() throws {
        let account = account()

        let url = try account.beginSignIn()

        #expect(url.absoluteString.hasPrefix("https://huggingface.co/oauth/authorize?"))
        #expect(account.state == .signingIn)
    }

    /// A callback carrying somebody else's state must not become a session — and
    /// must not leave a token behind either.
    @Test("a callback this app did not ask for is refused")
    func refusesAForeignCallback() async throws {
        let store = InMemoryHFTokenStore()
        let exchanger = FakeExchanger()
        let account = account(store: store, exchanger: exchanger)
        _ = try account.beginSignIn()

        await account.completeSignIn(
            callback: URL(string: "reachy-mini-swift://oauth-callback?code=abc&state=someone-else")!
        )

        #expect(exchanger.exchanged.isEmpty)
        #expect(try store.load() == nil)
        if case .failed = account.state {} else {
            Issue.record("expected a failed sign-in, got \(account.state)")
        }
    }

    @Test("a successful callback stores the token and names the account")
    func completesSignIn() async throws {
        let store = InMemoryHFTokenStore()
        let exchanger = FakeExchanger()
        let account = account(store: store, exchanger: exchanger)
        let url = try account.beginSignIn()
        let state = try #require(URLComponents(url: url, resolvingAgainstBaseURL: false)?
            .queryItems?.first { $0.name == "state" }?.value)

        await account.completeSignIn(
            callback: URL(string: "reachy-mini-swift://oauth-callback?code=abc&state=\(state)")!
        )

        #expect(account.state == .signedIn(username: "alexey1312"))
        #expect(exchanger.exchanged.first?.code == "abc")
        #expect(try store.load()?.accessToken == "hf_new")
        #expect(try store.load()?.username == "alexey1312")
    }

    /// The fallback path, and the only one that works until the OAuth app exists.
    @Test("a pasted token is validated before it is kept")
    func acceptsAValidatedPastedToken() async throws {
        let store = InMemoryHFTokenStore()
        let exchanger = FakeExchanger()
        let account = account(store: store, exchanger: exchanger)

        await account.signIn(pastedToken: "hf_pasted")

        #expect(exchanger.validated == ["hf_pasted"])
        #expect(account.state == .signedIn(username: "alexey1312"))
        #expect(try store.load()?.accessToken == "hf_pasted")
    }

    @Test("a pasted token the Hub rejects is not kept")
    func rejectsAnInvalidPastedToken() async throws {
        let store = InMemoryHFTokenStore()
        let exchanger = FakeExchanger()
        exchanger.rejectsTokens = true
        let account = account(store: store, exchanger: exchanger)

        await account.signIn(pastedToken: "nope")

        #expect(try store.load() == nil)
        if case .failed = account.state {} else {
            Issue.record("expected a failed sign-in, got \(account.state)")
        }
    }

    @Test("signing out forgets the token")
    func signsOut() throws {
        let store = InMemoryHFTokenStore(token: HFToken(accessToken: "hf_old", expiresAt: .distantFuture))
        let account = account(store: store)
        account.restore()

        account.signOut()

        #expect(account.state == .signedOut)
        #expect(try store.load() == nil)
    }

    /// Renewal happens on the way to a request, not on a timer: nothing else knows
    /// when the token is about to be needed.
    @Test("an expiring token is renewed on use and the renewal is kept")
    func refreshesOnDemand() async throws {
        let store = InMemoryHFTokenStore(
            token: HFToken(accessToken: "hf_old", refreshToken: "r1", expiresAt: .distantPast, username: "alexey1312")
        )
        let exchanger = FakeExchanger()
        let account = account(store: store, exchanger: exchanger)
        account.restore()

        let token = await account.currentToken()

        #expect(token == "hf_refreshed")
        #expect(exchanger.refreshCalls == 1)
        #expect(try store.load()?.accessToken == "hf_refreshed")
        #expect(account.state == .signedIn(username: "alexey1312"))
    }

    @Test("a token that is still good is used as it is")
    func usesAValidTokenUnchanged() async throws {
        let store = InMemoryHFTokenStore(
            token: HFToken(accessToken: "hf_good", expiresAt: .distantFuture, username: "alexey1312")
        )
        let exchanger = FakeExchanger()
        let account = account(store: store, exchanger: exchanger)
        account.restore()

        #expect(await account.currentToken() == "hf_good")
        #expect(exchanger.refreshCalls == 0)
    }

    @Test("a signed-out app has no token to offer")
    func offersNoTokenWhenSignedOut() async {
        let account = account()
        account.restore()

        #expect(await account.currentToken() == nil)
    }
}

import Foundation
import Observation

/// This app's own Hugging Face session: what it holds, and how it got it.
///
/// Deliberately separate from a robot's account. Signing in here is what makes
/// "Your Reachies" possible at all — it is how central knows whose robots to
/// list — and linking a robot is a second, explicit act.
///
/// The browser is not here. Opening a URL and receiving the callback belongs to
/// the UI layer, which has `ASWebAuthenticationSession`; this owns the parts that
/// have to be right whether or not a browser is involved.
@MainActor
@Observable
public final class HFAccount {
    public enum State: Equatable, Sendable {
        case signedOut
        case signingIn
        case signedIn(username: String)
        /// The session lapsed and cannot be renewed silently. The username is kept
        /// so the prompt can name whose session it was.
        case needsReauth(username: String?)
        case failed(String)
    }

    public private(set) var state: State = .signedOut

    private let configuration: HFOAuthConfiguration
    private let store: any HFTokenStoring
    private let exchanger: any HFTokenExchanging
    private let now: @Sendable () -> Date
    private var token: HFToken?
    /// The PKCE pair and state of the sign-in currently in flight. Held here so a
    /// callback can be checked against what this app actually asked for.
    private var pending: (pkce: HFOAuth.PKCE, state: String)?

    public init(
        configuration: HFOAuthConfiguration = .reachyMini,
        store: any HFTokenStoring = InMemoryHFTokenStore(),
        exchanger: (any HFTokenExchanging)? = nil,
        now: @escaping @Sendable () -> Date = { Date() }
    ) {
        self.configuration = configuration
        self.store = store
        self.exchanger = exchanger ?? HFTokenExchanger(configuration: configuration)
        self.now = now
    }

    /// False until the OAuth app is registered on the Hub. The pasted-token path
    /// stays available either way, which is what makes this an honest question for
    /// a screen to ask rather than a dead button.
    public var canSignInWithBrowser: Bool {
        configuration.isConfigured
    }

    public var username: String? {
        switch state {
        case let .signedIn(username): username
        case let .needsReauth(username): username
        default: nil
        }
    }

    /// Reads whatever the last launch left behind. Cheap and offline — the token's
    /// own expiry is enough to decide, with no call to the Hub.
    public func restore() {
        token = try? store.load()
        guard let token else {
            state = .signedOut
            return
        }
        state = token.needsReauth(at: now())
            ? .needsReauth(username: token.username)
            : .signedIn(username: token.username ?? "")
    }

    /// The URL to open in the browser. Remembers the PKCE pair the callback will
    /// be checked against.
    public func beginSignIn() throws -> URL {
        guard configuration.isConfigured else { throw HFOAuthError.notConfigured }
        let pkce = HFOAuth.PKCE()
        let state = UUID().uuidString
        guard let url = HFOAuth.authorizationURL(configuration: configuration, pkce: pkce, state: state) else {
            throw HFOAuthError.notConfigured
        }
        pending = (pkce, state)
        self.state = .signingIn
        return url
    }

    /// Finishes what `beginSignIn()` started. Refuses a callback whose state this
    /// app did not issue, and never stores a token it could not attribute.
    public func completeSignIn(callback: URL) async {
        guard let pending else {
            state = .failed(HFOAuthError.stateMismatch.localizedDescription)
            return
        }
        self.pending = nil
        do {
            let code = try HFOAuth.code(in: callback, expectedState: pending.state)
            let issued = try await exchanger.exchange(code: code, verifier: pending.pkce.verifier)
            let username = try await exchanger.username(for: issued.accessToken)
            try keep(issued.named(username))
            state = .signedIn(username: username)
        } catch {
            state = .failed(Self.describe(error))
        }
    }

    /// The personal-access-token path: the way in without a registered OAuth app,
    /// and the way in for anyone who would rather not use a browser at all.
    public func signIn(pastedToken: String) async {
        let trimmed = pastedToken.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            state = .failed(HFOAuthError.invalidToken.localizedDescription)
            return
        }
        state = .signingIn
        do {
            // Validated against the Hub rather than pattern-matched: a token that
            // looks right and is not would fail later, somewhere less explicable.
            let username = try await exchanger.username(for: trimmed)
            try keep(HFToken(accessToken: trimmed, username: username))
            state = .signedIn(username: username)
        } catch {
            state = .failed(Self.describe(error))
        }
    }

    /// Forgets this app's token. A robot that was linked keeps its own copy — that
    /// is a separate act to undo, and doing it silently here would leave the user
    /// believing a robot went offline when it did not.
    public func signOut() {
        try? store.clear()
        token = nil
        pending = nil
        state = .signedOut
    }

    /// The token to put in an `Authorization` header, renewed first if it is due.
    ///
    /// Renewal happens here rather than on a timer because this is the only moment
    /// that knows the token is about to be used.
    public func currentToken() async -> String? {
        guard let token else { return nil }
        guard token.isExpired(at: now()) else { return token.accessToken }
        do {
            let renewed = try await exchanger.refreshing(token)
            try keep(renewed)
            state = .signedIn(username: renewed.username ?? "")
            return renewed.accessToken
        } catch {
            state = .needsReauth(username: token.username)
            return nil
        }
    }

    private func keep(_ token: HFToken) throws {
        try store.save(token)
        self.token = token
    }

    private static func describe(_ error: any Error) -> String {
        (error as? LocalizedError)?.errorDescription ?? error.localizedDescription
    }
}

import Foundation
@testable import ReachyKit
import Testing

/// A SwiftPM test binary is unsigned, and an unsigned process cannot always reach
/// a keychain — on a CI machine with no login keychain unlocked, every call comes
/// back `errSecMissingEntitlement`. Probing once decides whether these tests can
/// say anything at all, rather than failing for a reason that has nothing to do
/// with the code.
private enum KeychainProbe {
    static let isUsable: Bool = {
        let store = KeychainHFTokenStore(service: "com.alexey1312.ReachyMini.probe")
        defer { try? store.clear() }
        do {
            try store.save(HFToken(accessToken: "probe"))
            return true
        } catch {
            return false
        }
    }()
}

@Suite("Keychain token store", .enabled(if: KeychainProbe.isUsable), .serialized)
struct KeychainHFTokenStoreTests {
    /// One service per test: `.serialized` orders tests inside this suite, but the
    /// keychain is shared with every other process on the machine.
    private func store(_ label: String = #function) -> KeychainHFTokenStore {
        KeychainHFTokenStore(service: "com.alexey1312.ReachyMini.tests.\(label)")
    }

    @Test("a token survives a round trip")
    func roundTripsAToken() throws {
        let store = store()
        defer { try? store.clear() }
        let token = HFToken(
            accessToken: "hf_abc",
            refreshToken: "r1",
            expiresAt: Date(timeIntervalSince1970: 1_800_000_000),
            username: "alexey1312"
        )

        try store.save(token)

        #expect(try store.load() == token)
    }

    @Test("nothing stored reads as nothing, not as an error")
    func readsEmptyAsNil() throws {
        #expect(try store().load() == nil)
    }

    /// Signing in twice must replace the token, not fail on the second attempt —
    /// `SecItemAdd` answers `errSecDuplicateItem` for an item that already exists.
    @Test("saving twice replaces the first token")
    func overwritesAnExistingToken() throws {
        let store = store()
        defer { try? store.clear() }

        try store.save(HFToken(accessToken: "hf_first"))
        try store.save(HFToken(accessToken: "hf_second"))

        #expect(try store.load()?.accessToken == "hf_second")
    }

    @Test("clearing removes the token, and clearing again is not an error")
    func clearsIdempotently() throws {
        let store = store()
        try store.save(HFToken(accessToken: "hf_abc"))

        try store.clear()
        try store.clear()

        #expect(try store.load() == nil)
    }
}

import Foundation
import Security

/// Keeps this app's Hugging Face token in the Keychain.
///
/// The first Keychain code in the project, and where ADR 0001 said credentials
/// belong. Written against `Security` directly rather than a wrapper: the whole
/// surface is three calls, and a dependency that holds a credential is one more
/// thing to audit.
///
/// The item is `ThisDeviceOnly` — it does not travel to iCloud Keychain or into a
/// backup. A token restored onto another device would be one the user never
/// knowingly put there, and re-signing in costs a tap.
public struct KeychainHFTokenStore: HFTokenStoring {
    public enum Failure: Error, Equatable {
        case keychain(OSStatus)
    }

    private let service: String
    private let account: String

    public init(
        service: String = "com.alexey1312.ReachyMini.huggingface",
        account: String = "oauth-token"
    ) {
        self.service = service
        self.account = account
    }

    public func load() throws -> HFToken? {
        var query = baseQuery
        query[kSecReturnData as String] = true
        query[kSecMatchLimit as String] = kSecMatchLimitOne

        var result: CFTypeRef?
        let status = SecItemCopyMatching(query as CFDictionary, &result)
        switch status {
        case errSecSuccess:
            guard let data = result as? Data else { return nil }
            // A token this app can no longer parse is not an error worth
            // propagating — it reads as signed out, and the next sign-in
            // overwrites it.
            return try? JSONDecoder().decode(HFToken.self, from: data)
        case errSecItemNotFound:
            return nil
        default:
            throw Failure.keychain(status)
        }
    }

    public func save(_ token: HFToken) throws {
        let data = try JSONEncoder().encode(token)

        // Signing in again must replace what is there; `SecItemAdd` alone answers
        // `errSecDuplicateItem` the second time.
        let update = SecItemUpdate(
            baseQuery as CFDictionary,
            [kSecValueData as String: data] as CFDictionary
        )
        if update == errSecSuccess {
            return
        }
        guard update == errSecItemNotFound else {
            throw Failure.keychain(update)
        }

        var item = baseQuery
        item[kSecValueData as String] = data
        item[kSecAttrAccessible as String] = kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly
        let status = SecItemAdd(item as CFDictionary, nil)
        guard status == errSecSuccess else {
            throw Failure.keychain(status)
        }
    }

    public func clear() throws {
        let status = SecItemDelete(baseQuery as CFDictionary)
        guard status == errSecSuccess || status == errSecItemNotFound else {
            throw Failure.keychain(status)
        }
    }

    private var baseQuery: [String: Any] {
        [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: account,
        ]
    }
}

