3	/// Serves canned HTTP responses to a `URLSession` injected into `RobotConnection`,
4	/// which is the only way to exercise daemon status codes without a daemon.
5	///
6	/// Stubs bind to the session that carries them, not to a global table: `swift test
7	/// --parallel` runs separate suites concurrently, so a shared table lets one suite
8	/// answer another suite's requests, or wipe them mid-flight. `.serialized` is no
9	/// defence — it orders tests within one suite and says nothing about the others.
10	final class StubURLProtocol: URLProtocol {
11	    struct Stub: Sendable {
12	        let statusCode: Int
13	        let body: Data
14	
15	        init(statusCode: Int, json: String = "{}") {
16	            self.statusCode = statusCode
17	            body = Data(json.utf8)
18	        }
19	    }
20	
21	    /// Routes are keyed by path, optionally narrowed by a query:
22	    /// `/update/available` answers whatever the query is, while
23	    /// `/update/available?pre_release=true` answers only that one. The narrower key
24	    /// wins, so a table can pin one variant and let the bare path cover the rest —
25	    /// without it, `pre_release=true` and `false` collapse onto a single stub.
26	    static func makeSession(_ stubs: [String: Stub]) -> URLSession {
27	        let token = UUID().uuidString
28	        lock.withLock { sessions[token] = stubs }
29	
30	        let configuration = URLSessionConfiguration.ephemeral
31	        configuration.protocolClasses = [StubURLProtocol.self]
32	        configuration.httpAdditionalHeaders = [tokenHeader: token]
33	        return URLSession(configuration: configuration)
34	    }
35	
36	    /// What this session was actually asked for, in order. The sealed Wi-Fi payload is
37	    /// the reason this exists: a test has to be able to prove the password never
38	    /// appeared in a URL.
39	    static func requests(for session: URLSession) -> [URLRequest] {
40	        served(for: session).map(\.request)
41	    }
42	
43	    /// Sent bodies, in the same order as `requests(for:)`.
44	    ///
45	    /// `URLRequest.httpBody` is nil by the time a protocol sees an upload — the
46	    /// payload arrives as a stream — so it is drained here. `POST /apps/install`
47	    /// is the reason: the daemon stores that body as the app's metadata, and only
48	    /// the bytes on the wire prove nothing was dropped on the way.
49	    static func bodies(for session: URLSession) -> [Data] {
50	        served(for: session).map(\.body)
51	    }
52	
53	    private struct Served {
54	        let request: URLRequest
55	        let body: Data
56	    }
57	
58	    private static func served(for session: URLSession) -> [Served] {
59	        guard let token = session.configuration.httpAdditionalHeaders?[tokenHeader] as? String else {
60	            return []
61	        }
62	        return lock.withLock { served[token] ?? [] }
63	    }
64	
65	    private static let tokenHeader = "X-Stub-Session"
66	    private nonisolated(unsafe) static var sessions: [String: [String: Stub]] = [:]
67	    private nonisolated(unsafe) static var served: [String: [Served]] = [:]
68	    private static let lock = NSLock()
69	
70	    private static func record(_ request: URLRequest) {
71	        guard let token = request.value(forHTTPHeaderField: tokenHeader) else { return }
72	        let body = request.httpBody ?? request.httpBodyStream.map(drain) ?? Data()
73	        lock.withLock { served[token, default: []].append(Served(request: request, body: body)) }
74	    }
75	
76	    private static func drain(_ stream: InputStream) -> Data {
77	        stream.open()
78	        defer { stream.close() }
79	        var data = Data()
80	        var buffer = [UInt8](repeating: 0, count: 4096)
81	        while stream.hasBytesAvailable {
82	            let read = stream.read(&buffer, maxLength: buffer.count)
83	            guard read > 0 else { break }
84	            data.append(buffer, count: read)
85	        }
86	        return data
87	    }
88	
89	    private static func stub(for request: URLRequest) -> Stub? {
90	        guard let token = request.value(forHTTPHeaderField: tokenHeader),
91	              let url = request.url,
92	              let table = lock.withLock({ sessions[token] })
93	        else { return nil }
94	
95	        if let query = url.query(), let narrow = table["\(url.path)?\(query)"] {
96	            return narrow
97	        }
98	        return table[url.path]
99	    }
100	
101	    override static func canInit(with _: URLRequest) -> Bool {
102	        true
103	    }
104	
105	    override static func canonicalRequest(for request: URLRequest) -> URLRequest {
106	        request
107	    }
108	
109	    override func startLoading() {
110	        Self.record(request)
111	        guard let url = request.url,
112	              let stub = Self.stub(for: request),
113	              let response = HTTPURLResponse(
114	                  url: url,
115	                  statusCode: stub.statusCode,
116	                  httpVersion: "HTTP/1.1",
117	                  headerFields: ["Content-Type": "application/json"]
118	              )
119	        else {
120	            client?.urlProtocol(self, didFailWithError: URLError(.unsupportedURL))
121	            return
122	        }
123	        client?.urlProtocol(self, didReceive: response, cacheStoragePolicy: .notAllowed)
124	        client?.urlProtocol(self, didLoad: stub.body)
125	        client?.urlProtocolDidFinishLoading(self)
126	    }
127	
128	    override func stopLoading() {}
129	}
