5	/// Drives one robot software update: check, start, stream the log, wait out the
6	/// restart, confirm the new version.
7	@MainActor
8	@Observable
9	final class SystemUpdateModel {
10	    enum State: Equatable {
11	        case idle
12	        case checking
13	        case upToDate(current: String)
14	        /// The robot itself has no route to PyPI. Nothing the app can fix.
15	        case robotOffline(current: String)
16	        case available(current: String, latest: String)
17	        case installing
18	        /// The log socket closed, which is what the daemon restarting looks like.
19	        case restarting
20	        case finished(version: String)
21	        case failed(String)
22	    }
23	
24	    private(set) var state: State = .idle
25	    /// Shared with `LogConsoleView`, so pip output gets the same filter, pause and
26	    /// export the daemon journal has.
27	    let log = LogConsoleModel()
28	
29	    private let session: RobotSession
30	    /// The two steps that cannot be driven through a stubbed client: one needs a live
31	    /// WebSocket, the other waits out a real reboot. Injected by tests only.
32	    private let makeEvents: (String) throws -> AsyncStream<UpdateLogEvent>
33	    private let reconnect: () async -> String?
34	
35	    init(
36	        session: RobotSession,
37	        events: ((String) throws -> AsyncStream<UpdateLogEvent>)? = nil,
38	        reconnect: (() async -> String?)? = nil
39	    ) {
40	        self.session = session
41	        makeEvents = events ?? { [session] jobID in try session.updateLog(jobID: jobID) }
42	        self.reconnect = reconnect ?? { [session] in await session.reconnectAfterUpdate() }
43	    }
44	
45	    var isBusy: Bool {
46	        switch state {
47	        case .checking, .installing, .restarting: true
48	        default: false
49	        }
50	    }
51	
52	    func check(preRelease: Bool) async {
53	        state = .checking
54	        do {
55	            state = switch try await session.availableUpdate(preRelease: preRelease) {
56	            case let .upToDate(current): .upToDate(current: current)
57	            case let .robotOffline(current): .robotOffline(current: current)
58	            case let .available(current, latest): .available(current: current, latest: latest)
59	            }
60	        } catch {
61	            state = .failed(describe(error))
62	        }
63	    }
64	
65	    /// Runs to a terminal state. The daemon dies mid-stream by design, so the socket
66	    /// closing is treated as "installed, now rebooting" rather than as a failure.
67	    func install(preRelease: Bool) async {
68	        guard case let .available(current, _) = state else { return }
69	        state = .installing
70	        log.clear()
71	
72	        let jobID: String
73	        do {
74	            jobID = try await session.startUpdate(preRelease: preRelease)
75	        } catch {
76	            state = .failed(describe(error))
77	            return
78	        }
79	
80	        do {
81	            for await event in try makeEvents(jobID) {
82	                switch event {
83	                case let .line(line):
84	                    log.ingest(line)
85	                case let .status(status):
86	                    if status == .failed {
87	                        state = .failed("The robot reported that the update failed.")
88	                        return
89	                    }
90	                case let .rejected(reason):
91	                    state = .failed(reason)
92	                    return
93	                case .closed:
94	                    break
95	                }
96	            }
97	        } catch {
98	            state = .failed(describe(error))
99	            return
100	        }
101	
102	        state = .restarting
103	        await confirmRestart(from: current)
104	    }
105	
106	    private func confirmRestart(from previous: String) async {
107	        guard let version = await reconnect() else {
108	            state = .failed("The robot did not come back after the update. Power-cycle it and try again.")
109	            return
110	        }
111	        guard version != previous else {
112	            state = .failed(
113	                "The update finished but the robot still reports \(version). "
114	                    + "A new enough release may not be published yet."
115	            )
116	            return
117	        }
118	        state = .finished(version: version)
119	    }
120	
121	    private func describe(_ error: Error) -> String {
122	        (error as? LocalizedError)?.errorDescription ?? error.localizedDescription
123	    }
124	}
125	
126	#if DEBUG
127	    extension SystemUpdateModel {
128	        /// One update parked mid-flight. `events` and `reconnect` are stubbed out rather than
129	        /// left at their defaults: the real ones open a WebSocket and wait out a reboot.
130	        static func preview(
131	            state: State,
132	            session: RobotSession? = nil,
