        // Stable across launches: the same app must not change colour on a reload.
        #expect(dance.colors == AppArtwork(app: JSONDecoder().decode(RobotApp.self, from: Data(#"""
        {"name": "dance_party", "source_kind": "installed", "extra": {}}
        """#.utf8))).colors)
    }
