import ReachyKit
import SwiftUI

/// One app in the store list.
struct AppStoreRow: View {
    let app: RobotApp
    var isInstalled = false
    var isRunning = false
    var hasUpdate = false
    var isStartupApp = false

    var body: some View {
        HStack(spacing: 12) {
            AppArtworkTile(app: app)
            VStack(alignment: .leading, spacing: 3) {
                HStack(spacing: 5) {
                    Text(app.title)
                        .font(.headline)
                        .lineLimit(1)
                    if app.isOfficial {
                        Image(systemName: "checkmark.seal.fill")
                            .foregroundStyle(.tint)
                            .accessibilityLabel("Official")
                    }
                    if app.isPrivate {
                        Image(systemName: "lock.fill")
                            .foregroundStyle(.secondary)
                            .accessibilityLabel("Private")
                    }
                }
                .font(.caption)

                if let subtitle {
                    Text(subtitle)
                        .font(.subheadline)
                        .foregroundStyle(.secondary)
                        .lineLimit(2)
                }

                if let footnote {
                    Text(footnote)
                        .font(.caption)
                        .foregroundStyle(.secondary)
                }
            }
            Spacer(minLength: 8)
            trailing
        }
        .padding(.vertical, 4)
    }

    private var subtitle: String? {
        app.summary ?? app.author
    }

    /// Author and likes are all the Hub offers as a reputation signal, and the
    /// only way to tell two similarly named apps apart.
    private var footnote: String? {
        var parts: [String] = []
        if let author = app.author, app.summary != nil {
            parts.append(author)
        }
        if let likes = app.likes, likes > 0 {
            parts.append("♥ \(likes)")
        }
        if isStartupApp {
            parts.append("Starts on wake-up")
        }
        return parts.isEmpty ? nil : parts.joined(separator: " · ")
    }

    @ViewBuilder
    private var trailing: some View {
        if isRunning {
            Label("Running", systemImage: "waveform")
                .labelStyle(.iconOnly)
                .foregroundStyle(.tint)
                .symbolEffect(.variableColor.iterative)
                .accessibilityLabel("Running")
        } else if hasUpdate {
            Text("Update")
                .font(.caption.weight(.semibold))
                .padding(.horizontal, 10)
                .padding(.vertical, 4)
                .background(.tint, in: .capsule)
                .foregroundStyle(.white)
        } else if isInstalled {
            Image(systemName: "checkmark.circle.fill")
                .foregroundStyle(.secondary)
                .accessibilityLabel("Installed")
        } else {
            Image(systemName: "arrow.down.circle")
                .foregroundStyle(.tint)
                .accessibilityLabel("Not installed")
        }
    }
}

import ReachyKit
import SwiftUI

/// The robot's app store: what is installed, what the Hub offers, and what is
/// running right now.
struct AppStoreScreen: View {
    let session: RobotSession

    @State private var model: AppStoreModel
    @State private var selected: RobotApp?
    @Environment(\.reachyPreviewMode) private var previewMode

    init(session: RobotSession, model: AppStoreModel = AppStoreModel()) {
        self.session = session
        _model = State(initialValue: model)
    }

    var body: some View {
        @Bindable var model = model
        List {
            Section {
                Picker("Section", selection: $model.section) {
                    ForEach(AppStoreModel.Section.allCases) { section in
                        Text(section.title).tag(section)
                    }
                }
                .pickerStyle(.segmented)
                .listRowInsets(EdgeInsets(top: 4, leading: 0, bottom: 4, trailing: 0))
                .listRowBackground(Color.clear)
            }

            if model.isHeldRemotely {
                Section {
                    remoteSessionNotice
                }
            }

            if let lastError = model.lastError {
                Section {
                    Text(lastError)
                        .font(.caption)
                        .foregroundStyle(.red)
                }
            }

            Section {
                if model.loading, model.visibleApps.isEmpty {
                    ProgressView()
                        .frame(maxWidth: .infinity)
                } else {
                    ForEach(model.visibleApps) { app in
                        Button {
                            selected = app
                        } label: {
                            AppStoreRow(
                                app: app,
                                isInstalled: model.isInstalled(app),
                                isRunning: model.isRunning(app),
                                hasUpdate: model.hasUpdate(app),
                                isStartupApp: model.isStartupApp(app)
                            )
                        }
                        .buttonStyle(.plain)
                    }
                }
            }
        }
        .overlay {
            if model.visibleApps.isEmpty, !model.loading {
                emptyState
            }
        }
        .navigationTitle("Apps")
        .searchable(text: $model.searchText, prompt: "Search apps")
        .minimizedSearchToolbar()
        .safeAreaInset(edge: .bottom) {
            if let running = model.runningApp {
                RunningAppBanner(status: running, busy: model.busy) { action in
                    Task {
                        switch action {
                        case .stop: await model.stop(session: session)
                        case .restart: await model.restart(session: session)
                        }
                    }
                }
                .padding()
            }
        }
        .toolbar {
            Button {
                Task { await model.load(session: session, refresh: true) }
            } label: {
                Label("Refresh", systemImage: "arrow.clockwise")
            }
            .disabled(model.loading)
        }
        .sheet(item: $selected) { app in
            NavigationStack {
                AppDetailSheet(app: app, model: model, session: session) { selected = nil }
            }
            .presentationDetents([.medium, .large])
        }
        .task {
            guard !previewMode else { return }
            await model.load(session: session)
        }
    }

    @ViewBuilder
    private var emptyState: some View {
        if !model.searchText.isEmpty {
            ContentUnavailableView.search(text: model.searchText)
        } else if model.lastError != nil {
            ContentUnavailableView(
                "Store unavailable",
                systemImage: "wifi.exclamationmark",
                description: Text("The robot could not reach Hugging Face. Pull to refresh once it is back online.")
            )
        } else {
            switch model.section {
            case .installed:
                ContentUnavailableView(
                    "No apps installed",
                    systemImage: "square.stack.3d.up.slash",
                    description: Text("Browse Discover to install one from Hugging Face.")
                )
            case .discover:
                ContentUnavailableView(
                    "Nothing to show",
                    systemImage: "square.stack.3d.up.slash",
                    description: Text("The robot found no apps on Hugging Face.")
                )
            }
        }
    }

    /// A relay session holds the same lock a local app does, and the user cannot
    /// take it back from here — saying so beats a disabled button with no reason.
    private var remoteSessionNotice: some View {
        Label {
            VStack(alignment: .leading, spacing: 2) {
                Text("In use remotely")
                    .font(.subheadline.weight(.semibold))
                Text(
                    model.lockHolder.map { "\($0) is driving this robot over Hugging Face." }
                        ?? "Someone is driving this robot over Hugging Face."
                )
                .font(.caption)
                .foregroundStyle(.secondary)
            }
        } icon: {
            Image(systemName: "antenna.radiowaves.left.and.right")
                .foregroundStyle(.tint)
        }
    }
}

/// What is running, and the two things worth doing about it.
struct RunningAppBanner: View {
    enum Action {
        case stop
        case restart
    }

    let status: RobotAppStatus
    var busy = false
    let perform: (Action) -> Void

    var body: some View {
        HStack(spacing: 12) {
            AppArtworkTile(app: status.app, size: 34)
            VStack(alignment: .leading, spacing: 1) {
                Text(status.app.title)
                    .font(.subheadline.weight(.semibold))
                    .lineLimit(1)
                Text(stateDescription)
                    .font(.caption)
                    .foregroundStyle(.secondary)
            }
            Spacer(minLength: 4)
            Button {
                perform(.restart)
            } label: {
                Label("Restart", systemImage: "arrow.clockwise")
                    .labelStyle(.iconOnly)
            }
            .buttonStyle(.bordered)
            .buttonBorderShape(.circle)
            .disabled(busy)

            Button {
                perform(.stop)
            } label: {
                Label("Stop", systemImage: "stop.fill")
                    .labelStyle(.iconOnly)
            }
            .buttonStyle(.borderedProminent)
            .buttonBorderShape(.circle)
            .tint(.red)
            .disabled(busy)
        }
        .padding(12)
        .background(.regularMaterial, in: .rect(cornerRadius: 18, style: .continuous))
    }

    private var stateDescription: String {
        switch status.state {
        case .starting: "Starting…"
        case .running: "Running"
        case .stopping: "Stopping…"
        case .done: "Finished"
        case .error: status.error ?? "Stopped with an error"
        case let .unknown(state): state
        }
    }
}

private extension View {
    /// iOS 26 collapses a bottom search field into a button until it is used. The
    /// deployment floor is iOS 18, so this is opt-in per availability rather than
    /// a project-wide setting.
    @ViewBuilder
    func minimizedSearchToolbar() -> some View {
        #if os(iOS)
            if #available(iOS 26, *) {
                searchToolbarBehavior(.minimized)
            } else {
                self
            }
        #else
            self
        #endif
    }
}

import Foundation
import ReachyKit
@testable import ReachyUI
import Testing

private final class InstallRobotClient: RobotAPIClient, RobotAppsClient, @unchecked Sendable {
    private let lock = NSLock()
    private(set) var installed: [RobotApp] = []
    private(set) var privateInstalls: [String] = []
    private(set) var removed: [String] = []
    private(set) var updated: [String] = []
    var refusesToStart = false

    private var daemonState: Components.Schemas.DaemonStatus {
        let json = """
        {"robot_name":"testbot","state":"running","wireless_version":true,
         "desktop_app_daemon":false,"simulation_enabled":true,"mockup_sim_enabled":false,
         "backend_status":{"motor_control_mode":"enabled","error":null}}
        """
        // swiftlint:disable:next force_try
        return try! JSONDecoder().decode(Components.Schemas.DaemonStatus.self, from: Data(json.utf8))
    }

    func handshake() async throws -> RobotConnection.Handshake {
        .init(identity: .init(hardwareID: "hw", name: "testbot", daemonVersion: "1.9.0"), status: daemonState)
    }

    func daemonStatus() async throws -> Components.Schemas.DaemonStatus { daemonState }
    func wakeUp() async throws -> String { "wake" }
    func gotoSleep() async throws -> String { "sleep" }

    func installApp(_ app: RobotApp) async throws -> String {
        if refusesToStart {
            throw ReachyKitError.daemonRejected(statusCode: 400)
        }
        lock.withLock { installed.append(app) }
        return "job-install"
    }

    func installPrivateSpace(id spaceID: String) async throws -> String {
        lock.withLock { privateInstalls.append(spaceID) }
        return "job-private"
    }

    func removeApp(named name: String) async throws -> String {
        lock.withLock { removed.append(name) }
        return "job-remove"
    }

    func updateApp(named name: String) async throws -> String {
        lock.withLock { updated.append(name) }
        return "job-update"
    }

    func installedApps() async throws -> [RobotApp] { [] }
    func currentAppStatus() async throws -> RobotAppStatus? { nil }
    func startupApp() async throws -> String? { nil }
}

@MainActor
@Suite("App install model", .timeLimit(.minutes(1)))
struct AppInstallModelTests {
    private static func app(_ name: String, kind: String = "hf_space", extra: String = "{}") throws -> RobotApp {
        try JSONDecoder().decode(RobotApp.self, from: Data(#"""
        {"name": "\#(name)", "source_kind": "\#(kind)", "extra": \#(extra)}
        """#.utf8))
    }

    private func connected(_ client: InstallRobotClient) async -> RobotSession {
        let session = RobotSession { _ in client }
        #expect(await session.connect(to: .init(host: "127.0.0.1")))
        return session
    }

    private func events(_ events: [AppJobMonitor.Event]) -> AsyncStream<AppJobMonitor.Event> {
        AsyncStream { continuation in
            for event in events {
                continuation.yield(event)
            }
            continuation.finish()
        }
    }

    @Test("an install streams its log and ends in success")
    func installsAnApp() async throws {
        let client = InstallRobotClient()
        let session = await connected(client)
        let app = try Self.app("reachy-mini-dance", extra: #"{"id": "pollen-robotics/reachy-mini-dance"}"#)
        let model = AppInstallModel(session: session) { _, _ in
            self.events([.line("Collecting reachy-mini"), .status(.done), .finished(.succeeded)])
        }

        await model.perform(.install(app))

        #expect(model.state == .succeeded(.install(app)))
        #expect(client.installed.map(\.name) == ["reachy-mini-dance"])
        #expect(model.log.entries.contains { $0.message.contains("Collecting reachy-mini") })
    }

    /// A private Space cannot be installed by posting its `AppInfo` — the daemon
    /// has to fetch it with the token it stores, through its own route.
    @Test("a private Space goes through the route that uses the robot's token")
    func installsAPrivateSpace() async throws {
        let client = InstallRobotClient()
        let session = await connected(client)
        let app = try Self.app(
            "secret",
            extra: #"{"id": "someone/secret", "private": true}"#
        )
        let model = AppInstallModel(session: session) { _, _ in self.events([.finished(.succeeded)]) }

        await model.perform(.install(app))

        #expect(client.privateInstalls == ["someone/secret"])
        #expect(client.installed.isEmpty)
    }

    /// The job's failure never reaches the HTTP status — it arrives as a terminal
    /// state with the last log line as its reason.
    @Test("a failed job shows the reason the daemon logged")
    func reportsFailure() async throws {
        let session = await connected(InstallRobotClient())
        let app = try Self.app("reachy-mini-dance")
        let model = AppInstallModel(session: session) { _, _ in
            self.events([.finished(.failed("No matching distribution found"))])
        }

        await model.perform(.install(app))

        #expect(model.state == .failed(.install(app), "No matching distribution found"))
    }

    /// A restart mid-install is neither success nor failure: the job register died
    /// with the daemon, and the only honest thing is to say so and re-read the list.
    @Test("a daemon restart is its own outcome")
    func reportsDaemonRestart() async throws {
        let session = await connected(InstallRobotClient())
        let app = try Self.app("reachy-mini-dance")
        let model = AppInstallModel(session: session) { _, _ in self.events([.finished(.daemonRestarted)]) }

        await model.perform(.install(app))

        #expect(model.state == .daemonRestarted(.install(app)))
    }

    @Test("a job that never ends is reported as a timeout, not a failure of its own")
    func reportsTimeout() async throws {
        let session = await connected(InstallRobotClient())
        let app = try Self.app("reachy-mini-dance")
        let model = AppInstallModel(session: session) { _, _ in self.events([.finished(.timedOut)]) }

        await model.perform(.install(app))

        if case let .failed(_, reason) = model.state {
            #expect(reason.localizedCaseInsensitiveContains("too long"))
        } else {
            Issue.record("expected a failure, got \(model.state)")
        }
    }

    /// Upstream's budgets, which are what the robot was tested against: 60 s for an
    /// install, 90 s for a removal.
    @Test("each operation gets its own deadline")
    func usesPerOperationTimeouts() async throws {
        let session = await connected(InstallRobotClient())
        let app = try Self.app("dance_party", kind: "installed")
        let budgets = Budgets()
        let model = AppInstallModel(session: session) { _, configuration in
            budgets.record(configuration.timeout)
            return self.events([.finished(.succeeded)])
        }

        await model.perform(.install(app))
        await model.perform(.remove(app))

        #expect(budgets.recorded == [.seconds(60), .seconds(90)])
    }

    @Test("a daemon that refuses to start the job says so before any log appears")
    func reportsRefusedStart() async throws {
        let client = InstallRobotClient()
        client.refusesToStart = true
        let session = await connected(client)
        let app = try Self.app("local-thing")
        let model = AppInstallModel(session: session) { _, _ in self.events([]) }

        await model.perform(.install(app))

        if case .failed = model.state {} else {
            Issue.record("expected a failure, got \(model.state)")
        }
    }

    @Test("removing and updating are keyed by the installed name")
    func removesAndUpdatesByName() async throws {
        let client = InstallRobotClient()
        let session = await connected(client)
        let app = try Self.app("dance_party", kind: "installed")
        let model = AppInstallModel(session: session) { _, _ in self.events([.finished(.succeeded)]) }

        await model.perform(.remove(app))
        await model.perform(.update(app))

        #expect(client.removed == ["dance_party"])
        #expect(client.updated == ["dance_party"])
    }

    @Test("dismissing clears the outcome so the overlay can go away")
    func dismisses() async throws {
        let session = await connected(InstallRobotClient())
        let model = AppInstallModel(session: session) { _, _ in self.events([.finished(.succeeded)]) }

        await model.perform(.install(try Self.app("reachy-mini-dance")))
        model.dismiss()

        #expect(model.state == .idle)
        #expect(model.log.entries.isEmpty)
    }
}

private final class Budgets: @unchecked Sendable {
    private let lock = NSLock()
    private var values: [Duration] = []

    var recorded: [Duration] {
        lock.withLock { values }
    }

    func record(_ duration: Duration) {
        lock.withLock { values.append(duration) }
    }
}

import Foundation
import Observation
import ReachyKit

/// Drives one install, update or removal from the moment the daemon accepts the
/// job to the moment there is something honest to tell the user.
///
/// The daemon answers all three with a job id straight away and reports the work
/// out of band, so nothing here can be learned from an HTTP status: a job that
/// fails still returns 200, and a job whose daemon restarted stops existing
/// altogether. `AppJobMonitor` reconciles the socket and the poll; this turns its
/// four outcomes into four things a screen can say.
@MainActor
@Observable
final class AppInstallModel {
    enum Operation: Equatable {
        case install(RobotApp)
        case update(RobotApp)
        case remove(RobotApp)

        var app: RobotApp {
            switch self {
            case let .install(app), let .update(app), let .remove(app): app
            }
        }

        var title: String {
            switch self {
            case .install: "Installing"
            case .update: "Updating"
            case .remove: "Removing"
            }
        }

        /// Upstream's budgets, which are what the robot was tested against.
        var configuration: AppJobMonitor.Configuration {
            switch self {
            case .install: .install
            case .update: .update
            case .remove: .removal
            }
        }
    }

    enum State: Equatable {
        case idle
        case running(Operation)
        case succeeded(Operation)
        case failed(Operation, String)
        /// The daemon restarted mid-job and took its job register with it. The work
        /// may well have finished — the installed list is the only way to know.
        case daemonRestarted(Operation)
    }

    private(set) var state: State = .idle
    /// Shared with `LogConsoleView`, so `uv pip install` output gets the same
    /// filter, pause and export the daemon journal has.
    let log = LogConsoleModel()

    private let session: RobotSession
    /// The one step a stubbed client cannot drive: it opens a WebSocket and polls
    /// alongside it. Injected by tests and previews.
    private let makeEvents: (String, AppJobMonitor.Configuration) throws -> AsyncStream<AppJobMonitor.Event>

    init(
        session: RobotSession,
        events: ((String, AppJobMonitor.Configuration) throws -> AsyncStream<AppJobMonitor.Event>)? = nil
    ) {
        self.session = session
        makeEvents = events ?? { [session] jobID, configuration in
            try session.appJobEvents(jobID: jobID, configuration: configuration)
        }
    }

    var isBusy: Bool {
        if case .running = state { return true }
        return false
    }

    var operation: Operation? {
        switch state {
        case .idle: nil
        case let .running(operation), let .succeeded(operation),
             let .failed(operation, _), let .daemonRestarted(operation):
            operation
        }
    }

    func perform(_ operation: Operation) async {
        state = .running(operation)
        log.clear()

        let jobID: String
        do {
            jobID = try await start(operation)
        } catch {
            state = .failed(operation, Self.describe(error))
            return
        }

        do {
            for await event in try makeEvents(jobID, operation.configuration) {
                switch event {
                case let .line(line):
                    log.ingest(line)
                case .status:
                    // The terminal status arrives again as an outcome; showing it
                    // twice would just make the log noisier.
                    break
                case let .finished(outcome):
                    state = Self.state(for: outcome, operation: operation)
                }
            }
        } catch {
            state = .failed(operation, Self.describe(error))
        }
    }

    func dismiss() {
        state = .idle
        log.clear()
    }

    private func start(_ operation: Operation) async throws -> String {
        switch operation {
        case let .install(app):
            // A private Space cannot be installed by posting its `AppInfo`: the
            // files are only readable with the token the robot stores, so the
            // daemon has to fetch it through its own route.
            if app.isPrivate, let spaceID = app.spaceID {
                return try await session.installPrivateSpace(id: spaceID)
            }
            return try await session.installApp(app)
        case let .update(app):
            return try await session.updateApp(named: app.name)
        case let .remove(app):
            return try await session.removeApp(named: app.name)
        }
    }

    private static func state(for outcome: AppJobMonitor.Outcome, operation: Operation) -> State {
        switch outcome {
        case .succeeded:
            .succeeded(operation)
        case let .failed(reason):
            .failed(operation, reason ?? "The robot did not say why.")
        case .daemonRestarted:
            .daemonRestarted(operation)
        case .timedOut:
            .failed(operation, "The robot took too long to answer. Check the app list before trying again.")
        }
    }

    private static func describe(_ error: any Error) -> String {
        (error as? LocalizedError)?.errorDescription ?? error.localizedDescription
    }
}

#if DEBUG
    extension AppInstallModel {
        /// One job parked mid-flight. `events` is stubbed rather than left at its
        /// default, which opens a socket.
        static func preview(
            state: State,
            session: RobotSession? = nil,
            log lines: [String] = []
        ) -> AppInstallModel {
            let model = AppInstallModel(
                session: session ?? .preview(),
                events: { _, _ in AsyncStream { $0.finish() } }
            )
            model.state = state
            for line in lines {
                model.log.ingest(line)
            }
            return model
        }
    }
#endif

import ReachyKit
import SwiftUI

/// One app, and everything that can be done to it.
///
/// The job runs here rather than behind the sheet: an install takes a minute of
/// `uv pip install` output, and a user who dismissed the sheet would have nothing
/// to come back to.
struct AppDetailSheet: View {
    let app: RobotApp
    let model: AppStoreModel
    let session: RobotSession
    let install: AppInstallModel
    let dismiss: () -> Void

    @State private var confirmingRemoval = false
    @Environment(\.reachyPreviewMode) private var previewMode

    var body: some View {
        Form {
            Section {
                header
            }

            if let job = jobForThisApp {
                Section("Progress") {
                    JobProgressRow(state: job)
                    if install.isBusy || !install.log.entries.isEmpty {
                        LogConsoleView(model: install.log)
                            .frame(minHeight: 160)
                    }
                }
            } else {
                actions
            }

            if let summary = app.summary {
                Section("About") {
                    Text(summary)
                        .font(.subheadline)
                }
            }

            if let spaceID = app.spaceID, let url = URL(string: "https://huggingface.co/spaces/\(spaceID)") {
                Section {
                    Link(destination: url) {
                        Label("View on Hugging Face", systemImage: "arrow.up.right.square")
                    }
                }
            }
        }
        .formStyle(.grouped)
        .navigationTitle(app.title)
        #if os(iOS)
            .navigationBarTitleDisplayMode(.inline)
        #endif
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Done") {
                        install.dismiss()
                        dismiss()
                    }
                    .disabled(install.isBusy)
                }
            }
            .interactiveDismissDisabled(install.isBusy)
            .confirmationDialog(
                "Remove \(app.title)?",
                isPresented: $confirmingRemoval,
                titleVisibility: .visible
            ) {
                Button("Remove", role: .destructive) {
                    perform(.remove(installedApp ?? app))
                }
            } message: {
                Text("The app and its Python environment are deleted from the robot.")
            }
    }

    private var header: some View {
        HStack(spacing: 14) {
            AppArtworkTile(app: app, size: 64)
            VStack(alignment: .leading, spacing: 4) {
                Text(app.title)
                    .font(.title3.weight(.semibold))
                if let author = app.author {
                    Text(author)
                        .font(.subheadline)
                        .foregroundStyle(.secondary)
                }
                HStack(spacing: 10) {
                    if app.isOfficial {
                        Label("Official", systemImage: "checkmark.seal.fill")
                    }
                    if app.isPrivate {
                        Label("Private", systemImage: "lock.fill")
                    }
                    if let likes = app.likes, likes > 0 {
                        Label("\(likes)", systemImage: "heart.fill")
                    }
                }
                .font(.caption)
                .foregroundStyle(.secondary)
            }
            Spacer(minLength: 0)
        }
        .padding(.vertical, 4)
    }

    @ViewBuilder
    private var actions: some View {
        Section {
            if let installed = installedApp {
                if model.isRunning(app) {
                    Button("Stop", systemImage: "stop.fill", role: .destructive) {
                        Task { await model.stop(session: session) }
                    }
                } else {
                    Button("Start", systemImage: "play.fill") {
                        Task { await model.start(app, session: session) }
                    }
                    // Starting evicts whatever holds the robot; the daemon refuses
                    // with a 400 rather than taking it, and a remote session is not
                    // ours to take at all.
                    .disabled(model.busy || model.isHeldRemotely || model.runningApp != nil)
                }

                if model.hasUpdate(app) {
                    Button("Update", systemImage: "arrow.down.circle") {
                        perform(.update(installed))
                    }
                }

                Toggle("Start on wake-up", isOn: startupBinding)
                    .disabled(model.busy)

                Button("Remove", systemImage: "trash", role: .destructive) {
                    confirmingRemoval = true
                }
            } else {
                Button("Install", systemImage: "arrow.down.circle.fill") {
                    perform(.install(app))
                }
                .disabled(app.isPrivate && !canInstallPrivately)
            }
        } footer: {
            if app.isPrivate, !canInstallPrivately {
                Text("A private Space can only be installed once this robot is linked to your Hugging Face account.")
            } else if model.isHeldRemotely {
                Text("Someone is driving this robot over Hugging Face right now.")
            }
        }
    }

    private var installedApp: RobotApp? {
        model.installedTwin(of: app)
    }

    /// The daemon fetches a private Space with the token it stores, so this is
    /// about the *robot's* account, not about being signed in on this device.
    private var canInstallPrivately: Bool {
        session.canLinkHuggingFace
    }

    private var jobForThisApp: AppInstallModel.State? {
        guard let operation = install.operation else { return nil }
        let subject = operation.app
        guard subject.id == app.id || subject.name == installedApp?.name else { return nil }
        return install.state
    }

    private var startupBinding: Binding<Bool> {
        Binding(
            get: { model.isStartupApp(app) },
            set: { isOn in
                Task { await model.setStartupApp(isOn ? app : nil, session: session) }
            }
        )
    }

    private func perform(_ operation: AppInstallModel.Operation) {
        guard !previewMode else { return }
        Task {
            await install.perform(operation)
            await model.reloadInstalled(session: session)
        }
    }
