import Foundation
import HuggingFaceAuth
@testable import ReachyUI
import Testing

/// Stands in for `ASWebAuthenticationSession`, which cannot run in a test.
private final class FakeBrowser: HFWebAuthenticating, @unchecked Sendable {
    private let lock = NSLock()
    private(set) var opened: [URL] = []
    var result: Result<URL, any Error> = .success(URL(string: "reachy-mini-swift://oauth-callback?code=abc")!)

    func authenticate(url: URL, callbackScheme _: String) async throws -> URL {
        lock.withLock { opened.append(url) }
        return try result.get()
    }
}

private final class FakeExchanger: HFTokenExchanging, @unchecked Sendable {
    var username = "alexey1312"
    var rejectsTokens = false

    func exchange(code _: String, verifier _: String) async throws -> HFToken {
        HFToken(accessToken: "hf_new", expiresAt: Date().addingTimeInterval(3600))
    }

    func refreshing(_ token: HFToken) async throws -> HFToken { token }

    func username(for _: String) async throws -> String {
        if rejectsTokens {
            throw HFOAuthError.invalidToken
        }
        return username
    }
}

@MainActor
@Suite("Hugging Face sign-in", .timeLimit(.minutes(1)))
struct HFSignInModelTests {
    private let configuration = HFOAuthConfiguration(
        clientID: "client-1",
        redirectURI: "reachy-mini-swift://oauth-callback",
        scopes: HFOAuthConfiguration.reachyMiniScopes
    )

    private func model(
        browser: FakeBrowser = FakeBrowser(),
        exchanger: FakeExchanger = FakeExchanger(),
        configuration: HFOAuthConfiguration? = nil
    ) -> (HFSignInModel, HFAccount) {
        let account = HFAccount(
            configuration: configuration ?? self.configuration,
            store: InMemoryHFTokenStore(),
            exchanger: exchanger
        )
        return (HFSignInModel(account: account, browser: browser), account)
    }

    /// The whole point of `ASWebAuthenticationSession`: it shares Safari's cookies,
    /// so a user already signed in to the Hub taps once and is back.
    @Test("a browser round trip signs the user in")
    func signsInThroughTheBrowser() async {
        let browser = FakeBrowser()
        let (model, account) = model(browser: browser)

        await model.signInWithBrowser()

        #expect(browser.opened.first?.host == "huggingface.co")
        #expect(account.state == .signedIn(username: "alexey1312"))
        #expect(model.errorText == nil)
    }

    /// A callback carrying a state this app did not issue must not sign anyone in.
    /// `HFAccount` enforces that; this proves the UI does not paper over it.
    @Test("a foreign callback ends as an error, not a session")
    func refusesAForeignCallback() async {
        let browser = FakeBrowser()
        browser.result = .success(URL(string: "reachy-mini-swift://oauth-callback?code=abc&state=elsewhere")!)
        let (model, account) = model(browser: browser)

        await model.signInWithBrowser()

        #expect(model.errorText != nil)
        if case .signedIn = account.state {
            Issue.record("a foreign callback signed the user in")
        }
    }

    /// Closing the sheet is not a failure. Showing an error for it is how an app
    /// tells its user off for changing their mind.
    @Test("cancelling shows nothing at all")
    func cancellingIsSilent() async {
        let browser = FakeBrowser()
        browser.result = .failure(HFSignInModel.Cancelled())
        let (model, _) = model(browser: browser)

        await model.signInWithBrowser()

        #expect(model.errorText == nil)
        #expect(model.isBusy == false)
    }

    @Test("a browser that fails says why")
    func reportsBrowserFailure() async {
        let browser = FakeBrowser()
        browser.result = .failure(URLError(.networkConnectionLost))
        let (model, _) = model(browser: browser)

        await model.signInWithBrowser()

        #expect(model.errorText != nil)
    }

    /// Until the OAuth app is registered on the Hub there is no client id, and
    /// opening a browser would land the user on an error page.
    @Test("without a client id the browser is never opened")
    func refusesToOpenUnconfigured() async {
        let browser = FakeBrowser()
        let (model, _) = model(browser: browser, configuration: .reachyMini)

        #expect(model.offersBrowserSignIn == false)
        await model.signInWithBrowser()

        #expect(browser.opened.isEmpty)
    }

    @Test("a pasted token is accepted once the Hub confirms it")
    func signsInWithAPastedToken() async {
        let (model, account) = model()
        model.pastedToken = "  hf_pasted  "

        await model.signInWithPastedToken()

        #expect(account.state == .signedIn(username: "alexey1312"))
        // Cleared as soon as it is spent: a token left in a field is a token in a
        // screenshot.
        #expect(model.pastedToken.isEmpty)
    }

    @Test("a token the Hub rejects leaves the field alone to be corrected")
    func keepsARejectedToken() async {
        let exchanger = FakeExchanger()
        exchanger.rejectsTokens = true
        let (model, _) = model(exchanger: exchanger)
        model.pastedToken = "nope"

        await model.signInWithPastedToken()

        #expect(model.errorText != nil)
        #expect(model.pastedToken == "nope")
    }

    @Test("signing out forgets the session")
    func signsOut() async {
        let (model, account) = model()
        await model.signInWithBrowser()

        model.signOut()

        #expect(account.state == .signedOut)
    }
}

import Foundation
import HuggingFaceAuth
import Observation

/// Opens the sign-in page and hands the callback back.
///
/// A seam rather than a direct call: `ASWebAuthenticationSession` needs a real
/// window to present from, cannot run in a test, and must never open during a
/// snapshot.
@MainActor
protocol HFWebAuthenticating: Sendable {
    func authenticate(url: URL, callbackScheme: String) async throws -> URL
}

/// The sign-in half of the Hugging Face account card.
///
/// `HFAccount` owns the protocol and the token; this owns what the user sees
/// while it happens — which button is available, what is spinning, and what went
/// wrong in words.
@MainActor
@Observable
final class HFSignInModel {
    /// Thrown by the browser seam when the user closed the sheet. Not an error to
    /// report: showing one tells the user off for changing their mind.
    struct Cancelled: Error {}

    var pastedToken = ""
    private(set) var isBusy = false
    private(set) var errorText: String?

    let account: HFAccount
    private let browser: any HFWebAuthenticating

    init(account: HFAccount, browser: (any HFWebAuthenticating)? = nil) {
        self.account = account
        self.browser = browser ?? WebAuthenticationBrowser()
    }

    /// False until the OAuth app is registered on the Hub. The pasted-token path
    /// stays open either way, which is why this is a question worth asking rather
    /// than a button that fails.
    var offersBrowserSignIn: Bool {
        account.canSignInWithBrowser
    }

    func signInWithBrowser() async {
        guard offersBrowserSignIn else { return }
        errorText = nil
        isBusy = true
        defer { isBusy = false }

        do {
            let url = try account.beginSignIn()
            let callback = try await browser.authenticate(
                url: url,
                callbackScheme: HFOAuthConfiguration.callbackScheme
            )
            await account.completeSignIn(callback: callback)
            if case let .failed(reason) = account.state {
                errorText = reason
            }
        } catch is Cancelled {
            account.signOut()
        } catch {
            account.signOut()
            errorText = Self.describe(error)
        }
    }

    func signInWithPastedToken() async {
        let token = pastedToken.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !token.isEmpty else { return }
        errorText = nil
        isBusy = true
        defer { isBusy = false }

        await account.signIn(pastedToken: token)
        if case let .failed(reason) = account.state {
            // Left in the field on purpose: a token that was mistyped is worth
            // correcting rather than retyping from scratch.
            errorText = reason
        } else {
            pastedToken = ""
        }
    }

    func signOut() {
        account.signOut()
        errorText = nil
        pastedToken = ""
    }

    private static func describe(_ error: any Error) -> String {
        (error as? LocalizedError)?.errorDescription ?? error.localizedDescription
    }
}

#if DEBUG
    extension HFSignInModel {
        /// A card parked in one state, with a browser that opens nothing.
        static func preview(
            state: HFAccount.State = .signedOut,
            configuration: HFOAuthConfiguration = .init(
                clientID: "preview-client",
                redirectURI: "reachy-mini-swift://oauth-callback",
                scopes: HFOAuthConfiguration.reachyMiniScopes
            ),
            error: String? = nil
        ) -> HFSignInModel {
            let token: HFToken? = switch state {
            case let .signedIn(username): HFToken(accessToken: "hf_preview", username: username)
            case let .needsReauth(username):
                HFToken(accessToken: "hf_preview", expiresAt: .distantPast, username: username)
            default: nil
            }
            let account = HFAccount(
                configuration: configuration,
                store: InMemoryHFTokenStore(token: token),
                exchanger: InertExchanger()
            )
            account.restore()
            let model = HFSignInModel(account: account, browser: InertBrowser())
            model.errorText = error
            return model
        }
    }

    private struct InertBrowser: HFWebAuthenticating {
        func authenticate(url _: URL, callbackScheme _: String) async throws -> URL {
            throw HFSignInModel.Cancelled()
        }
    }

    private struct InertExchanger: HFTokenExchanging {
        func exchange(code _: String, verifier _: String) async throws -> HFToken {
            throw HFOAuthError.notConfigured
        }

        func refreshing(_ token: HFToken) async throws -> HFToken { token }

        func username(for _: String) async throws -> String {
            throw HFOAuthError.notConfigured
        }
    }
#endif

import AuthenticationServices
import Foundation
import HuggingFaceAuth

/// The real browser behind `HFWebAuthenticating`.
///
/// `ASWebAuthenticationSession` rather than a `WKWebView` or Safari: it runs the
/// sign-in page **in Safari's own context**, so a user already signed in to the
/// Hub is one tap from done — and this app never sees the page, the password, or
/// the cookies. It is also the only presentation Apple accepts for third-party
/// sign-in.
@MainActor
final class WebAuthenticationBrowser: NSObject, HFWebAuthenticating {
    func authenticate(url: URL, callbackScheme: String) async throws -> URL {
        try await withCheckedThrowingContinuation { continuation in
            let session = ASWebAuthenticationSession(
                url: url,
                callbackURLScheme: callbackScheme
            ) { callback, error in
                if let error {
                    // The user closing the sheet is the one "failure" that is not
                    // one; everything else is worth showing.
                    let isCancellation = (error as? ASWebAuthenticationSessionError)?.code == .canceledLogin
                    continuation.resume(throwing: isCancellation ? HFSignInModel.Cancelled() : error)
                    return
                }
                guard let callback else {
                    continuation.resume(throwing: HFOAuthError.missingCode)
                    return
                }
                continuation.resume(returning: callback)
            }
            session.presentationContextProvider = self
            // Deliberately *not* ephemeral: sharing Safari's cookies is the whole
            // reason this is one tap rather than a password prompt.
            session.prefersEphemeralWebBrowserSession = false
            session.start()
        }
    }
}

extension WebAuthenticationBrowser: ASWebAuthenticationPresentationContextProviding {
    nonisolated func presentationAnchor(for _: ASWebAuthenticationSession) -> ASPresentationAnchor {
        MainActor.assumeIsolated {
            #if os(macOS)
                NSApplication.shared.keyWindow ?? ASPresentationAnchor()
            #else
                let scene = UIApplication.shared.connectedScenes
                    .compactMap { $0 as? UIWindowScene }
                    .first { $0.activationState == .foregroundActive }
                return scene?.keyWindow ?? ASPresentationAnchor()
            #endif
        }
    }
}

