            client?.urlProtocol(self, didLoad: chunk)
        }
        guard !stub.staysOpen else { return }
        client?.urlProtocolDidFinishLoading(self)
    }
}

override public func stopLoading() {
    streaming?.cancel()
    streaming = nil
}

