import Foundation
@testable import ReachyKit
import ReachyTestSupport
import Testing

/// The Hugging Face relay: an SSE stream down, HTTP POSTs up. Every shape here is
/// the one the robot's own `central_signaling_relay.py` speaks to the same server.
@Suite("Central relay client", .timeLimit(.minutes(1)))
struct CentralRelayClientTests {
    private static let base = URL(string: "https://central.example")!

    private func client(
        _ stubs: [String: StubURLProtocol.Stub],
        token: String? = "hf_token",
        session: URLSession? = nil
    ) -> (CentralRelayClient, URLSession) {
        let session = session ?? StubURLProtocol.makeSession(stubs)
        let client = CentralRelayClient(
            configuration: .init(baseURL: Self.base, clientName: "ReachyMini Swift"),
            session: session,
            token: { token }
        )
        return (client, session)
    }

    private func collect(
        _ client: CentralRelayClient,
        until isDone: @escaping ([CentralRelayClient.Event]) -> Bool
    ) async -> [CentralRelayClient.Event] {
        var received: [CentralRelayClient.Event] = []
        for await event in await client.events() {
            received.append(event)
            if isDone(received) {
                break
            }
        }
        return received
    }

    /// The stream carries SSE framing, not bare JSON: only `data:` lines are
    /// payload, and the rest — comments, `event:`, `id:` — are noise a decoder
    /// must never see.
    @Test("only data lines are decoded")
    func readsOnlyDataLines() async {
        let (client, _) = client([
            "/events": .init(statusCode: 200, lines: [
                ": keepalive",
                "event: message",
                #"data: {"type":"welcome","peerId":"peer-1"}"#,
                "",
                #"data: {"type":"list","producers":[{"peerId":"robot-1","meta":{"name":"testbot"}}]}"#,
            ]),
            "/send": .init(statusCode: 200),
        ])

        let events = await collect(client) { events in
            events.contains { if case .message(.producerList) = $0 { true } else { false } }
        }

        #expect(events.first == .connected(peerID: "peer-1"))
        #expect(events.contains { $0 == .message(.producerList([.init(id: "robot-1", name: "testbot")])) })
    }

    /// Central sweeps peers with no recent inbound traffic, so a listener has to
    /// announce itself — and the name it announces is what the robot's owner sees
    /// as the thing holding their robot.
    @Test("the listener announces itself as soon as it is welcomed")
    func registersOnWelcome() async {
        let (client, session) = client([
            "/events": .init(statusCode: 200, lines: [#"data: {"type":"welcome","peerId":"peer-1"}"#]),
            "/send": .init(statusCode: 200),
        ])

        _ = await collect(client) { $0.contains { if case .connected = $0 { true } else { false } } }
        // The POST is fired from the stream's task; give it a moment to land.
        try? await Task.sleep(for: .milliseconds(200))

        let posted = StubURLProtocol.bodies(for: session)
            .compactMap { try? JSONDecoder().decode(SignalingMessage.self, from: $0) }
        #expect(posted.contains { $0 == .setPeerStatus(roles: ["listener"], name: "ReachyMini Swift") })
    }

    /// A token that central refuses is not something to retry: every attempt with
    /// the same token gets the same answer, and the user has to sign in again.
    @Test("a rejected token ends the stream instead of retrying")
    func stopsOnUnauthorized() async {
        let (client, _) = client(["/events": .init(statusCode: 401)])

        let events = await collect(client) { _ in true }

        #expect(events == [.failed(.unauthorized)])
    }

    @Test("with no token the stream never opens")
    func requiresAToken() async {
        let (client, session) = client(["/events": .init(statusCode: 200)], token: nil)

        let events = await collect(client) { _ in true }

        #expect(events == [.failed(.noToken)])
        #expect(StubURLProtocol.requests(for: session).isEmpty)
    }

    /// WebRTC's end-of-candidates marker. `RTCIceCandidate` throws on an empty
    /// candidate string, so it is dropped here rather than at the media layer.
    @Test("the end-of-candidates marker never reaches the caller")
    func dropsEmptyCandidates() async {
        let (client, _) = client([
            "/events": .init(statusCode: 200, lines: [
                #"data: {"type":"welcome","peerId":"peer-1"}"#,
                #"data: {"type":"peer","sessionId":"s1","ice":{"candidate":"","sdpMLineIndex":0}}"#,
                #"data: {"type":"peer","sessionId":"s1","ice":{"candidate":"candidate:1","sdpMLineIndex":0}}"#,
            ]),
            "/send": .init(statusCode: 200),
        ])

        let events = await collect(client) { events in
            events.contains { if case .message(.ice) = $0 { true } else { false } }
        }

        let candidates = events.compactMap { event -> String? in
            if case let .message(.ice(_, candidate, _, _)) = event { candidate } else { nil }
        }
        #expect(candidates == ["candidate:1"])
    }

    /// A line that is not JSON at all — central sends `data: ping` as its
    /// keepalive — must not end the stream.
    @Test("a keepalive that is not JSON is ignored")
    func ignoresNonJSONData() async {
        let (client, _) = client([
            "/events": .init(statusCode: 200, lines: [
                "data: ping",
                #"data: {"type":"welcome","peerId":"peer-1"}"#,
            ]),
            "/send": .init(statusCode: 200),
        ])

        let events = await collect(client) { $0.contains { if case .connected = $0 { true } else { false } } }

        #expect(events == [.connected(peerID: "peer-1")])
    }

    // MARK: Sending

    /// Central answers the POST that asked. `startSession` is the case that
    /// matters: the session id — or the refusal — comes back in the reply body
    /// rather than over the stream.
    @Test("the reply to a send is itself a signaling message")
    func readsTheReplyToASend() async throws {
        let (client, session) = client([
            "/send": .init(
                statusCode: 200,
                json: #"{"type":"sessionStarted","peerId":"robot-1","sessionId":"s1"}"#
            ),
        ])

        let reply = try await client.send(.startSession(peerID: "robot-1"))

        #expect(reply == .sessionStarted(peerID: "robot-1", sessionID: "s1"))
        let request = try #require(StubURLProtocol.requests(for: session).first)
        #expect(request.httpMethod == "POST")
        // The token travels in a header, never the URL: central is a Hugging Face
        // Space, and a URL reaches its access log and every proxy on the way.
        #expect(request.value(forHTTPHeaderField: "Authorization") == "Bearer hf_token")
        #expect(request.url?.absoluteString.contains("hf_token") == false)
    }

    @Test("a refusal comes back the same way and is not an error")
    func readsARejection() async throws {
        let (client, _) = client([
            "/send": .init(
                statusCode: 200,
                json: #"{"type":"sessionRejected","reason":"robot_busy","activeApp":"Hand Tracker"}"#
            ),
        ])

        let reply = try await client.send(.startSession(peerID: "robot-1"))

        #expect(reply == .sessionRejected(reason: "robot_busy", activeApp: "Hand Tracker"))
    }

    @Test("an acknowledgement with no message in it is not an error either")
    func acceptsAnEmptyReply() async throws {
        let (client, _) = client(["/send": .init(statusCode: 200, json: #"{"status":"ok"}"#)])

        #expect(try await client.send(.list) == nil)
    }

    /// 1200 requests a minute per token, and central answers 429 past it. Retrying
    /// immediately is how a client turns a rate limit into a ban.
    @Test("a rate limit is reported as itself")
    func reportsRateLimit() async {
        let (client, _) = client(["/send": .init(statusCode: 429)])

        await #expect(throws: CentralRelayClient.Failure.rateLimited) {
            try await client.send(.list)
        }
    }

    // MARK: The robot list

    @Test("the robot list decodes with the keys that identify a robot")
    func listsRobots() async throws {
        let (client, _) = client([
            "/api/robot-status": .init(statusCode: 200, json: #"""
            {"robots": [
              {"peerId": "peer-7", "robotName": "testbot", "busy": false,
               "meta": {"name": "testbot", "transport": "wifi", "hardware_id": "a1b2c3d4e5f60718"},
               "last_seen_age_seconds": 2.5}
            ]}
            """#),
        ])

        let robots = try await client.robots()

        #expect(robots.map(\.id) == ["a1b2c3d4e5f60718"])
        #expect(robots.first?.transport == .wifi)
    }

    /// Presence in the list *is* the online signal — central sweeps a robot whose
    /// lease lapsed — so an empty list is an answer, not a failure.
    @Test("an empty list is an answer")
    func acceptsAnEmptyRobotList() async throws {
        let (client, _) = client(["/api/robot-status": .init(statusCode: 200, json: #"{"robots": []}"#)])

        #expect(try await client.robots().isEmpty)
    }

    @Test("a token central will not accept is reported as such")
    func reportsUnauthorizedList() async {
        let (client, _) = client(["/api/robot-status": .init(statusCode: 401)])

        await #expect(throws: CentralRelayClient.Failure.unauthorized) {
            try await client.robots()
        }
    }
}

import Foundation

/// The client half of the Hugging Face relay — how this app reaches a robot that
/// is not on the same network.
///
/// The same signaling protocol the robot serves on port 8443, over a different
/// transport: a server-sent-event stream down, HTTP POSTs up. Central is a
/// Hugging Face Space, and it authenticates every call with the user's own token,
/// which is what makes a robot visible to its owner and to nobody else.
///
/// Every constant here is the robot's, from `central_signaling_relay.py`, so both
/// ends give up and retry on the same schedule.
public actor CentralRelayClient {
    public struct Configuration: Sendable {
        /// Overridable for a fork or a staging Space — the daemon reads the same
        /// value from `REACHY_CENTRAL_URL`.
        public var baseURL: URL
        /// What the robot's owner sees holding their robot while this session is
        /// up, so it names the app rather than the device.
        public var clientName: String
        /// The robot allows 60 s of silence before calling the stream dead;
        /// central sends a keepalive well inside that.
        public var readTimeout: Duration
        public var reconnectInterval: Duration
        public var maxReconnectInterval: Duration

        public init(
            baseURL: URL = CentralRelayClient.defaultBaseURL,
            clientName: String = "Reachy Mini",
            readTimeout: Duration = .seconds(60),
            reconnectInterval: Duration = .seconds(5),
            maxReconnectInterval: Duration = .seconds(60)
        ) {
            self.baseURL = baseURL
            self.clientName = clientName
            self.readTimeout = readTimeout
            self.reconnectInterval = reconnectInterval
            self.maxReconnectInterval = maxReconnectInterval
        }
    }

    public enum Failure: Error, Equatable, Sendable {
        /// This app holds no token. Nothing to retry — the user signs in first.
        case noToken
        /// Central refused the token. Also nothing to retry: the same token will
        /// be refused again.
        case unauthorized
        /// 1200 requests a minute per token. Retrying at once turns a limit into
        /// a ban.
        case rateLimited
        case http(Int)
    }

    public enum Event: Equatable, Sendable {
        case connected(peerID: String)
        case message(SignalingMessage)
        case failed(Failure)
        /// The stream ended and will be retried, unless the failure was terminal.
        case disconnected
    }

    public static let defaultBaseURL = URL(string: "https://pollen-robotics-reachy-mini-central.hf.space")!

    private let configuration: Configuration
    private let session: URLSession
    private let token: @Sendable () async -> String?

    /// The token is fetched per request rather than held: it can be renewed or
    /// revoked while a stream is open, and a copy kept here would outlive both.
    public init(
        configuration: Configuration = Configuration(),
        session: URLSession = .shared,
        token: @escaping @Sendable () async -> String?
    ) {
        self.configuration = configuration
        self.session = session
        self.token = token
    }

    /// One pass over `GET /events`. Ends with `.failed` for anything terminal and
    /// `.disconnected` when the stream simply stopped.
    public func events() -> AsyncStream<Event> {
        let (stream, continuation) = AsyncStream.makeStream(of: Event.self, bufferingPolicy: .bufferingNewest(256))
        let task = Task { await run(continuation) }
        continuation.onTermination = { _ in task.cancel() }
        return stream
    }

    /// Sends one signaling message. Central answers in the body of this very POST
    /// — `sessionStarted` or `sessionRejected` for a `startSession` — so the reply
    /// is returned rather than waited for on the stream.
    @discardableResult
    public func send(_ message: SignalingMessage) async throws -> SignalingMessage? {
        var request = try await authorized(path: "/send")
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        request.httpBody = try JSONEncoder().encode(message)

        let (data, response) = try await session.data(for: request)
        try Self.check(response)
        // An acknowledgement (`{"status":"ok"}`) is not a signaling message, and
        // not an error either.
        return try? JSONDecoder().decode(SignalingMessage.self, from: data)
    }

    /// The robots central can see for this token. Presence in the list *is* the
    /// online signal: central sweeps a peer whose lease lapsed.
    public func robots() async throws -> [CentralRobot] {
        struct Response: Decodable {
            let robots: [CentralRobot]
        }
        let (data, response) = try await session.data(for: try await authorized(path: "/api/robot-status"))
        try Self.check(response)
        return try JSONDecoder().decode(Response.self, from: data).robots
    }

    /// The one route central serves without a token.
    public func isReachable() async -> Bool {
        guard let url = URL(string: "/health", relativeTo: configuration.baseURL) else { return false }
        guard let (_, response) = try? await session.data(from: url) else { return false }
        return (response as? HTTPURLResponse)?.statusCode == 200
    }

    // MARK: - The stream

    private func run(_ continuation: AsyncStream<Event>.Continuation) async {
        defer { continuation.finish() }

        var request: URLRequest
        do {
            request = try await authorized(path: "/events")
        } catch let failure as Failure {
            continuation.yield(.failed(failure))
            return
        } catch {
            continuation.yield(.failed(.http(-1)))
            return
        }
        request.setValue("text/event-stream", forHTTPHeaderField: "Accept")
        request.timeoutInterval = Double(configuration.readTimeout.components.seconds)

        do {
            let (bytes, response) = try await session.bytes(for: request)
            try Self.check(response)
            for try await line in bytes.lines {
                guard !Task.isCancelled else { return }
                guard let message = Self.message(in: line) else { continue }
                if case let .welcome(peerID) = message {
                    continuation.yield(.connected(peerID: peerID))
                    // Central evicts peers with no recent inbound traffic, and the
                    // name announced here is what the robot's owner sees holding
                    // their robot.
                    try? await send(.setPeerStatus(roles: ["listener"], name: configuration.clientName))
                    continue
                }
                continuation.yield(.message(message))
            }
            continuation.yield(.disconnected)
        } catch let failure as Failure {
            continuation.yield(.failed(failure))
        } catch {
            continuation.yield(.disconnected)
        }
    }

    /// One SSE line. Anything but `data:` is framing, and a `data:` line that is
    /// not JSON is central's keepalive.
    static func message(in line: String) -> SignalingMessage? {
        guard line.hasPrefix("data:") else { return nil }
        let payload = line.dropFirst("data:".count).trimmingCharacters(in: .whitespaces)
        guard !payload.isEmpty,
              let message = try? JSONDecoder().decode(SignalingMessage.self, from: Data(payload.utf8))
        else { return nil }
        // An empty candidate is WebRTC's end-of-candidates marker, and
        // `RTCIceCandidate` throws on it — dropping it here keeps that out of the
        // media layer entirely.
        if case let .ice(_, candidate, _, _) = message, candidate.isEmpty {
            return nil
        }
        return message
    }

    private func authorized(path: String) async throws -> URLRequest {
        guard let token = await token() else { throw Failure.noToken }
        guard let url = URL(string: path, relativeTo: configuration.baseURL) else {
            throw Failure.http(-1)
        }
        var request = URLRequest(url: url)
        request.setValue("Bearer \(token)", forHTTPHeaderField: "Authorization")
        return request
    }

    private static func check(_ response: URLResponse) throws {
        guard let http = response as? HTTPURLResponse else { throw Failure.http(-1) }
        switch http.statusCode {
        case 200 ..< 300: return
        case 401, 403: throw Failure.unauthorized
        case 429: throw Failure.rateLimited
        case let code: throw Failure.http(code)
        }
    }
}

