import Foundation

/// What a WebRTC session needs from whoever is carrying its signaling.
///
/// Two carriers exist and the RTC half does not care which: on the LAN it is the
/// robot's own WebSocket on port 8443, and from outside it is the Hugging Face
/// relay's event stream. Both speak the same `webrtcsink` protocol, both make the
/// robot the offerer, and both end up handing this app an SDP offer to answer.
public protocol RobotSignaling: Sendable {
    func events() async -> AsyncStream<SignalingEvent>
    func send(answerSDP: String) async
    func send(candidate: String, sdpMLineIndex: Int32, sdpMid: String?) async
    func disconnect() async
}

/// The signaling half of a session, in the terms the media layer acts on.
public enum SignalingEvent: Sendable, Equatable {
    /// Signaling is up but nothing is producing yet — the simulator before media
    /// is acquired, or a robot whose relay has not registered.
    case waitingForProducer
    case offer(sessionID: String, sdp: String)
    case remoteCandidate(sessionID: String, candidate: String, sdpMLineIndex: Int32, sdpMid: String?)
    /// The session ended. `reason` exists only over the relay, where central says
    /// why — a local app took the robot, or another device did.
    case sessionEnded(reason: String?)
    /// Terminal: nothing will be retried. The LAN client reconnects on its own and
    /// never reports this; the relay does, for a token that was refused.
    case failed(String)
}

extension CameraSignalingClient: RobotSignaling {
    public func events() async -> AsyncStream<SignalingEvent> {
        let source: AsyncStream<Event> = events()
        return AsyncStream { continuation in
            let task = Task {
                for await event in source {
                    continuation.yield(SignalingEvent(event))
                }
                continuation.finish()
            }
            continuation.onTermination = { _ in task.cancel() }
        }
    }
}

private extension SignalingEvent {
    init(_ event: CameraSignalingClient.Event) {
        self = switch event {
        case .waitingForProducer: .waitingForProducer
        case let .offer(sessionID, sdp): .offer(sessionID: sessionID, sdp: sdp)
        case let .remoteCandidate(sessionID, candidate, index, mid):
            .remoteCandidate(sessionID: sessionID, candidate: candidate, sdpMLineIndex: index, sdpMid: mid)
        // The LAN client re-negotiates by itself, so it never says why.
        case .sessionEnded: .sessionEnded(reason: nil)
        }
    }
}

import Foundation
@testable import ReachyKit
import ReachyTestSupport
import Testing

/// The relay dressed as signaling: pick the robot out of central's producer list,
/// ask for a session, and hand the media layer the same offer it would have got
/// from the robot's own socket.
@Suite("Central signaling transport", .timeLimit(.minutes(1)))
struct CentralSignalingTransportTests {
    private func transport(
        _ stubs: [String: StubURLProtocol.Stub],
        robot: String = "robot-1"
    ) -> (CentralSignalingTransport, URLSession) {
        let session = StubURLProtocol.makeSession(stubs)
        let client = CentralRelayClient(
            configuration: .init(baseURL: URL(string: "https://central.example")!, clientName: "Test"),
            session: session,
            token: { "hf_token" }
        )
        return (CentralSignalingTransport(relay: client, robotPeerID: robot), session)
    }

    private func collect(
        _ transport: CentralSignalingTransport,
        until isDone: @escaping ([SignalingEvent]) -> Bool
    ) async -> [SignalingEvent] {
        var received: [SignalingEvent] = []
        for await event in await transport.events() {
            received.append(event)
            if isDone(received) {
                break
            }
        }
        return received
    }

    /// The robot is the offerer here too, so the session has to be asked for
    /// before anything arrives — and central answers that ask in the POST body.
    @Test("asks for a session as soon as the robot is listed, then relays the offer")
    func startsASessionAndRelaysTheOffer() async {
        let (transport, session) = transport([
            "/events": .init(statusCode: 200, lines: [
                #"data: {"type":"welcome","peerId":"me"}"#,
                #"data: {"type":"list","producers":[{"peerId":"robot-1","meta":{"name":"testbot"}}]}"#,
                #"data: {"type":"peer","sessionId":"s1","sdp":{"type":"offer","sdp":"v=0 offer"}}"#,
            ]),
            "/send": .init(statusCode: 200, json: #"{"type":"sessionStarted","peerId":"robot-1","sessionId":"s1"}"#),
        ])

        let events = await collect(transport) { events in
            events.contains { if case .offer = $0 { true } else { false } }
        }

        #expect(events.contains(.offer(sessionID: "s1", sdp: "v=0 offer")))
        let asked = StubURLProtocol.bodies(for: session)
            .compactMap { try? JSONDecoder().decode(SignalingMessage.self, from: $0) }
        #expect(asked.contains(.startSession(peerID: "robot-1")))
    }

    /// A robot that is not in the list is not online. Saying so beats waiting for
    /// an offer that is never coming.
    @Test("a robot missing from the list reads as nothing producing yet")
    func reportsMissingRobot() async {
        let (transport, _) = transport([
            "/events": .init(statusCode: 200, lines: [
                #"data: {"type":"welcome","peerId":"me"}"#,
                #"data: {"type":"list","producers":[{"peerId":"someone-else"}]}"#,
            ]),
            "/send": .init(statusCode: 200),
        ])

        let events = await collect(transport) { $0.contains(.waitingForProducer) }

        #expect(events.contains(.waitingForProducer))
    }

    /// Being turned away is the common case — the robot is in use — and it is the
    /// end of this attempt, with central's own reason carried through.
    @Test("a refusal ends the attempt and names the app holding the robot")
    func reportsRefusal() async {
        let (transport, _) = transport([
            "/events": .init(statusCode: 200, lines: [
                #"data: {"type":"welcome","peerId":"me"}"#,
                #"data: {"type":"list","producers":[{"peerId":"robot-1","busy":true,"activeApp":"Hand Tracker"}]}"#,
            ]),
            "/send": .init(
                statusCode: 200,
                json: #"{"type":"sessionRejected","reason":"robot_busy","activeApp":"Hand Tracker"}"#
            ),
        ])

        let events = await collect(transport) { events in
            events.contains { if case .failed = $0 { true } else { false } }
        }

        #expect(events.contains { event in
            if case let .failed(reason) = event {
                reason.contains("Hand Tracker")
            } else {
                false
            }
        })
    }

    /// Eviction. Central says which kind, and the difference matters: a local app
    /// started on the robot is not the same as another device taking over.
    @Test("an eviction carries the reason central gave")
    func relaysEndSessionReason() async {
        let (transport, _) = transport([
            "/events": .init(statusCode: 200, lines: [
                #"data: {"type":"welcome","peerId":"me"}"#,
                #"data: {"type":"list","producers":[{"peerId":"robot-1"}]}"#,
                #"data: {"type":"endSession","sessionId":"s1","reason":"local_app_started"}"#,
            ]),
            "/send": .init(statusCode: 200, json: #"{"type":"sessionStarted","peerId":"robot-1","sessionId":"s1"}"#),
        ])

        let events = await collect(transport) { events in
            events.contains { if case .sessionEnded = $0 { true } else { false } }
        }

        #expect(events.contains(.sessionEnded(reason: "local_app_started")))
    }

    @Test("a token central refuses is terminal")
    func reportsUnauthorized() async {
        let (transport, _) = transport(["/events": .init(statusCode: 401)])

        let events = await collect(transport) { _ in true }

        #expect(events.count == 1)
        #expect(events.first.map { if case .failed = $0 { true } else { false } } == true)
    }

    /// The answer and every local candidate go back up the same POST route, tagged
    /// with the session central handed out.
    @Test("the answer and the candidates carry the session central gave")
    func sendsAnswerAndCandidates() async throws {
        let (transport, session) = transport([
            "/events": .init(statusCode: 200, lines: [
                #"data: {"type":"welcome","peerId":"me"}"#,
                #"data: {"type":"list","producers":[{"peerId":"robot-1"}]}"#,
                #"data: {"type":"peer","sessionId":"s1","sdp":{"type":"offer","sdp":"v=0 offer"}}"#,
            ]),
            "/send": .init(statusCode: 200, json: #"{"type":"sessionStarted","peerId":"robot-1","sessionId":"s1"}"#),
        ])
        _ = await collect(transport) { events in
            events.contains { if case .offer = $0 { true } else { false } }
        }

        await transport.send(answerSDP: "v=0 answer")
        await transport.send(candidate: "candidate:1", sdpMLineIndex: 0, sdpMid: "0")

        let sent = StubURLProtocol.bodies(for: session)
            .compactMap { try? JSONDecoder().decode(SignalingMessage.self, from: $0) }
        #expect(sent.contains(.sdp(sessionID: "s1", type: "answer", sdp: "v=0 answer")))
        #expect(sent.contains(.ice(sessionID: "s1", candidate: "candidate:1", sdpMLineIndex: 0, sdpMid: "0")))
    }
}

import Foundation

/// The Hugging Face relay, dressed as signaling for the media layer.
///
/// Everything specific to reaching a robot from outside its network lives here:
/// finding it in central's producer list, asking for a session, and turning
/// central's refusals into something a screen can say. What comes out the other
/// side is the same `SignalingEvent` stream the robot's own socket produces, so
/// the WebRTC half never learns which network it is on.
public actor CentralSignalingTransport: RobotSignaling {
    private let relay: CentralRelayClient
    /// Which robot to ask for. `peerId` changes on every relay reconnect, so this
    /// is resolved from a stable id (`hardware_id`) before a transport is built,
    /// not stored across reconnects.
    private let robotPeerID: String

    private var sessionID: String?
    /// Central hands out one session per ask. Producer lists arrive repeatedly —
    /// on connect and on every peer change — and asking again for a session we
    /// already hold would evict ourselves.
    private var isNegotiating = false

    public init(relay: CentralRelayClient, robotPeerID: String) {
        self.relay = relay
        self.robotPeerID = robotPeerID
    }

    public func events() -> AsyncStream<SignalingEvent> {
        let (stream, continuation) = AsyncStream.makeStream(
            of: SignalingEvent.self,
            bufferingPolicy: .bufferingNewest(64)
        )
        let task = Task { await run(continuation) }
        continuation.onTermination = { _ in task.cancel() }
        return stream
    }

    public func send(answerSDP: String) async {
        guard let sessionID else { return }
        try? await relay.answer(sessionID: sessionID, sdp: answerSDP)
    }

    public func send(candidate: String, sdpMLineIndex: Int32, sdpMid: String?) async {
        guard let sessionID else { return }
        try? await relay.send(
            candidate: candidate,
            sdpMLineIndex: sdpMLineIndex,
            sdpMid: sdpMid,
            sessionID: sessionID
        )
    }

    public func disconnect() async {
        guard let sessionID else { return }
        self.sessionID = nil
        isNegotiating = false
        try? await relay.endSession(sessionID)
    }

    private func run(_ continuation: AsyncStream<SignalingEvent>.Continuation) async {
        defer { continuation.finish() }

        for await event in await relay.events() {
            guard !Task.isCancelled else { return }
            switch event {
            case .connected:
                continue
            case let .producers(producers):
                await negotiate(among: producers, continuation)
            case let .offer(sessionID, sdp):
                self.sessionID = sessionID
                continuation.yield(.offer(sessionID: sessionID, sdp: sdp))
            case let .remoteCandidate(sessionID, candidate, index, mid):
                continuation.yield(.remoteCandidate(
                    sessionID: sessionID,
                    candidate: candidate,
                    sdpMLineIndex: index,
                    sdpMid: mid
                ))
            case let .sessionEnded(_, reason):
                sessionID = nil
                isNegotiating = false
                continuation.yield(.sessionEnded(reason: reason))
            case let .failed(failure):
                continuation.yield(.failed(Self.describe(failure)))
                return
            case .disconnected:
                continuation.yield(.sessionEnded(reason: nil))
                return
            }
        }
    }

    private func negotiate(
        among producers: [CentralRelayClient.Producer],
        _ continuation: AsyncStream<SignalingEvent>.Continuation
    ) async {
        guard sessionID == nil, !isNegotiating else { return }
        guard let robot = producers.first(where: { $0.peerID == robotPeerID }) else {
            // Absence from the list is central's way of saying offline — the lease
            // simply lapsed and nothing is producing.
            continuation.yield(.waitingForProducer)
            return
        }

        isNegotiating = true
        defer { isNegotiating = false }
        do {
            switch try await relay.startSession(with: robot.peerID) {
            case let .started(sessionID):
                self.sessionID = sessionID
            case let .rejected(reason, activeApp):
                continuation.yield(.failed(Self.describe(reason: reason, activeApp: activeApp)))
            }
        } catch {
            continuation.yield(.failed(Self.describe(error)))
        }
    }

    // MARK: - Words for what happened

    static func describe(reason: String, activeApp: String?) -> String {
        switch reason {
        case "robot_busy", "robot_busy_local_app", "robot_busy_local":
            activeApp.map { "The robot is running \($0)." }
                ?? "The robot is in use right now."
        default:
            activeApp.map { "The robot refused the session (\(reason)) while running \($0)." }
                ?? "The robot refused the session (\(reason))."
        }
    }

    private static func describe(_ failure: CentralRelayClient.Failure) -> String {
        switch failure {
        case .noToken:
            "Sign in to Hugging Face to reach this robot from outside its network."
        case .unauthorized:
            "Hugging Face refused this session. Sign in again."
        case .rateLimited:
            "Too many requests to Hugging Face. Try again in a minute."
        case let .http(code):
            "Hugging Face answered HTTP \(code)."
        }
    }

    private static func describe(_ error: any Error) -> String {
        if let failure = error as? CentralRelayClient.Failure {
            return describe(failure)
        }
        return (error as? LocalizedError)?.errorDescription ?? error.localizedDescription
    }
}

