import Foundation
@testable import ReachyKit
import Testing

/// A data channel that answers whatever a test scripts, and records what it was
/// asked. Stands in for the reliable `"data"` channel the robot opens.
private final class FakeDataChannel: RemoteDataChannel, @unchecked Sendable {
    private let lock = NSLock()
    private var continuation: AsyncStream<String>.Continuation?
    private(set) var sent: [String] = []
    /// Answers keyed by the command that provokes them.
    var replies: [String: String] = [:]

    func send(_ text: String) async throws {
        lock.withLock { sent.append(text) }
        guard let command = try? JSONDecoder().decode(TypeOnly.self, from: Data(text.utf8)).type,
              let reply = lock.withLock({ replies[command] })
        else { return }
        emit(reply)
    }

    func messages() -> AsyncStream<String> {
        AsyncStream { continuation in
            lock.withLock { self.continuation = continuation }
        }
    }

    /// Anything the robot says on its own — a broadcast, or a reply to something
    /// this test never sent.
    func emit(_ text: String) {
        lock.withLock { continuation }?.yield(text)
    }

    private struct TypeOnly: Decodable {
        let type: String
    }
}

@Suite("Remote control channel", .timeLimit(.minutes(1)))
struct RemoteControlChannelTests {
    private func channel(
        _ replies: [String: String] = [:],
        timeout: Duration = .seconds(5)
    ) -> (RemoteControlChannel, FakeDataChannel) {
        let fake = FakeDataChannel()
        fake.replies = replies
        return (RemoteControlChannel(channel: fake, timeout: timeout), fake)
    }

    /// The robot answers by echoing the command back. There is no request id on
    /// this channel — the echoed `command` is the whole of the correlation.
    @Test("a command is matched to its reply by the command it echoes")
    func matchesByEchoedCommand() async throws {
        let (control, fake) = channel([
            "wake_up": #"{"status":"ok","command":"wake_up","completed":true}"#,
        ])

        try await control.perform("wake_up")

        let sent = try #require(fake.sent.first)
        #expect(sent.contains("\"type\":\"wake_up\"") || sent.contains("\"type\" : \"wake_up\""))
    }

    /// A failure comes back on the same channel, as a field rather than a status
    /// code, and carries the robot's own words.
    @Test("an error reply is thrown with the robot's own message")
    func throwsTheRobotsError() async {
        let (control, _) = channel([
            "wake_up": #"{"error":"Backend not running","command":"wake_up"}"#,
        ])

        await #expect(throws: RemoteControlChannel.Failure.robot("Backend not running")) {
            try await control.perform("wake_up")
        }
    }

    /// The robot broadcasts things nobody asked for — move progress, for one — and
    /// a reply to a command still in flight must not be lost among them.
    @Test("an unsolicited message does not satisfy a pending command")
    func ignoresUnrelatedMessages() async throws {
        let (control, fake) = channel()

        async let reply: Void = control.perform("wake_up")
        try await Task.sleep(for: .milliseconds(50))
        fake.emit(#"{"type":"play_uploaded_move","upload_id":"u1","finished":true}"#)
        fake.emit(#"{"status":"ok","command":"goto_sleep","completed":true}"#)
        fake.emit(#"{"status":"ok","command":"wake_up","completed":true}"#)

        try await reply
    }

    /// Nothing on this channel says how long a command may take, and a caller left
    /// awaiting forever is worse than one told the robot went quiet.
    @Test("a command the robot never answers gives up")
    func timesOut() async {
        let (control, _) = channel(timeout: .milliseconds(100))

        await #expect(throws: RemoteControlChannel.Failure.timedOut) {
            try await control.perform("wake_up")
        }
    }

    @Test("a reply with a payload comes back decoded")
    func decodesAPayload() async throws {
        let (control, _) = channel([
            "get_state": #"""
            {"command":"get_state","state":{"body_yaw":0.5,"motor_mode":"enabled","is_move_running":false}}
            """#,
        ])

        struct State: Decodable, Equatable {
            let bodyYaw: Double
            let motorMode: String

            enum CodingKeys: String, CodingKey {
                case bodyYaw = "body_yaw"
                case motorMode = "motor_mode"
            }
        }
        struct Reply: Decodable {
            let state: State
        }

        let reply = try await control.perform("get_state", expecting: Reply.self)

        #expect(reply.state == State(bodyYaw: 0.5, motorMode: "enabled"))
    }

    /// Two commands of the same name cannot be told apart on the wire, so they are
    /// not allowed to be in flight together — the second would take the first's
    /// reply.
    @Test("the same command twice runs one after the other")
    func serialisesIdenticalCommands() async throws {
        let (control, fake) = channel([
            "wake_up": #"{"status":"ok","command":"wake_up","completed":true}"#,
        ])

        async let first: Void = control.perform("wake_up")
        async let second: Void = control.perform("wake_up")
        try await first
        try await second

        #expect(fake.sent.count == 2)
    }

    /// Commands carry parameters, and the robot's models name them its way.
    @Test("a payload is sent alongside the command type")
    func sendsAPayload() async throws {
        let (control, fake) = channel([
            "set_volume": #"{"status":"ok","command":"set_volume","completed":true}"#,
        ])

        try await control.perform("set_volume", payload: ["volume": .number(42)])

        let sent = try #require(fake.sent.first)
        let object = try JSONSerialization.jsonObject(with: Data(sent.utf8)) as? [String: Any]
        #expect(object?["type"] as? String == "set_volume")
        #expect(object?["volume"] as? Double == 42)
    }
}

import Foundation

/// The WebRTC data channel, with the WebRTC left out.
///
/// A seam rather than an `RTCDataChannel`: the protocol above it is plain JSON
/// and belongs with the rest of the daemon's vocabulary, in a module that does
/// not link a media framework.
public protocol RemoteDataChannel: Sendable {
    func send(_ text: String) async throws
    func messages() -> AsyncStream<String>
}

/// A JSON value, for command payloads whose shape the caller decides.
public enum RemoteValue: Equatable, Sendable, Encodable {
    case string(String)
    case number(Double)
    case bool(Bool)
    case array([RemoteValue])
    case object([String: RemoteValue])
    case null

    public func encode(to encoder: any Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case let .string(value): try container.encode(value)
        case let .number(value): try container.encode(value)
        case let .bool(value): try container.encode(value)
        case let .array(values): try container.encode(values)
        case let .object(values): try container.encode(values)
        case .null: try container.encodeNil()
        }
    }
}

/// Drives the robot over the reliable `"data"` channel of a WebRTC session.
///
/// This is the whole control surface of a remote session: the daemon's HTTP API
/// is not reachable from outside the robot's network, and the same commands
/// arrive here as JSON instead.
///
/// **There is no request id.** The robot answers by echoing the command back —
/// `{"status": "ok", "command": "wake_up", "completed": true}`, or
/// `{"error": "…", "command": "wake_up"}` — so a reply can only be attributed by
/// name. Two commands of the same name in flight together would be
/// indistinguishable, and this serialises them rather than guessing.
public actor RemoteControlChannel {
    public enum Failure: Error, Equatable, Sendable {
        /// The robot answered, and said no. The text is its own.
        case robot(String)
        /// Nothing came back in time. Nothing on this channel promises a deadline,
        /// so one is imposed here — a caller left awaiting forever is worse off
        /// than one told the robot went quiet.
        case timedOut
        case closed
    }

    private let channel: any RemoteDataChannel
    private let timeout: Duration
    private var reader: Task<Void, Never>?
    /// One waiter per command name, which is all the wire can distinguish.
    private var waiting: [String: CheckedContinuation<Data, any Error>] = [:]
    /// Commands already in flight under the same name. Awaited in turn.
    private var queued: [String: [CheckedContinuation<Void, Never>]] = [:]

    public init(channel: any RemoteDataChannel, timeout: Duration = .seconds(10)) {
        self.channel = channel
        self.timeout = timeout
    }

    deinit { reader?.cancel() }

    /// Sends a command and waits for the robot's answer.
    @discardableResult
    public func perform(
        _ command: String,
        payload: [String: RemoteValue] = [:]
    ) async throws -> Data {
        startReading()
        await takeTurn(for: command)
        defer { yieldTurn(for: command) }

        var body = payload
        body["type"] = .string(command)
        let text = String(decoding: try JSONEncoder().encode(body), as: UTF8.self)

        let reply = try await withThrowingTaskGroup(of: Data.self) { group in
            group.addTask { [self] in try await awaitReply(to: command, sending: text) }
            group.addTask { [timeout] in
                try? await Task.sleep(for: timeout)
                throw Failure.timedOut
            }
            defer { group.cancelAll() }
            guard let first = try await group.next() else { throw Failure.closed }
            return first
        }
        try Self.throwIfError(in: reply)
        return reply
    }

    /// The same, with the answer decoded.
    @discardableResult
    public func perform<Reply: Decodable>(
        _ command: String,
        payload: [String: RemoteValue] = [:],
        expecting _: Reply.Type
    ) async throws -> Reply {
        try JSONDecoder().decode(Reply.self, from: await perform(command, payload: payload))
    }

    private func awaitReply(to command: String, sending text: String) async throws -> Data {
        try await withCheckedThrowingContinuation { continuation in
            waiting[command] = continuation
            Task { [channel] in
                do {
                    try await channel.send(text)
                } catch {
                    resume(command, with: .failure(error))
                }
            }
        }
    }

    private func startReading() {
        guard reader == nil else { return }
        reader = Task { [channel] in
            for await text in channel.messages() {
                guard !Task.isCancelled else { return }
                await deliver(text)
            }
            await failAll(with: .closed)
        }
    }

    /// The robot also broadcasts messages nobody asked for — move progress, for
    /// one — so anything that names no pending command is simply dropped.
    private func deliver(_ text: String) {
        let data = Data(text.utf8)
        guard let command = try? JSONDecoder().decode(Echo.self, from: data).command else { return }
        resume(command, with: .success(data))
    }

    private func resume(_ command: String, with result: Result<Data, any Error>) {
        guard let continuation = waiting.removeValue(forKey: command) else { return }
        continuation.resume(with: result)
    }

    private func failAll(with failure: Failure) {
        let pending = waiting.values
        waiting = [:]
        for continuation in pending {
            continuation.resume(throwing: failure)
        }
    }

    // MARK: One command of a name at a time

    private func takeTurn(for command: String) async {
        guard waiting[command] != nil || queued[command] != nil else {
            queued[command] = []
            return
        }
        await withCheckedContinuation { continuation in
            queued[command, default: []].append(continuation)
        }
    }

    private func yieldTurn(for command: String) {
        guard var line = queued[command], !line.isEmpty else {
            queued[command] = nil
            return
        }
        let next = line.removeFirst()
        queued[command] = line
        next.resume()
    }

    private struct Echo: Decodable {
        let command: String?
    }

    private static func throwIfError(in data: Data) throws {
        struct Reply: Decodable {
            let error: String?
        }
        if let error = try? JSONDecoder().decode(Reply.self, from: data).error, !error.isEmpty {
            throw Failure.robot(error)
        }
    }
}

