    var body = payload
    body["type"] = .string(command)
    let text = String(decoding: try JSONEncoder().encode(body), as: UTF8.self)

    // A timer that fails the waiter, rather than a task group racing the
    // waiter against a sleep. The group would have to await both children
    // before it could exit, and a continuation nothing resumes has no way to
    // let it — one continuation with exactly four ways to be resumed (reply,
    // send failure, deadline, closed channel) has no such corner.
    let deadline = Task { [timeout] in
        try? await Task.sleep(for: timeout)
        guard !Task.isCancelled else { return }
        await self.expire(command)
    }
    defer { deadline.cancel() }

    let reply = try await awaitReply(to: command, sending: text)
    try Self.throwIfError(in: reply)
    return reply
}

private func expire(_ command: String) {
    waiting.removeValue(forKey: command)?.resume(throwing: Failure.timedOut)
}

input.old_string:
/// Cancellation-aware on purpose. The only thing that normally resumes this
/// continuation is a reply arriving, and the timeout races it inside a task
/// group — which awaits every child before it may exit. A continuation with no
/// cancellation path would leave that group waiting for a child nobody can
/// wake, and no outer deadline can rescue it.
private func awaitReply(to command: String, sending text: String) async throws -> Data {
    try await withTaskCancellationHandler {
        try await withCheckedThrowingContinuation { continuation in
            waiting[command] = continuation
            Task { [channel] in
                do {
                    try await channel.send(text)
                } catch {
                    await self.resume(command, with: .failure(error))
                }
            }
        }
    } onCancel: {
        Task { await self.abandon(command) }
    }
}

private func abandon(_ command: String) {
    waiting.removeValue(forKey: command)?.resume(throwing: CancellationError())
}

