import ReachyKit
import SwiftUI

/// The robots this Hugging Face account can reach, wherever they are.
///
/// The other way into a robot, beside discovery on the local network — and the
/// only one that works from somewhere else. A robot that is off is absent rather
/// than listed as offline: central sweeps a peer whose lease lapsed, so presence
/// in the list *is* the online signal.
struct YourReachiesScreen: View {
    let model: YourReachiesModel
    /// Called with the robot the user picked. The session is built by whoever
    /// presented this screen — it owns the WebRTC half.
    var connect: (CentralRobot) -> Void
    var signIn: () -> Void

    var body: some View {
        List {
            if let lastRefreshError = model.lastRefreshError {
                Section {
                    Text(lastRefreshError)
                        .font(.caption)
                        .foregroundStyle(.secondary)
                }
            }

            switch model.state {
            case let .listed(robots):
                Section {
                    ForEach(robots) { robot in
                        Button {
                            connect(robot)
                        } label: {
                            RemoteRobotRow(robot: robot)
                        }
                        .buttonStyle(.plain)
                        .disabled(robot.isBusy)
                    }
                } footer: {
                    Text("Reached through Hugging Face, so these work from anywhere.")
                }
            case .loading, .signedOut, .empty, .needsSignIn, .failed:
                EmptyView()
            }
        }
        .overlay { placeholder }
        .navigationTitle("Your Reachies")
        .refreshable { await model.refresh() }
        .task { await model.load() }
    }

    @ViewBuilder
    private var placeholder: some View {
        switch model.state {
        case .loading:
            ProgressView("Asking Hugging Face")
        case .signedOut:
            ContentUnavailableView {
                Label("Not signed in", systemImage: "person.crop.circle.badge.questionmark")
            } description: {
                Text("Sign in to Hugging Face to reach robots linked to your account.")
            } actions: {
                Button("Sign in", action: signIn)
            }
        case .needsSignIn:
            // Deliberately not a Retry: the same token will be refused again.
            ContentUnavailableView {
                Label("Session expired", systemImage: "person.crop.circle.badge.exclamationmark")
            } description: {
                Text("Hugging Face refused this session. Signing in again fixes it.")
            } actions: {
                Button("Sign in again", action: signIn)
            }
        case .empty:
            ContentUnavailableView {
                Label("No Reachy online", systemImage: "wifi.slash")
            } description: {
                Text("None linked to your Hugging Face account are online.")
            } actions: {
                Button("Refresh") {
                    Task { await model.refresh() }
                }
            }
        case let .failed(reason):
            ContentUnavailableView {
                Label("Could not reach Hugging Face", systemImage: "exclamationmark.triangle")
            } description: {
                Text(reason)
            } actions: {
                Button("Try again") {
                    Task { await model.refresh() }
                }
            }
        case .listed:
            EmptyView()
        }
    }
}

/// One robot as central sees it. Deliberately does not show an address: over the
/// relay there isn't one, and the robot is identified by who owns it.
struct RemoteRobotRow: View {
    let robot: CentralRobot

    var body: some View {
        HStack(spacing: 12) {
            Image(systemName: "app.connected.to.app.below.fill")
                .font(.title2)
                .foregroundStyle(robot.isBusy ? .secondary : .tint)
                .frame(width: 32)
            VStack(alignment: .leading, spacing: 2) {
                Text(robot.displayName)
                    .font(.headline)
                    .foregroundStyle(robot.isBusy ? .secondary : .primary)
                if let subtitle {
                    Text(subtitle)
                        .font(.caption)
                        .foregroundStyle(.secondary)
                }
            }
            Spacer()
            if !robot.isBusy {
                Image(systemName: "chevron.right")
                    .font(.footnote.weight(.semibold))
                    .foregroundStyle(.tertiary)
            }
        }
        .padding(.vertical, 4)
    }
}

private extension RemoteRobotRow {
    /// Naming what holds the robot is the difference between "busy" and
    /// "broken" — the user can go and close that app.
    var subtitle: String? {
        if robot.isBusy {
            return robot.activeApp.map { "In use by \($0)" } ?? "In use"
        }
        return switch robot.transport {
        case .usb: "Online · wired"
        case .wifi, .unknown, .none: "Online"
        }
    }
}

