     public func daemonStatus() async throws -> Components.Schemas.DaemonStatus {
         let version = try await control.perform("get_version", correlation: .replyKey("version"), expecting: VersionReply.self)
         let hardware = try await control.perform("get_hardware_id", correlation: .replyKey("hardware_id"), expecting: HardwareIDReply.self)
         return Components.Schemas.DaemonStatus(
             robotName: robotName ?? "",
             state: .running,
             wirelessVersion: false,
             desktopAppDaemon: false,
             version: version.version,
             hardwareId: hardware.hardwareID
