22	final class HFSignInModel {
23	    /// Thrown by the browser seam when the user closed the sheet. Not an error to
24	    /// report: showing one tells the user off for changing their mind.
25	    struct Cancelled: Error {}
26	
27	    var pastedToken = ""
28	    private(set) var isBusy = false
29	    private(set) var errorText: String?
30	
31	    let account: HFAccount
32	    private let browser: any HFWebAuthenticating
33	
34	    init(account: HFAccount, browser: (any HFWebAuthenticating)? = nil) {
35	        self.account = account
36	        self.browser = browser ?? WebAuthenticationBrowser()
37	    }
38	
39	    /// False until the OAuth app is registered on the Hub. The pasted-token path
40	    /// stays open either way, which is why this is a question worth asking rather
41	    /// than a button that fails.
42	    var offersBrowserSignIn: Bool {
43	        account.canSignInWithBrowser
44	    }
45	
46	    func signInWithBrowser() async {
47	        guard offersBrowserSignIn else { return }
48	        errorText = nil
49	        isBusy = true
50	        defer { isBusy = false }
51	
52	        do {
53	            let url = try account.beginSignIn()
54	            let callback = try await browser.authenticate(
55	                url: url,
56	                callbackScheme: HFOAuthConfiguration.callbackScheme
57	            )
58	            await account.completeSignIn(callback: callback)
59	            if case let .failed(reason) = account.state {
60	                errorText = reason
61	            }
62	        } catch is Cancelled {
63	            account.signOut()
64	        } catch {
65	            account.signOut()
66	            errorText = Self.describe(error)
67	        }
68	    }
