70	    func signInWithPastedToken() async {
71	        let token = pastedToken.trimmingCharacters(in: .whitespacesAndNewlines)
72	        guard !token.isEmpty else { return }
73	        errorText = nil
74	        isBusy = true
75	        defer { isBusy = false }
76	
77	        await account.signIn(pastedToken: token)
78	        if case let .failed(reason) = account.state {
79	            // Left in the field on purpose: a token that was mistyped is worth
80	            // correcting rather than retyping from scratch.
81	            errorText = reason
82	        } else {
83	            pastedToken = ""
84	        }
85	    }
