import Foundation
@testable import ReachyKit
import Testing

/// The widget renders what the app last saw, because a widget extension lives for
/// seconds and cannot connect to anything itself. Everything here exists to keep
/// that honest: what was seen, and how long ago.
@Suite("Robot snapshot")
struct RobotSnapshotTests {
    private let now = Date(timeIntervalSince1970: 1_800_000_000)

    private func store() throws -> RobotSnapshotStore {
        RobotSnapshotStore(
            defaults: try #require(UserDefaults(suiteName: "RobotSnapshotTests.\(UUID().uuidString)"))
        )
    }

    private func snapshot(
        name: String? = "kitchen",
        isAwake: Bool = true,
        runningApp: String? = nil,
        takenAt: Date? = nil
    ) -> RobotSnapshot {
        RobotSnapshot(
            robotName: name,
            isAwake: isAwake,
            runningApp: runningApp,
            takenAt: takenAt ?? now
        )
    }

    @Test("a written snapshot comes back")
    func roundTrips() throws {
        let store = try store()
        let written = snapshot(runningApp: "Hand Tracker")

        store.write(written)

        #expect(store.current == written)
    }

    /// The state before a robot has ever been connected. A widget cannot invent
    /// one, and pretending otherwise is the whole failure mode here.
    @Test("an empty store knows nothing")
    func startsUnknown() throws {
        let store = try store()

        #expect(store.current == nil)
        #expect(store.state(at: now) == .unknown)
    }

    @Test("a snapshot just taken is fresh")
    func reportsFresh() throws {
        let store = try store()
        let written = snapshot()
        store.write(written)

        #expect(store.state(at: now.addingTimeInterval(60)) == .fresh(written))
    }

    /// A robot switched off does not tell anyone. Past the window the app stops
    /// claiming to know what it is doing and says only when it last looked.
    @Test("a snapshot past the freshness window is stale, not wrong")
    func reportsStale() throws {
        let store = try store()
        let written = snapshot()
        store.write(written)

        #expect(store.state(at: now.addingTimeInterval(RobotSnapshotStore.freshness + 1)) == .stale(written))
    }

    /// Exactly at the boundary still counts as fresh — the window is how long the
    /// reading is trusted for, inclusive.
    @Test("the freshness window is inclusive at its edge")
    func treatsTheBoundaryAsFresh() throws {
        let store = try store()
        let written = snapshot()
        store.write(written)

        #expect(store.state(at: now.addingTimeInterval(RobotSnapshotStore.freshness)) == .fresh(written))
    }

    /// A clock that went backwards — a timezone change, a manual correction —
    /// must not read as a reading from the future being stale.
    @Test("a snapshot dated in the future is still fresh")
    func toleratesAClockGoingBackwards() throws {
        let store = try store()
        let written = snapshot()
        store.write(written)

        #expect(store.state(at: now.addingTimeInterval(-600)) == .fresh(written))
    }

    /// Disconnecting clears it. Leaving the last reading behind would have the
    /// widget describe a robot the user deliberately let go of.
    @Test("clearing the snapshot returns to knowing nothing")
    func clears() throws {
        let store = try store()
        store.write(snapshot())

        store.clear()

        #expect(store.current == nil)
        #expect(store.state(at: now) == .unknown)
    }
}

import Foundation

/// What the app last saw of a robot, for a process that cannot look for itself.
///
/// A widget extension is woken for a moment, renders, and is gone. It can hold
/// neither the state WebSocket nor a WebRTC session, so it shows what the app
/// wrote the last time it was connected — and `takenAt` is what keeps that
/// honest rather than merely confident.
public struct RobotSnapshot: Codable, Sendable, Equatable {
    /// Nil for a robot whose daemon never answered a name — the same daemons
    /// that cannot be renamed at all.
    public let robotName: String?
    public let isAwake: Bool
    /// The app the robot is running, when it is running one.
    public let runningApp: String?
    /// When the app saw this. Not decoration: everything below turns on it.
    public let takenAt: Date

    public init(robotName: String?, isAwake: Bool, runningApp: String?, takenAt: Date) {
        self.robotName = robotName
        self.isAwake = isAwake
        self.runningApp = runningApp
        self.takenAt = takenAt
    }
}

/// Whether a snapshot is still worth stating as fact.
public enum RobotSnapshotState: Sendable, Equatable {
    /// No robot has been connected, or the last one was let go of. Nothing to
    /// show, and nothing to guess.
    case unknown
    /// Recent enough to describe in the present tense.
    case fresh(RobotSnapshot)
    /// Old enough that the robot may have been switched off since — a robot
    /// leaving does not announce itself. Say when it was seen, not what it is
    /// doing.
    case stale(RobotSnapshot)
}

/// The snapshot, in storage both processes can reach.
public struct RobotSnapshotStore {
    static let key = "ReachyKit.robotSnapshot"

    /// How long a reading is repeated as current.
    ///
    /// A robot switched off, unplugged or carried out of range tells nobody, and
    /// the app is not running to notice. Half an hour is long enough to cover a
    /// phone put down mid-session and short enough that a widget does not
    /// describe yesterday's robot in the present tense.
    public static let freshness: TimeInterval = 30 * 60

    private let defaults: UserDefaults

    /// Defaults to the shared group, which is the only store the widget can read.
    public init(defaults: UserDefaults = KnownRobots.defaults) {
        self.defaults = defaults
    }

    public var current: RobotSnapshot? {
        guard let data = defaults.data(forKey: Self.key) else { return nil }
        return try? JSONDecoder().decode(RobotSnapshot.self, from: data)
    }

    public func write(_ snapshot: RobotSnapshot) {
        guard let data = try? JSONEncoder().encode(snapshot) else { return }
        defaults.set(data, forKey: Self.key)
    }

    /// Called when the session ends: a reading left behind would have the widget
    /// describe a robot the user deliberately disconnected from.
    public func clear() {
        defaults.removeObject(forKey: Self.key)
    }

    public func state(at date: Date = Date()) -> RobotSnapshotState {
        guard let current else { return .unknown }
        // A negative age is a clock that moved backwards — a timezone change, a
        // manual correction — not a reading from the future gone stale.
        let age = date.timeIntervalSince(current.takenAt)
        return age <= Self.freshness ? .fresh(current) : .stale(current)
    }
}

