import Foundation
import ReachyKit
@testable import ReachyWidgetUI
import Testing

/// The widget's whole job is to say something true about a robot nobody is
/// currently talking to. What it must never do is state a reading it cannot
/// stand behind.
@Suite("Robot widget content")
struct RobotWidgetContentTests {
    private let now = Date(timeIntervalSince1970: 1_800_000_000)

    private func snapshot(
        name: String? = "kitchen",
        isAwake: Bool = true,
        runningApp: String? = nil,
        ageInMinutes: Double = 0
    ) -> RobotSnapshot {
        RobotSnapshot(
            robotName: name,
            isAwake: isAwake,
            runningApp: runningApp,
            takenAt: now.addingTimeInterval(-ageInMinutes * 60)
        )
    }

    @Test("with no robot ever connected it offers the app rather than a state")
    func describesTheEmptyState() {
        let content = RobotWidgetContent(state: .unknown, at: now)

        #expect(content.isStale == false)
        #expect(content.detail.localizedCaseInsensitiveContains("awake") == false)
        #expect(content.detail.localizedCaseInsensitiveContains("asleep") == false)
    }

    @Test("a fresh reading is stated in the present tense")
    func describesAnAwakeRobot() {
        let content = RobotWidgetContent(state: .fresh(snapshot()), at: now)

        #expect(content.title == "kitchen")
        #expect(content.detail.localizedCaseInsensitiveContains("awake"))
        #expect(content.isStale == false)
    }

    @Test("an asleep robot says so")
    func describesASleepingRobot() {
        let content = RobotWidgetContent(state: .fresh(snapshot(isAwake: false)), at: now)

        #expect(content.detail.localizedCaseInsensitiveContains("asleep"))
    }

    /// The one rule worth a test of its own: past the window the widget reports
    /// when it last looked, never what the robot is doing. A robot switched off
    /// an hour ago would otherwise still read as awake.
    @Test("a stale reading reports when it was taken, not what the robot is doing")
    func refusesToStateAStaleReading() {
        let content = RobotWidgetContent(state: .stale(snapshot(ageInMinutes: 120)), at: now)

        #expect(content.isStale)
        #expect(content.title == "kitchen")
        #expect(content.detail.localizedCaseInsensitiveContains("awake") == false)
        #expect(content.detail.localizedCaseInsensitiveContains("asleep") == false)
    }

    /// Daemon 1.9.0 cannot be renamed and reports an empty name, so a robot
    /// without one is the common case rather than an edge.
    @Test("a robot with no name still has something to be called")
    func namesAnUnnamedRobot() {
        let content = RobotWidgetContent(state: .fresh(snapshot(name: nil)), at: now)

        #expect(content.title.isEmpty == false)
    }

    /// The running app is the most useful thing on the widget when there is one,
    /// and it belongs in front of the plain awake/asleep reading.
    @Test("a running app is named instead of the plain state")
    func namesTheRunningApp() {
        let content = RobotWidgetContent(state: .fresh(snapshot(runningApp: "Hand Tracker")), at: now)

        #expect(content.detail.contains("Hand Tracker"))
    }
}

import Foundation
import ReachyKit

/// What the widget puts on screen, worked out from a snapshot before any view is
/// involved — so the one rule that matters here is testable without rendering
/// anything.
///
/// That rule: a reading past its window is reported as *when it was taken*, never
/// as what the robot is doing. Nothing tells this app that a robot was switched
/// off, carried out of range or unplugged, and a widget still reading "Awake" an
/// hour later is worse than one admitting it does not know.
public struct RobotWidgetContent: Equatable, Sendable {
    public let title: String
    public let detail: String
    public let symbolName: String
    /// Lets the view render a memory differently from a live reading, without
    /// having to work out which it is.
    public let isStale: Bool

    public init(title: String, detail: String, symbolName: String, isStale: Bool) {
        self.title = title
        self.detail = detail
        self.symbolName = symbolName
        self.isStale = isStale
    }

    public init(state: RobotSnapshotState, at date: Date = Date()) {
        switch state {
        case .unknown:
            self.init(
                title: "No robot",
                detail: "Open the app to connect",
                symbolName: "questionmark.circle",
                isStale: false
            )
        case let .fresh(snapshot):
            self.init(
                title: Self.name(of: snapshot),
                detail: Self.activity(of: snapshot),
                symbolName: Self.symbol(for: snapshot),
                isStale: false
            )
        case let .stale(snapshot):
            self.init(
                title: Self.name(of: snapshot),
                detail: "Last seen \(Self.age(of: snapshot, at: date))",
                symbolName: "clock.arrow.circlepath",
                isStale: true
            )
        }
    }

    /// Daemon 1.9.0 mounts no rename route and reports an empty name, so a robot
    /// without one is ordinary rather than exceptional — it still needs calling
    /// something.
    private static func name(of snapshot: RobotSnapshot) -> String {
        snapshot.robotName ?? "Reachy Mini"
    }

    /// A running app is the most useful thing there is to say, so it displaces
    /// the plain awake reading rather than crowding in beside it.
    private static func activity(of snapshot: RobotSnapshot) -> String {
        if let runningApp = snapshot.runningApp {
            return runningApp
        }
        return snapshot.isAwake ? "Awake" : "Asleep"
    }

    private static func symbol(for snapshot: RobotSnapshot) -> String {
        if snapshot.runningApp != nil {
            return "square.grid.2x2.fill"
        }
        return snapshot.isAwake ? "figure.wave" : "moon.zzz.fill"
    }

    private static func age(of snapshot: RobotSnapshot, at date: Date) -> String {
        let formatter = RelativeDateTimeFormatter()
        formatter.unitsStyle = .full
        return formatter.localizedString(for: snapshot.takenAt, relativeTo: date)
    }
}

import SwiftUI

/// The widget's face.
///
/// Deliberately free of `WidgetKit`: the container background and the timeline
/// belong to the extension, and keeping them out of here is what lets this render
/// in a preview — and therefore in the snapshot suite — like any other view.
public struct RobotWidgetView: View {
    private let content: RobotWidgetContent

    public init(content: RobotWidgetContent) {
        self.content = content
    }

    public var body: some View {
        VStack(alignment: .leading, spacing: 6) {
            Image(systemName: content.symbolName)
                .font(.title2)
                .foregroundStyle(content.isStale ? AnyShapeStyle(.secondary) : AnyShapeStyle(.tint))
            Spacer(minLength: 0)
            Text(content.title)
                .font(.headline)
                .lineLimit(1)
            Text(content.detail)
                .font(.caption)
                .foregroundStyle(.secondary)
                // Two lines because a relative date in a wordier language runs
                // past one at the small size, and a truncated "last seen" is the
                // one part of a stale reading that has to survive.
                .lineLimit(2)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .leading)
    }
}

import ReachyKit
import ReachyWidgetUI
import SwiftUI
import WidgetKit

struct RobotStatusEntry: TimelineEntry {
    let date: Date
    let content: RobotWidgetContent
}

/// Reads the snapshot the app left in the shared group. It cannot do anything
/// else: this process is woken for a moment, and a robot is reached over a
/// WebSocket or a peer connection that could not be opened, let alone settled,
/// inside that.
struct RobotStatusProvider: TimelineProvider {
    func placeholder(in _: Context) -> RobotStatusEntry {
        RobotStatusEntry(date: .now, content: RobotWidgetContent(state: .unknown))
    }

    func getSnapshot(in _: Context, completion: @escaping (RobotStatusEntry) -> Void) {
        completion(entry(at: .now))
    }

    /// Two entries, not one. The first is what is true now; the second is the
    /// moment the reading stops being trustworthy, so the widget goes stale on
    /// its own rather than repeating "Awake" for a robot switched off hours ago
    /// while the app is not running to correct it.
    func getTimeline(in _: Context, completion: @escaping (Timeline<RobotStatusEntry>) -> Void) {
        let now = Date.now
        var entries = [entry(at: now)]
        if case let .fresh(snapshot) = RobotSnapshotStore().state(at: now) {
            let expiry = snapshot.takenAt.addingTimeInterval(RobotSnapshotStore.freshness)
            if expiry > now {
                entries.append(RobotStatusEntry(
                    date: expiry,
                    content: RobotWidgetContent(state: .stale(snapshot), at: expiry)
                ))
            }
        }
        // The app reloads timelines when it learns something, so this is only the
        // floor for a phone that never opens it.
        completion(Timeline(entries: entries, policy: .after(now.addingTimeInterval(60 * 60))))
    }

    private func entry(at date: Date) -> RobotStatusEntry {
        let state = RobotSnapshotStore().state(at: date)
        return RobotStatusEntry(date: date, content: RobotWidgetContent(state: state, at: date))
    }
}

struct RobotStatusWidget: Widget {
    var body: some WidgetConfiguration {
        StaticConfiguration(kind: "RobotStatus", provider: RobotStatusProvider()) { entry in
            RobotWidgetView(content: entry.content)
                .containerBackground(.fill.tertiary, for: .widget)
                .widgetURL(ReachyWidgetLink.robot.url)
        }
        .configurationDisplayName("Reachy Mini")
        .description("Your robot's last known state.")
        .supportedFamilies([.systemSmall, .systemMedium])
    }
}

