import Foundation
@testable import ReachyKit
import Testing

/// Wake and sleep are multi-step protocols against the daemon, and the order is
/// not a detail: cutting motor power before the sleep animation finishes drops
/// the head wherever it happens to be.
@Suite("Robot power", .timeLimit(.minutes(1)))
struct RobotPowerTests {
    private final class Client: RobotAPIClient, @unchecked Sendable {
        private let lock = NSLock()
        private var calls: [String] = []
        var running: Set<String> = []
        var wakeFailure: (any Error)?

        var recorded: [String] {
            lock.lock()
            defer { lock.unlock() }
            return calls
        }

        private func record(_ call: String) {
            lock.lock()
            calls.append(call)
            lock.unlock()
        }

        func handshake() async throws -> RobotConnection.Handshake {
            try await .init(identity: .preview, status: daemonStatus())
        }

        func daemonStatus() async throws -> Components.Schemas.DaemonStatus {
            .preview(state: .running)
        }

        func wakeUp() async throws -> String {
            if let wakeFailure { throw wakeFailure }
            record("wakeUp")
            return "move-wake"
        }

        func gotoSleep() async throws -> String {
            record("gotoSleep")
            return "move-sleep"
        }

        func setMotorMode(_ mode: Components.Schemas.MotorControlMode) async throws {
            record("motors:\(mode.rawValue)")
        }

        func runningMoveUUIDs() async throws -> Set<String> {
            lock.lock()
            defer { lock.unlock() }
            return running
        }
    }

    private func power(_ client: Client) -> RobotPower {
        var configuration = RobotSession.Configuration()
        // The real delays are for a robot, not for a test runner.
        configuration.motorSettleDelay = .milliseconds(1)
        configuration.movePollInterval = .milliseconds(1)
        configuration.moveCompletionTimeout = .milliseconds(50)
        return RobotPower(client: client, configuration: configuration)
    }

    /// Motors first: the play route never touches the control mode, so an asleep
    /// robot would otherwise accept the command, play the sound and not move.
    @Test("waking enables the motors before playing the animation")
    func wakesInOrder() async throws {
        let client = Client()

        try await power(client).wake()

        #expect(client.recorded == ["motors:enabled", "wakeUp"])
    }

    /// The mirror image, and the one that matters for the hardware.
    @Test("sleeping finishes the animation before cutting power")
    func sleepsInOrder() async throws {
        let client = Client()

        try await power(client).sleep()

        #expect(client.recorded == ["gotoSleep", "motors:disabled"])
    }

    /// A move still running holds the sequence up — otherwise sleep would cut
    /// power mid-animation.
    @Test("sleeping waits for the animation the daemon is still running")
    func waitsForTheAnimation() async throws {
        let client = Client()
        client.running = ["move-sleep"]

        try await power(client).sleep()

        // The wait times out rather than hanging: parking the motors matters more
        // than proof the animation ran to the end.
        #expect(client.recorded == ["gotoSleep", "motors:disabled"])
    }

    /// An intent has no screen to put an error on, so it has to be thrown rather
    /// than swallowed the way a session stores it for a view.
    @Test("a refused wake-up is thrown, not swallowed")
    func throwsOnFailure() async {
        let client = Client()
        client.wakeFailure = ReachyKitError.backendNotRunning

        await #expect(throws: ReachyKitError.backendNotRunning) {
            try await power(client).wake()
        }
    }
}

import Foundation

/// The wake and sleep protocols, with no session around them.
///
/// `RobotSession` owns them for the app, where a failure belongs on a screen and
/// a transition has to be latched against a double tap. An App Intent has neither
/// a screen nor a second tap to guard against — it has seconds, one client, and a
/// caller that needs to be told what happened. So the protocol itself lives here
/// and both callers share it, rather than the sequence existing twice and drifting.
///
/// Neither transition is a single call: `/move/play/*` only plays an animation and
/// never touches the motor control mode, so enabling and cutting power is the
/// caller's job — and the order is what keeps the robot's head off the desk.
public struct RobotPower: Sendable {
    private let client: any RobotAPIClient
    private let configuration: RobotSession.Configuration

    public init(client: any RobotAPIClient, configuration: RobotSession.Configuration = .init()) {
        self.client = client
        self.configuration = configuration
    }

    /// Motors first, then the animation. An asleep robot accepts the play route,
    /// makes the sound and does not move, which reads as the robot ignoring you.
    public func wake() async throws {
        try await client.setMotorMode(.enabled)
        try await Task.sleep(for: configuration.motorSettleDelay)
        let uuid = try await client.wakeUp()
        await waitForMoveToFinish(uuid)
    }

    /// The animation must finish *before* power is cut, otherwise the head drops
    /// wherever it happens to be.
    public func sleep() async throws {
        let uuid = try await client.gotoSleep()
        await waitForMoveToFinish(uuid)
        try await client.setMotorMode(.disabled)
    }

    /// Polls the daemon's own running-move list until the id is gone.
    ///
    /// A timeout returns normally rather than throwing: parking the motors matters
    /// more than proof the animation ran to the end, and a remote connection
    /// reports no running moves at all by construction.
    private func waitForMoveToFinish(_ uuid: String) async {
        let deadline = ContinuousClock.now + configuration.moveCompletionTimeout
        while ContinuousClock.now < deadline {
            guard let running = try? await client.runningMoveUUIDs() else { return }
            if !running.contains(uuid) { return }
            try? await Task.sleep(for: configuration.movePollInterval)
        }
    }
}

